INSERT INTO curriculum_topics
  (id, board, exam_year, class_level, subject, unit, topic, learning_objective, source_url, source_retrieved_at, review_status, version)
VALUES
  ('topic-viii-physics-kinetic-molecular-theory', 'CISCE', NULL, 'VIII', 'Physics', 'Matter', 'Kinetic Theory, States of Matter, and Phase Transitions', 'Explain the physical behavior of solids, liquids, and gases using kinetic molecular theory and describe energy exchange during phase transitions.', 'https://cisce.org/wp-content/uploads/2025/03/UpperPrimary.pdf', '2026-10-20', 'reviewed', 1),
  ('topic-viii-physics-physical-quantities-density', 'CISCE', NULL, 'VIII', 'Physics', 'Measurement', 'Density of Irregular Solids, Fluids, and Relative Density', 'Determine the density of irregular solids and liquids using displacement apparatus and predict floatation or sinking using relative density.', 'https://cisce.org/wp-content/uploads/2025/03/UpperPrimary.pdf', '2026-10-20', 'reviewed', 1),
  ('topic-viii-physics-moment-and-pressure', 'CISCE', NULL, 'VIII', 'Physics', 'Force and Pressure', 'Turning Effect of Force, Pressure, and Fluid Thrust', 'Calculate the moment of force and pressure, investigate fluid pressure properties, and describe atmospheric pressure qualitatively.', 'https://cisce.org/wp-content/uploads/2025/03/UpperPrimary.pdf', '2026-10-20', 'reviewed', 1),
  ('topic-viii-physics-work-kinetic-potential-energy', 'CISCE', NULL, 'VIII', 'Physics', 'Energy', 'Work, Kinetic and Potential Energy, and Power', 'Define and calculate work, kinetic energy, and gravitational potential energy, examine energy transformations, and distinguish power from energy.', 'https://cisce.org/wp-content/uploads/2025/03/UpperPrimary.pdf', '2026-10-20', 'reviewed', 1),
  ('topic-viii-physics-refraction-and-curved-mirrors', 'CISCE', NULL, 'VIII', 'Physics', 'Light', 'Refraction, Spherical Mirrors, and Dispersion of White Light', 'Understand refraction, construct ray rules for concave and convex mirrors, distinguish real and virtual images, and explain dispersion via prisms.', 'https://cisce.org/wp-content/uploads/2025/03/UpperPrimary.pdf', '2026-10-20', 'reviewed', 1),
  ('topic-viii-physics-thermal-expansion-and-heat', 'CISCE', NULL, 'VIII', 'Physics', 'Heat', 'Boiling, Evaporation, and Thermal Expansion of Matter', 'Distinguish boiling from evaporation, explain linear, superficial, and volume thermal expansion, and compare expansivity across solids, liquids, and gases.', 'https://cisce.org/wp-content/uploads/2025/03/UpperPrimary.pdf', '2026-10-20', 'reviewed', 1),
  ('topic-viii-physics-pitch-frequency-loudness', 'CISCE', NULL, 'VIII', 'Physics', 'Sound', 'Pitch and Frequency, Musical Instruments, and Loudness', 'Relate pitch to frequency and loudness to amplitude, analyze sound mechanisms across instrument families, and quantify sound intensity in decibels.', 'https://cisce.org/wp-content/uploads/2025/03/UpperPrimary.pdf', '2026-10-20', 'reviewed', 1),
  ('topic-viii-physics-electrostatics-household-circuits', 'CISCE', NULL, 'VIII', 'Physics', 'Electricity', 'Static Electricity, Household Circuits, and Electrical Safety', 'Understand static charge interactions and electroscopes, analyze household electrical wiring and safety devices, and calculate energy usage in kWh.', 'https://cisce.org/wp-content/uploads/2025/03/UpperPrimary.pdf', '2026-10-20', 'reviewed', 1),
  ('topic-x-physics-turning-forces', 'CISCE', 2027, 'X', 'Physics', 'Force and Motion', 'Turning forces, equilibrium, centre of gravity, and circular motion', 'Understand torque, equilibrium conditions, centre of gravity, and circular motion dynamics under centripetal and centrifugal forces.', 'https://cisce.org/wp-content/uploads/2025/03/10.-Physics.pdf', '2026-10-20', 'reviewed', 1),
  ('topic-x-physics-work-energy-power', 'CISCE', 2027, 'X', 'Physics', 'Force, Work, Power and Energy', 'Work, mechanical energy, conservation laws, power, and conversion units', 'Define work and power, calculate kinetic and gravitational potential energy, and relate electrical, mechanical, and thermal energy units.', 'https://cisce.org/wp-content/uploads/2025/03/10.-Physics.pdf', '2026-10-20', 'reviewed', 1),
  ('topic-x-physics-machines-conservation-energy', 'CISCE', 2027, 'X', 'Physics', 'Force, Work, Power and Energy', 'Machines, mechanical advantage, velocity ratio, efficiency, levers, pulleys, and conservation of energy', 'Analyze levers, calculate pulley system performance metrics, and apply conservation of mechanical energy to falling bodies and pendulums.', 'https://cisce.org/wp-content/uploads/2025/03/10.-Physics.pdf', '2026-10-20', 'reviewed', 1),
  ('topic-x-physics-refraction-tir', 'CISCE', 2027, 'X', 'Physics', 'Light', 'Laws of refraction, refractive index, apparent depth, and total internal reflection', 'Understand refraction laws, calculate refractive index and critical angle, analyze apparent depth, and trace total internal reflection in prisms.', 'https://cisce.org/wp-content/uploads/2025/03/10.-Physics.pdf', '2026-10-20', 'reviewed', 1),
  ('topic-x-physics-lenses-spectrum-scattering', 'CISCE', 2027, 'X', 'Physics', 'Light', 'Lenses, ray diagrams, power of lens, electromagnetic spectrum, and scattering', 'Construct lens ray diagrams, solve lens and power equations, categorize the electromagnetic spectrum, and explain light scattering phenomena.', 'https://cisce.org/wp-content/uploads/2025/03/10.-Physics.pdf', '2026-10-20', 'reviewed', 1),
  ('topic-x-physics-sound', 'CISCE', 2027, 'X', 'Physics', 'Sound', 'Echoes, ultrasound applications, natural/damped/forced vibrations, and resonance', 'Calculate echo distances and sound speeds, describe sonar applications, distinguish vibration modes, and analyze resonance conditions.', 'https://cisce.org/wp-content/uploads/2025/03/10.-Physics.pdf', '2026-10-20', 'reviewed', 1),
  ('topic-x-physics-electricity', 'CISCE', 2027, 'X', 'Physics', 'Electricity and Magnetism', 'Current electricity, resistance, internal resistance, power, and domestic circuits', 'Apply Ohm''s law, evaluate series/parallel circuits and cell internal resistance, compute energy costs, and explain domestic wiring safety.', 'https://cisce.org/wp-content/uploads/2025/03/10.-Physics.pdf', '2026-10-20', 'reviewed', 1),
  ('topic-x-physics-magnetism-induction', 'CISCE', 2027, 'X', 'Physics', 'Electricity and Magnetism', 'Electromagnetism, motor effect, electromagnetic induction, AC generators, and transformers', 'Apply right-hand thumb rule and Fleming''s rules, compare DC motors and AC generators, and calculate transformer voltage and current relationships.', 'https://cisce.org/wp-content/uploads/2025/03/10.-Physics.pdf', '2026-10-20', 'reviewed', 1),
  ('topic-x-physics-heat-calorimetry', 'CISCE', 2027, 'X', 'Physics', 'Heat', 'Calorimetry, specific heat capacity, latent heat of fusion, and heat exchange', 'Apply the principle of mixtures to compute specific heat capacity and latent heat of ice fusion, and interpret phase change curves.', 'https://cisce.org/wp-content/uploads/2025/03/10.-Physics.pdf', '2026-10-20', 'reviewed', 1),
  ('topic-x-physics-modern-physics', 'CISCE', 2027, 'X', 'Physics', 'Modern Physics', 'Nuclear structure, radioactivity, alpha/beta/gamma emissions, fission, and fusion', 'Trace nuclear transmutations under alpha and beta decay, assess radiation properties and hazards, and analyze nuclear fission versus fusion.', 'https://cisce.org/wp-content/uploads/2025/03/10.-Physics.pdf', '2026-10-20', 'reviewed', 1),
  ('topic-xii-commerce-business-environment', 'CISCE', 2027, 'XII', 'Commerce', 'Business Environment', 'Business Environment and SWOT Analysis', 'Analyse the concept, features, and importance of the business environment, conduct environmental scanning across micro and macro dimensions, and evaluate strategic organizational positioning using SWOT analysis.', 'https://cisce.org/wp-content/uploads/2025/04/14.-ISC-Commerce.doc.pdf', '2026-10-20', 'reviewed', 1),
  ('topic-xii-commerce-capital-financial-planning', 'CISCE', 2027, 'XII', 'Commerce', 'Financing', 'Capital and Financial Planning', 'Assess the importance of business finance, evaluate capital sources across organizational forms, formulate financial plans, examine determinants of capital structure, and distinguish fixed from working capital.', 'https://cisce.org/wp-content/uploads/2025/04/14.-ISC-Commerce.doc.pdf', '2026-10-20', 'reviewed', 1),
  ('topic-xii-commerce-equity-preference-shares', 'CISCE', 2027, 'XII', 'Commerce', 'Financing', 'Equity and Preference Shares', 'Examine the features, merits, and limitations of equity and preference shares, compare classes of preference shares, and explain modern equity mechanisms including bonus shares, rights issues, ESOPs, sweat equity, and QIPs.', 'https://cisce.org/wp-content/uploads/2025/04/14.-ISC-Commerce.doc.pdf', '2026-10-20', 'reviewed', 1),
  ('topic-xii-commerce-debentures-loan-capital', 'CISCE', 2027, 'XII', 'Commerce', 'Financing', 'Debentures and Loan Capital', 'Explain the meaning, kinds, merits, and limitations of debentures, distinguish shares from debentures, evaluate term loans from commercial banks and financial institutions, and appraise retained earnings as long-term capital.', 'https://cisce.org/wp-content/uploads/2025/04/14.-ISC-Commerce.doc.pdf', '2026-10-20', 'reviewed', 1),
  ('topic-xii-commerce-short-term-financing-banking', 'CISCE', 2027, 'XII', 'Commerce', 'Financing', 'Short-Term Financing and Banking Services', 'Evaluate short-term financing sources including bank credit, trade credit, customer advances, factoring, and inter-corporate deposits, and assess modern digital banking mechanisms such as RTGS, NEFT, IMPS, UPI, and payment cards.', 'https://cisce.org/wp-content/uploads/2025/04/14.-ISC-Commerce.doc.pdf', '2026-10-20', 'reviewed', 1),
  ('topic-xii-commerce-management-nature-levels', 'CISCE', 2027, 'XII', 'Commerce', 'Management', 'Management Meaning, Nature and Levels', 'Analyze management as an activity, group, discipline, and process, evaluate its characteristics, importance, and objectives, and differentiate managerial functions across organizational levels.', 'https://cisce.org/wp-content/uploads/2025/04/14.-ISC-Commerce.doc.pdf', '2026-10-20', 'reviewed', 1),
  ('topic-xii-commerce-principles-of-management', 'CISCE', 2027, 'XII', 'Commerce', 'Management', 'Principles of Management', 'Examine the nature and significance of management principles, analyze Taylor''s scientific management principles, evaluate Fayol''s fourteen administrative principles, and compare their contemporary applicability.', 'https://cisce.org/wp-content/uploads/2025/04/14.-ISC-Commerce.doc.pdf', '2026-10-20', 'reviewed', 1),
  ('topic-xii-commerce-planning-organising-staffing', 'CISCE', 2027, 'XII', 'Commerce', 'Management', 'Planning, Organising and Staffing', 'Master the planning process, plan types, and limitations; evaluate functional and divisional organizational structures, delegation, and decentralisation; and execute the systematic staffing sequence from recruitment through training and development.', 'https://cisce.org/wp-content/uploads/2025/04/14.-ISC-Commerce.doc.pdf', '2026-10-20', 'reviewed', 1),
  ('topic-xii-commerce-directing-controlling-coordination', 'CISCE', 2027, 'XII', 'Commerce', 'Management', 'Directing, Controlling and Coordination', 'Examine supervision, span of control, Maslow''s motivation theory, and leadership styles; resolve communication barriers; apply the controlling process and management by exception; and recognize coordination as the essence of management.', 'https://cisce.org/wp-content/uploads/2025/04/14.-ISC-Commerce.doc.pdf', '2026-10-20', 'reviewed', 1),
  ('topic-xii-commerce-marketing-concept-functions', 'CISCE', 2027, 'XII', 'Commerce', 'Marketing', 'Marketing Concept and Functions', 'Classify markets, contrast traditional orientations with the modern customer-centric marketing philosophy, distinguish marketing from selling, and analyze the core functions and socio-economic importance of marketing.', 'https://cisce.org/wp-content/uploads/2025/04/14.-ISC-Commerce.doc.pdf', '2026-10-20', 'reviewed', 1),
  ('topic-xii-commerce-marketing-mix', 'CISCE', 2027, 'XII', 'Commerce', 'Marketing', 'The Marketing Mix (4 Ps)', 'Formulate marketing mix strategies covering product elements (branding, labelling, packaging), evaluate five core pricing methods, select distribution channels, and integrate promotion mix tools.', 'https://cisce.org/wp-content/uploads/2025/04/14.-ISC-Commerce.doc.pdf', '2026-10-20', 'reviewed', 1),
  ('topic-xii-commerce-consumer-protection', 'CISCE', 2027, 'XII', 'Commerce', 'Marketing', 'Consumer Protection', 'Explain the rationale for consumer protection, analyze statutory consumer rights and responsibilities, differentiate protection methods, evaluate the Consumer Protection Act 2019 against the 1986 Act, and describe remedies against misleading advertisements.', 'https://cisce.org/wp-content/uploads/2025/04/14.-ISC-Commerce.doc.pdf', '2026-10-20', 'reviewed', 1);
