INSERT INTO learning_modules
  (id, topic_id, title, overview, key_points_json, worked_example_json, practice_advice, review_status, version)
VALUES
  ('module-viii-physics-matter-kinetic-theory', 'topic-viii-physics-kinetic-molecular-theory', 'Matter and the Kinetic Theory of Particles', 'According to the kinetic theory, matter exists in three states of matter: solids, liquids, and gases. All matter consists of tiny particles in ceaseless, random motion, whose arrangement and intermolecular forces determine physical properties. In solids, tightly packed particles vibrate about fixed positions; in liquids, particles remain in contact but slide past one another; in gases, widely separated particles move rapidly in all directions. Heating supplies thermal energy, increasing particle kinetic energy and overcoming intermolecular attractions to drive phase changes. A solid transforms into liquid through melting (or fusion), whereas liquid reverts to solid through freezing. Liquids undergo vaporisation into gas, occurring either as quiet surface evaporation at any temperature or rapid boiling at a fixed temperature. Cooling a gas causes condensation into liquid. Additionally, substances can undergo sublimation directly from solid to gas, or deposition directly from gas to solid.', '["All matter consists of particles in continuous random motion, and their average kinetic energy increases directly with temperature.","Solids possess closely packed particles with strong cohesive forces, liquids have looser packing with fluidity, and gases have maximum intermolecular space with negligible attraction.","Evaporation is a silent surface phenomenon occurring at any temperature, whereas boiling is a rapid bulk phenomenon occurring only at a substance''s fixed boiling point.","Sublimation is the direct transition from solid to vapor upon absorbing heat, while deposition is the direct transition from vapor to solid upon cooling."]', '{"prompt":"Explain why wet clothes spread out in an open, windy corridor dry significantly faster than the same clothes bunched together in a closed room.","steps":["Identify the physical mechanism: Drying of clothes is driven by the evaporation of liquid water into the surrounding air.","Surface area effect: Spreading clothes out maximizes the exposed liquid surface area, allowing a vastly greater number of energetic water molecules to escape the liquid surface per second.","Air movement effect: In a windy corridor, moving air sweeps away water vapor accumulating directly above the fabric surface, maintaining a steep concentration gradient and preventing saturation.","Contrast with closed room: In a closed room with bunched clothes, minimal surface area is exposed, and evaporating water quickly saturates the stagnant air adjacent to the fabric, suppressing the evaporation rate."],"answer":"Spreading clothes maximizes the exposed surface area for evaporation, and ambient wind continually removes saturated vapor above the fabric, drastically accelerating evaporation compared to bunched clothes in still air."}', 'Distinguish carefully between surface phenomena like evaporation and bulk phase transitions like boiling; always explain particulate behavior using kinetic energy and intermolecular forces.', 'reviewed', 1),
  ('module-viii-physics-measurement-density', 'topic-viii-physics-physical-quantities-density', 'Measurement of Density and Floatation', 'Density is a fundamental physical property defined as mass per unit volume of a substance. In the laboratory, determining the density of an irregular solid involves measuring its mass on a balance and finding its volume by displacement with a Eureka can or measuring cylinder. To determine the density of a liquid, one finds the mass of a known volume using a graduated cylinder or a density bottle with a ground-glass stopper. Relative density compares the density of any substance to the density of pure water at 4 °C. Comparing relative density allows one to predict whether a body floats or sinks in water. An object with a relative density greater than one sinks, whereas a body with a relative density less than one floats, submerging only a fraction of its volume equal to its relative density.', '["Density is defined as mass per unit volume, with SI unit kg/m³ and CGS unit g/cm³, related by 1 g/cm³ = 1000 kg/m³.","The volume of an irregular insoluble solid equals the volume of liquid it displaces when completely submerged.","Relative density (RD) is the ratio of substance density to the density of pure water at 4 °C and is a dimensionless quantity.","The principle of floatation states that a floating body displaces a volume of liquid whose weight exactly balances the entire weight of the floating body."]', '{"prompt":"An irregular stone of mass 168 g is gently immersed into a Eureka can completely filled with water. The displaced water collected in a graduated measuring cylinder measures 60 cm³. Calculate the density of the stone in g/cm³ and in SI units (kg/m³).","steps":["State given quantities: Mass m = 168 g; Displaced volume V = 60 cm³.","By Archimedes'' principle, the volume of the immersed stone equals the volume of displaced water, so V_stone = 60 cm³.","Apply density formula: Density ρ = m / V = 168 g / 60 cm³ = 2.8 g/cm³.","Convert to SI units: 1 g/cm³ = 1000 kg/m³, hence ρ = 2.8 × 1000 = 2800 kg/m³."],"answer":"2.8 g/cm³ (or 2800 kg/m³ in SI units)"}', 'Always ensure units match: combine mass in grams with volume in cm³, or mass in kilograms with volume in m³; relative density has no units.', 'reviewed', 1),
  ('module-viii-physics-force-and-pressure', 'topic-viii-physics-moment-and-pressure', 'Turning Effect of Force and Fluid Pressure', 'When a force acts on a rigid body pivoted about a fixed point, it produces a turning effect termed the moment of force or torque. Torque equals the product of the applied force and the perpendicular distance from the pivot to the line of action of the force. Pressure represents force or thrust exerted perpendicularly per unit contact area. In static fluids, pressure increases linearly with depth, acts with equal intensity in all directions at a constant depth, and transmits throughout the fluid. Surrounding atmospheric gas also exerts immense pressure upon all terrestrial objects.', '["Moment of force (Torque) = Force × Perpendicular distance from pivot, measured in newton-meters (N m).","The Principle of Moments states that for rotational equilibrium, the sum of clockwise moments equals the sum of anticlockwise moments.","Pressure is defined as normal force (thrust) per unit surface area: P = F / A, measured in pascals (1 Pa = 1 N/m²).","Fluid pressure is given by P = h × ρ × g, depending directly on depth h, liquid density ρ, and gravitational acceleration g."]', '{"prompt":"A heavy wooden door has a width of 0.85 m. A person pushes perpendicularly against the handle located 0.80 m from the hinges with a force of 35 N. Calculate the moment of the force applied to open the door.","steps":["Identify the applied force: F = 35 N.","Identify the perpendicular distance from the axis of rotation (hinges) to the point of application: d = 0.80 m.","Apply the torque formula: Moment of force = F × d.","Calculate: Moment = 35 N × 0.80 m = 28 N m."],"answer":"28 N m"}', 'Remember that distance in moment calculations must always be perpendicular to the force vector; converting all lengths to meters avoids standard calculation errors.', 'reviewed', 1),
  ('module-viii-physics-energy-work-power', 'topic-viii-physics-work-kinetic-potential-energy', 'Work, Mechanical Energy, and Power', 'In physics, work is done only when an applied force causes displacement of an object in the direction of the force. The capacity to execute work is called energy, quantified in joules. Mechanical energy exists in two forms: kinetic energy (energy of motion, proportional to mass and velocity squared) and potential energy (energy stored by virtue of position or configuration). Gravitational potential energy depends directly on body mass, local gravitational acceleration, and elevation height. Power measures the rate of transferring energy or doing work, with one watt equaling one joule per second.', '["Work done W = Force × Displacement in the direction of force (W = F × s), with SI unit joule (1 J = 1 N m).","Kinetic energy KE = 0.5 × m × v², showing that doubling velocity quadruples kinetic energy.","Gravitational potential energy PE = m × g × h, proportional to mass, elevation, and gravitational field strength.","Power is the time rate of doing work: P = W / t, measured in watts (1 W = 1 J/s)."]', '{"prompt":"A student of mass 48 kg climbs a flight of stairs consisting of 30 steps, each 15 cm high, in 18 seconds. Taking g = 10 m/s², calculate the work done against gravity and the average power developed.","steps":["Determine total vertical height climbed: h = 30 steps × 0.15 m/step = 4.5 m.","Calculate force required against gravity (weight): F = m × g = 48 kg × 10 m/s² = 480 N.","Calculate work done: W = F × h = 480 N × 4.5 m = 2160 J.","Calculate average power developed: P = W / t = 2160 J / 18 s = 120 W."],"answer":"Work done = 2160 J; Power developed = 120 W"}', 'Do not confuse work with force; if displacement is zero (such as pushing against a stationary brick wall), the physical work done is strictly zero.', 'reviewed', 1),
  ('module-viii-physics-light-refraction-curved-mirrors', 'topic-viii-physics-refraction-and-curved-mirrors', 'Refraction of Light, Curved Mirrors, and Dispersion', 'Refraction is the bending of light rays as they pass obliquely across an interface between optical media having different optical densities, caused by changes in propagation speed. Curved mirrors represent segments cut from spherical surfaces: concave mirrors converge incident rays, while convex mirrors diverge rays. Key geometric parameters include the pole, centre of curvature, principal axis, and focal point (where f = R / 2). Concave mirrors produce either magnified real images or magnified virtual images depending on object distance. Passing white light through a triangular glass prism causes dispersion into a continuous visible spectrum.', '["Light bends towards the normal when passing from an optically rarer medium to a denser medium, and bends away from normal when traveling from denser to rarer.","For spherical mirrors, focal length equals half the radius of curvature (f = R / 2).","Concave mirrors form real, inverted images for objects beyond the focus, but yield virtual, erect, and magnified images when the object is placed between the pole and focus.","Dispersion is the splitting of composite white light into its seven constituent colors (VIBGYOR) due to differing refraction angles in a prism."]', '{"prompt":"A spherical concave mirror has a radius of curvature of 36 cm. Determine its focal length. If an illuminated object is placed 10 cm in front of the mirror (between pole and focus), describe the nature and orientation of the image formed.","steps":["State radius of curvature: R = 36 cm.","Calculate focal length using f = R / 2: f = 36 cm / 2 = 18 cm.","Compare object distance u with focal length: u = 10 cm, which is less than f (18 cm).","Recall image characteristics for an object between pole P and focus F: Rays reflect and diverge in front of the mirror; their extensions behind the mirror meet to form a virtual, erect, and magnified image."],"answer":"Focal length = 18 cm; The image formed is virtual, erect, magnified, and located behind the mirror."}', 'When tracing rays through curved mirrors, use the standard principal rays: parallel to principal axis passes through focus, and through center of curvature reflects straight back.', 'reviewed', 1),
  ('module-viii-physics-heat-expansion-phase', 'topic-viii-physics-thermal-expansion-and-heat', 'Heat Transfer, Evaporation, and Thermal Expansion', 'Heating matter increases molecular kinetic energy, causing thermal expansion across all states. Solids undergo linear, superficial and volume (cubical) expansion, whereas liquids and gases experience only volume expansion. Examining the comparative expansivity of solids, liquids and gases reveals that gases expand far more than liquids, which in turn expand significantly more than solids for a given temperature increase. These expansion differences have important everyday consequences, such as leaving expansion gaps between railway tracks, sagging overhead power cables in summer, and using bimetallic strips in thermostats. Heat energy also drives phase transformations, highlighting the fundamental distinction between boiling and evaporation. Evaporation is a quiet, cooling surface phenomenon occurring at any temperature, whereas boiling is a vigorous bulk process where vapor bubbles form throughout the liquid at a definite, fixed boiling point.', '["Thermal expansion increases with state fluidity: gases expand far more than liquids, which expand more than solids for equal temperature rises.","Solids demonstrate linear expansion (length), superficial expansion (surface area), and cubical expansion (volume).","Unequal expansion of different metals is utilized in bimetallic strips for thermostats, fire alarms, and thermal circuit breakers.","Evaporation is a cooling, surface-only phenomenon occurring at any temperature, while boiling is a bulk transition occurring throughout a liquid at a fixed temperature."]', '{"prompt":"Explain why gaps are deliberately left between consecutive steel rail sections laid on railway tracks, and what would happen during a hot summer day if these gaps were omitted.","steps":["Identify the physical principle: Steel rails undergo significant linear expansion when their temperature rises during intense summer heat.","Function of gaps: The deliberate gaps provide empty longitudinal space into which expanding steel rails can expand safely without contacting each other.","Consequence of omitting gaps: If no gap is left, opposing rail ends exert immense compressive forces on one another as they expand.","Structural outcome: These extreme compressive stresses cause the steel tracks to buckle, bend sideways, or derail passing trains."],"answer":"Expansion gaps accommodate the linear thermal expansion of steel during hot weather; omitting them causes immense compressive stresses that buckle tracks and lead to derailments."}', 'Clearly differentiate linear, superficial, and cubical expansion coefficients; always contrast evaporation and boiling across surface vs bulk, temperature range, and cooling effect.', 'reviewed', 1),
  ('module-viii-physics-sound-waves-characteristics', 'topic-viii-physics-pitch-frequency-loudness', 'Sound Characteristics, Musical Instruments, and Loudness', 'Sound is a mechanical longitudinal wave produced by vibrating bodies, characterized by amplitude, frequency, and waveform. Pitch describes how high or shrill a sound appears and depends directly on wave frequency: higher frequencies yield higher pitches. Loudness measures the subjective sensation of sound intensity produced in the ear, depending directly on vibration amplitude squared and quantified in decibels (dB). In musical acoustics, different instrument families alter pitch via physical mechanisms: altering string length and tension, changing the length of vibrating air columns in wind instruments, or adjusting membrane tension in percussion instruments.', '["Frequency is the number of complete vibrations per second, measured in hertz (Hz); pitch depends directly on frequency.","Amplitude is the maximum displacement from rest; loudness is directly proportional to the square of amplitude.","In stringed instruments, pitch increases with greater tension, shorter vibrating length, and thinner string wire.","In wind instruments, pitch increases when the vibrating air column is made shorter; in percussion, pitch rises with tighter membrane tension."]', '{"prompt":"A guitar string of length 65 cm is plucked, producing a musical note of frequency 220 Hz. When the guitarist presses a fret to reduce the vibrating string length to 44 cm under identical tension, will the pitch become higher or lower? Explain why.","steps":["Identify the physical relationship: For a stretched string under constant tension, vibration frequency is inversely proportional to vibrating length (f ∝ 1 / L).","Analyze the change: Pressing the fret shortens the active vibrating length from 65 cm to 44 cm.","Deduce frequency shift: A shorter vibrating segment oscillates back and forth more times each second, raising the vibration frequency.","Relate frequency to pitch: Because pitch is directly governed by frequency, a higher frequency corresponds to a higher, shriller pitch."],"answer":"The pitch becomes higher because shortening the vibrating string increases its natural vibration frequency."}', 'Carefully separate loudness (governed by amplitude) from pitch (governed by frequency); blowing or striking harder increases loudness, not pitch.', 'reviewed', 1),
  ('module-viii-physics-electricity-static-household', 'topic-viii-physics-electrostatics-household-circuits', 'Static Electricity, Household Circuits, and Safety', 'Electricity encompasses static electrostatics and flowing current electricity. Static electricity arises from the friction-induced transfer of electrons between insulating bodies, obeying the fundamental law of conservation of charge: charge can neither be created nor destroyed. Objects may be charged by direct conduction or electrostatic induction without contact. A gold-leaf electroscope detects and identifies electrical charges via electrostatic repulsion between its metal leaves. In nature, massive static charge separation in storm clouds discharges as lightning, safely neutralized by pointed lightning conductors providing a low-resistance path to earth. In modern homes, electrical energy is delivered through three insulated wires: live (high potential), neutral (return path), and earth (protective grounding). Safety devices such as fuses and miniature circuit breakers (MCBs) protect circuits from overcurrent and short circuits. Domestic electrical consumption is billed in commercial units known as kilowatt-hours (kWh), where 1 kWh equals one kilowatt of power consumed steadily over one hour.', '["Electrostatic charging by friction involves transfer of electrons; like charges repel while unlike charges attract.","Charging by induction creates opposite charge on the near side of a conductor without physical contact or loss of original charge.","A lightning conductor protects tall structures by offering a zero-resistance path for cloud discharges safely into deep ground.","Domestic electrical energy is measured in commercial kilowatt-hours (1 kWh = 3.6 × 10⁶ J), with safety guaranteed by earth wires and live-wire fuse connections."]', '{"prompt":"A household uses four 100 W filament lamps for 5 hours each day and an electric geyser rated at 2000 W (2 kW) for 1.5 hours daily. Calculate the total electrical energy consumed in 30 days in commercial units (kilowatt-hours, kWh).","steps":["Calculate daily energy consumed by the 4 lamps: Energy = 4 lamps × 0.1 kW × 5 h = 2.0 kWh/day.","Calculate daily energy consumed by the geyser: Energy = 2.0 kW × 1.5 h = 3.0 kWh/day.","Sum daily electrical energy consumption: Total daily energy = 2.0 kWh + 3.0 kWh = 5.0 kWh/day.","Calculate total consumption over 30 days: Monthly energy = 5.0 kWh/day × 30 days = 150 kWh."],"answer":"150 kWh (units)"}', 'Remember that fuses and switches must always be connected into the LIVE wire; connecting a fuse in the neutral wire leaves appliances live and dangerous even after the fuse blows.', 'reviewed', 1),
  ('module-x-physics-turning-forces', 'topic-x-physics-turning-forces', 'Turning Forces, Moments, and Circular Motion', 'When a force acts on a rigid body free to rotate about a fixed pivot, it produces a turning effect termed the moment of a force or torque. Torque equals the product of the force and the perpendicular distance from its line of action to the pivot. The SI unit is newton metre (N m), and the CGS unit is dyne centimetre (dyn cm). Anticlockwise moments are conventionally positive, while clockwise moments are negative. A body attains static equilibrium when both translational and rotational conditions are satisfied: resultant external force is zero, and the algebraic sum of moments about any point is zero. The principle of moments is experimentally verified using a metre rule suspended horizontally from two spring balances carrying slotted weights, where the sum of the two spring-balance readings equals the total suspended weight. The centre of gravity is the point through which the resultant weight of the body acts for any orientation. In uniform circular motion, an object moves along a circle at constant speed with continuously changing velocity, sustained by an inward centripetal force in an inertial frame.', '["Torque is defined as force multiplied by the perpendicular distance from the pivot (tau = F * d); its SI unit is N m and 1 N m = 10^7 dyn cm.","A body is in mechanical equilibrium when resultant external force is zero and clockwise moments equal anticlockwise moments; this principle of moments is experimentally verified using a metre rule suspended from two spring balances carrying slotted weights, where the two spring-balance readings sum to the total weight.","Centre of gravity is the point about which the algebraic sum of moments of the weights of all constituent particles is zero; its position depends on mass distribution and need not lie inside the material.","Uniform circular motion is accelerated motion with constant speed and variable velocity; centripetal force acts towards the centre in an inertial frame, while centrifugal force is a fictitious outward force observed in the rotating frame."]', '{"prompt":"A uniform wooden metre rule of mass 120 g is pivoted horizontally on a knife-edge placed at the 40 cm mark. Where must a mass of 80 g be suspended along the rule so that it rests in horizontal equilibrium?","steps":["Identify the weight of the uniform metre rule: since it is uniform, its weight of 120 gf acts downwards at its geometric centre, which is the 50 cm mark.","Calculate the clockwise moment about the pivot at 40 cm produced by the rule''s weight: distance = 50 cm - 40 cm = 10 cm, so clockwise moment = 120 gf * 10 cm = 1200 gf cm.","Apply the principle of moments: the anticlockwise moment must equal the clockwise moment (1200 gf cm). Let the 80 g mass be suspended at distance d to the left of the pivot (between 0 cm and 40 cm mark).","Set up the equation: 80 gf * d = 1200 gf cm, which gives d = 1200 / 80 = 15 cm to the left of the 40 cm pivot. The position on the scale is 40 cm - 15 cm = 25 cm mark."],"answer":"The 80 g mass must be suspended at the 25 cm mark."}', 'Always identify the pivot first, calculate perpendicular distances from the pivot (not from the ends of the ruler), and equate total clockwise moments to total anticlockwise moments.', 'reviewed', 1),
  ('module-x-physics-work-energy-power', 'topic-x-physics-work-energy-power', 'Work, Energy, and Power', 'Work is defined in physics as the product of the component of force along the direction of displacement and the magnitude of the displacement: W = F S cos theta. Work is positive when force and displacement are in the same direction (theta = 0°), zero when force is perpendicular to displacement (theta = 90°, as in centripetal motion), and negative when force opposes motion (e.g., friction). Power is the rate of doing work (P = W / t = F v), with SI unit watt (1 W = 1 J/s) and commercial unit horsepower (1 hp = 746 W). Mechanical energy exists as kinetic energy (energy of motion, K = 1/2 m v^2 = p^2 / 2m) and potential energy (energy of position or configuration, U = mgh for gravitational field). Energy cannot be created or destroyed; it merely transforms from one form into another. Common conversion units include the erg (1 J = 10^7 erg), calorie (1 cal = 4.186 J), kilowatt-hour (1 kWh = 3.6 * 10^6 J), and electron volt (1 eV = 1.6 * 10^-19 J).', '["Work is given by W = F S cos theta; work is zero if displacement is zero, force is zero, or displacement is perpendicular to force (cos 90° = 0).","Energy conversion factors: 1 J = 10^7 erg, 1 cal = 4.186 J, 1 kWh = 3.6 * 10^6 J, and 1 eV = 1.6 * 10^-19 J.","Gravitational potential energy is U = mgh and kinetic energy is K = (1/2)mv^2 = p^2 / (2m), where p is linear momentum.","Power is the rate of doing work (P = W/t = F * v); its SI unit is the watt (W), with multiples kW, MW, GW, and mechanical unit 1 hp = 746 W."]', '{"prompt":"An electric water pump lifts 1200 kg of water through a vertical height of 15 m in 60 s. Calculate the useful power developed by the pump in watts and in horsepower. [Take g = 10 m/s^2, 1 hp = 746 W]","steps":["Calculate the work done against gravity in lifting the water: W = m * g * h = 1200 kg * 10 m/s^2 * 15 m = 180,000 J.","Calculate power in watts by dividing work done by time taken: P = W / t = 180,000 J / 60 s = 3000 W.","Convert power from watts to horsepower: P_hp = 3000 W / 746 W/hp = 4.02 hp."],"answer":"Power = 3000 W (or 4.02 hp)"}', 'Always check the angle between force and displacement: if theta = 90°, cos theta = 0 and no work is done regardless of the force magnitude.', 'reviewed', 1),
  ('module-x-physics-machines-conservation-energy', 'topic-x-physics-machines-conservation-energy', 'Machines, Levers, Pulleys, and Energy Conservation', 'A machine overcomes a large resistive load by applying a smaller effort, alters the direction of effort, or acts as a speed multiplier. Mechanical advantage is MA = Load / Effort, and Velocity Ratio is VR = (Distance moved by effort) / (Distance moved by load). Efficiency eta is the ratio of useful work output to total work input, leading to eta = MA / VR. For ideal machines, eta = 1 (100%) and MA = VR; real machines always have eta < 1 due to friction and moving component weight. Levers are classified by relative positions: Class I has fulcrum between load and effort (MA >, =, or < 1); Class II has load between fulcrum and effort (MA > 1, force multiplier); Class III has effort between fulcrum and load (MA < 1, speed multiplier). In pulley systems, a single movable pulley has VR = 2, while a block and tackle of n pulleys has VR = n. The principle of conservation of energy states that total mechanical energy remains constant in an isolated frictionless system.', '["Efficiency is related to mechanical advantage and velocity ratio by eta = MA / VR; for an ideal machine eta = 1 (100%) and MA = VR, but in practical machines MA < VR due to friction and mass of moving parts.","Class I levers have fulcrum between load and effort (MA >, =, < 1); Class II have load between fulcrum and effort (MA > 1); Class III have effort between fulcrum and load (MA < 1, speed multiplier).","For a block and tackle system with n pulleys, the velocity ratio VR = n; if the lower pulley block has weight w, then MA = n - (w/E).","Total mechanical energy (PE + KE) remains constant during frictionless motion: in free fall, PE converts to KE such that at any point U + K = mgh; in a pendulum, energy continuously interchanges between maximum PE at extremes and maximum KE at the mean position."]', '{"prompt":"A block and tackle system has 5 pulleys. A person uses this system to lift a load of 1000 N through a vertical height of 4 m by applying an effort of 250 N. Calculate: (i) the mechanical advantage (MA), (ii) the velocity ratio (VR), and (iii) the efficiency of the pulley system.","steps":["Calculate Mechanical Advantage: MA = Load / Effort = 1000 N / 250 N = 4.","Identify the Velocity Ratio for a block and tackle system: VR = n (total number of pulleys in the system) = 5.","Calculate Efficiency: eta = MA / VR = 4 / 5 = 0.80, which corresponds to 80%."],"answer":"MA = 4, VR = 5, Efficiency = 80% (eta = 0.80)"}', 'Remember that velocity ratio depends only on machine geometry and remains constant, whereas mechanical advantage and efficiency decrease when friction increases.', 'reviewed', 1),
  ('module-x-physics-refraction-tir', 'topic-x-physics-refraction-tir', 'Refraction of Light and Total Internal Reflection', 'Refraction is the bending of light as it passes obliquely between media of different optical densities. It is governed by Snell''s law: the ratio of the sine of the angle of incidence to that of refraction is constant (mu = sin i / sin r). When entering a denser medium, light speed and wavelength decrease proportionally while frequency remains constant. Refraction causes submerged objects to appear elevated: mu = Real Depth / Apparent Depth. When viewing an object in a thick glass plate or thick mirror, multiple images are seen due to successive reflections and refractions, where the second image formed by reflection at the silvered rear surface is the brightest. When light travels from a denser to a rarer medium, the angle of refraction exceeds the angle of incidence. The angle of incidence yielding a 90° angle of refraction is the critical angle (C), where sin C = 1/mu. If the angle of incidence exceeds C, total internal reflection occurs without intensity loss, as utilized in 45°-45°-90° right-angled isosceles prisms, 60° equilateral prisms, and 30°-60°-90° prisms.', '["During refraction across media, wave frequency remains strictly constant, while wave speed and wavelength change according to mu = v1 / v2 = lambda1 / lambda2.","Refraction causes apparent elevation (mu = Real Depth / Apparent Depth); in a thick glass plate or thick mirror, multiple images are formed by partial reflection and refraction, with the image from the silvered rear surface being the brightest.","Total internal reflection requires two strict conditions: light must travel from an optically denser to a rarer medium, and the angle of incidence must exceed the critical angle (i > C).","Critical angle is related to refractive index by sin C = 1/mu; total internal reflection with zero transmission loss is utilized in 45°-45°-90°, 60° equilateral, and 30°-60°-90° prisms to deviate rays by 90° or 180° or erect images."]', '{"prompt":"A light ray travels from water of refractive index 4/3 into air. Calculate: (i) the critical angle for the water-air interface [given: arcsin(0.75) = 48.6°], and (ii) state whether a ray incident at an angle of 55° in water will undergo refraction or total internal reflection.","steps":["Apply the critical angle formula: sin C = 1 / mu = 1 / (4/3) = 3/4 = 0.75.","Find C from the given trigonometric relation: C = arcsin(0.75) = 48.6°.","Compare the angle of incidence i = 55° with the critical angle C = 48.6°: since light travels from denser water to rarer air and i = 55° > 48.6°, the ray undergoes total internal reflection."],"answer":"Critical angle C = 48.6°; the ray undergoes total internal reflection."}', 'Always remember that frequency is invariant across refraction boundaries (f = v / lambda). For total internal reflection, ensure light is traveling from denser to rarer medium before comparing i with C.', 'reviewed', 1),
  ('module-x-physics-lenses-spectrum-scattering', 'topic-x-physics-lenses-spectrum-scattering', 'Lenses, Optical Instruments, Spectrum, and Scattering', 'Spherical lenses refract light to form real or virtual images. Convex (converging) lenses have positive focal lengths, while concave (diverging) lenses have negative focal lengths. The Cartesian sign convention applies to the lens formula: 1/f = 1/v - 1/u, and linear magnification is m = v/u = Height of image / Height of object. Optical power of a lens measures its converging or diverging capacity, defined as the reciprocal of focal length in metres: P = 1/f (unit: dioptre, D). A simple magnifying glass uses a convex lens with object within focal length (u < f) to form an erect, magnified virtual image. When white light traverses a glass prism, difference in wave speeds across colours produces dispersion into a spectrum (VIBGYOR). Beyond the visible band lie infrared and ultraviolet radiations, parts of the continuous electromagnetic spectrum. Scattering by atmospheric gas molecules is described by Rayleigh''s law: scattering intensity is inversely proportional to the fourth power of wavelength (I proportional to 1/lambda^4), explaining the blue sky.', '["Lens formula is 1/f = 1/v - 1/u and magnification is m = v/u; convex lenses have positive focal length (f > 0) while concave lenses have negative focal length (f < 0).","Power of a lens is P = 1/f (f in metres), measured in dioptres (D); a convex lens has positive power, while a concave lens has negative power.","In prism dispersion, deviation decreases with increasing wavelength (delta_violet > delta_red); the electromagnetic spectrum in order of increasing wavelength is: gamma rays, X-rays, ultraviolet, visible light, infrared, microwaves, radio waves.","Rayleigh scattering intensity is inversely proportional to the fourth power of wavelength (I proportional to 1/lambda^4); shorter blue wavelengths scatter much more than longer red wavelengths, producing the blue sky."]', '{"prompt":"An object of height 4.0 cm is placed at a distance of 20 cm in front of a convex lens of focal length 12 cm. Find: (i) the position of the image, (ii) the magnification, and (iii) the height of the image.","steps":["Apply Cartesian sign convention: object distance u = -20 cm, focal length f = +12 cm.","Substitute values into the lens formula 1/f = 1/v - 1/u: 1/12 = 1/v - (1/-20) => 1/12 = 1/v + 1/20.","Rearrange to solve for 1/v: 1/v = 1/12 - 1/20 = (5 - 3)/60 = 2/60 = 1/30 => v = +30 cm (a real, inverted image formed 30 cm behind the lens).","Calculate magnification: m = v / u = (+30 cm) / (-20 cm) = -1.5.","Calculate image height: h_image = m * h_object = -1.5 * 4.0 cm = -6.0 cm (inverted, real)."],"answer":"Image distance v = +30 cm, magnification m = -1.5, image height = -6.0 cm"}', 'Never forget the negative sign on object distance u under the Cartesian sign convention. For convex lenses f is positive; for concave lenses f is negative.', 'reviewed', 1),
  ('module-x-physics-sound', 'topic-x-physics-sound', 'Sound Waves, Echoes, Resonance, and Acoustics', 'Sound is a mechanical longitudinal wave requiring a material medium for propagation. When a sound wave encounters an obstacle of large dimensions compared to its wavelength, it reflects according to the laws of reflection. The persistence of human hearing is roughly 0.1 s; consequently, a distinct echo is perceived only if the reflected sound returns at least 0.1 s after the original sound. For sound traveling at 340 m/s in air, the minimum reflector distance is d = v t / 2 = 340 * 0.1 / 2 = 17 m. Ultrasonic sound waves (frequencies above 20 kHz) have high energy and directional propagation without excessive spreading, enabling SONAR ranging, echo depth sounding, and medical ultrasonography. Vibrations of mechanical bodies are classified into: free (natural) vibrations at the body''s natural frequency, damped vibrations where amplitude decays exponentially due to dissipative friction, and forced vibrations driven by an external periodic force. When the driving frequency matches the natural frequency, resonance occurs, yielding exceptionally large vibrational amplitudes.', '["An echo requires a distinct minimum time interval of 0.1 s; the distance to the reflector is given by d = (v * t) / 2, requiring at least 17 m in air at 340 m/s.","Resonance is a special case of forced vibrations where the external driving frequency equals the natural frequency of the oscillating system, causing maximum amplitude.","Characteristics of sound: Loudness depends on amplitude squared (subjective, unit decibel dB); Pitch depends on frequency; Quality (timbre) depends on waveform and harmonics.","Ultrasound waves (frequencies > 20,000 Hz) have high energy and short wavelengths, making them ideal for SONAR distance ranging, bat navigation, and diagnostic medical imaging."]', '{"prompt":"A research ship uses SONAR to map the seabed. An ultrasonic pulse emitted downwards is reflected from the ocean floor and detected by the ship''s hydrophone 0.80 s later. If the speed of sound in seawater is 1500 m/s, calculate the depth of the ocean bed at this location.","steps":["Identify the relationship for two-way echo reflection: Total distance traveled by the sound wave = 2 * d, where d is the ocean depth.","Use the distance-speed-time formula: 2 * d = v * t => d = (v * t) / 2.","Substitute the given values: d = (1500 m/s * 0.80 s) / 2 = 1200 / 2 = 600 m."],"answer":"Depth of ocean bed = 600 m"}', 'In echo and SONAR problems, remember that the sound travels to the target and back, so the total distance is always 2d. Divide the time by 2 or halve the total distance.', 'reviewed', 1),
  ('module-x-physics-electricity', 'topic-x-physics-electricity', 'Current Electricity, Circuit Analysis, and Domestic Wiring', 'Current electricity investigates electric charges in motion. Ohm''s law states that current through a conductor is directly proportional to the potential difference across it under constant physical conditions (V = I R). Electrical resistance depends on conductor length, cross-sectional area, material resistivity, and temperature: R = rho * L / A. Superconductors exhibit zero electrical resistance below a critical transition temperature. When a real chemical cell delivers current to an external circuit, its internal resistance causes an internal voltage drop (''lost volts'' = I r), such that the terminal potential difference satisfies V = E - I r. Electrical power is given by P = V I = I^2 R = V^2 / R, and energy consumed is measured commercially in kilowatt-hours (1 kWh = 3.6 * 10^6 J). Modern household wiring employs the ring main system with appliances in parallel. Switches, fuses, and MCBs must be installed in the live wire. Modern colour coding of three-core household cable designates live as brown, neutral as light blue, and earth as green/yellow. Two-way switching in staircase wiring enables an appliance to be operated independently from two separate locations.', '["Resistance is given by R = rho * L / A; equivalent resistance is R_s = R1 + R2 for series circuits, and 1/R_p = 1/R1 + 1/R2 for parallel circuits.","For a cell of electromotive force E and internal resistance r supplying current I, terminal voltage is V = E - I r, and current is I = E / (R + r).","Commercial electrical energy is measured in kilowatt-hours (kWh, where 1 kWh = 3.6 * 10^6 J); in domestic circuits, appliances are wired in parallel, with switches, fuses, and MCBs installed in the live wire, and the three-pin plug features a longer, thicker earth pin for safety.","Modern colour coding of three-core household cable designates live as brown, neutral as light blue, and earth as green/yellow; two-way switching with staircase wiring enables an appliance to be operated independently from two different locations."]', '{"prompt":"A cell of electromotive force (emf) 6.0 V and internal resistance 1.5 ohms is connected across an external resistor of resistance 8.5 ohms. Calculate: (i) the total circuit resistance, (ii) the current drawn from the cell, and (iii) the terminal voltage across the cell.","steps":["Calculate total circuit resistance: R_total = R + r = 8.5 ohms + 1.5 ohms = 10.0 ohms.","Calculate the current using Ohm''s law for the complete circuit: I = E / (R + r) = 6.0 V / 10.0 ohms = 0.60 A.","Calculate terminal potential difference using V = E - I r: V = 6.0 V - (0.60 A * 1.5 ohms) = 6.0 - 0.90 = 5.1 V."],"answer":"R_total = 10.0 ohms, I = 0.60 A, V = 5.1 V"}', 'Remember that terminal voltage V equals emf E only when no current is drawn (open circuit). In closed circuits, V = E - Ir. Always install switches and fuses in the live wire, never in the neutral wire.', 'reviewed', 1);
INSERT INTO learning_modules
  (id, topic_id, title, overview, key_points_json, worked_example_json, practice_advice, review_status, version)
VALUES
  ('module-x-physics-magnetism-induction', 'topic-x-physics-magnetism-induction', 'Electromagnetism, Motors, Induction, and Transformers', 'Oersted demonstrated that electric currents generate surrounding magnetic fields, whose direction follows the right-hand thumb rule. Concentrated fields are produced by solenoids, forming electromagnets whose strength increases with current, turn density, and a soft iron core. When a current-carrying conductor is placed in an external magnetic field, it experiences a mechanical force given by Fleming''s left-hand rule (motor effect). In a DC motor, this magnetic torque rotates an armature coil, while a split-ring commutator reverses current direction every half-turn to sustain unidirectional rotation. Conversely, Faraday discovered electromagnetic induction: moving a conductor through a magnetic field induces an electromotive force, with induced current direction determined by Fleming''s right-hand rule and Lenz''s law. In an AC generator, slip rings maintain continuous alternating output. Alternating current (AC) allows efficient high-voltage transmission with minimal power loss. Domestic AC supply in India is 50 Hz, so the current reverses direction 100 times per second. Voltage stepping is achieved using transformers: N_s / N_p = V_s / V_p = I_p / I_s.', '["Magnetic field direction around a current-carrying conductor is given by the Right-Hand Thumb Rule; field strength inside a solenoid is maximized with a soft iron core.","Fleming''s Left-Hand Rule predicts mechanical motion in motors (Thumb = Force, Forefinger = Field, Middle finger = Current); split-ring commutators reverse current each half-turn.","Fleming''s Right-Hand Rule predicts induced current in generators; domestic AC supply in India is 50 Hz, so the current reverses direction 100 times per second; Lenz''s law confirms conservation of energy.","For an ideal transformer, turns ratio matches voltage ratio and inversely matches current ratio: V_s / V_p = N_s / N_p = I_p / I_s; cores are laminated soft iron to minimize eddy currents and hysteresis."]', '{"prompt":"An ideal step-down transformer converts a mains supply voltage of 240 V to 12 V to power a low-voltage lamp. If the primary coil contains 1200 turns and the secondary delivers a current of 4.0 A: (i) find the number of turns in the secondary coil, and (ii) calculate the current drawn by the primary coil.","steps":["Apply the transformer turns-to-voltage ratio equation: N_s / N_p = V_s / V_p.","Calculate the secondary turns N_s: N_s = N_p * (V_s / V_p) = 1200 * (12 V / 240 V) = 1200 * (1/20) = 60 turns.","Use the power conservation relation for an ideal transformer (P_in = P_out => V_p * I_p = V_s * I_s) to find primary current I_p: I_p = (V_s * I_s) / V_p = (12 V * 4.0 A) / 240 V = 48 / 240 = 0.20 A."],"answer":"N_s = 60 turns, I_p = 0.20 A"}', 'Never confuse Fleming''s rules: use the Left-Hand Rule for motors (converting electrical energy to mechanical work) and the Right-Hand Rule for generators (generating induced current from mechanical motion).', 'reviewed', 1),
  ('module-x-physics-heat-calorimetry', 'topic-x-physics-heat-calorimetry', 'Calorimetry, Specific Heat Capacity, and Latent Heat of Fusion', 'Calorimetry deals with the quantitative measurement of heat energy exchange during physical and thermal processes. Temperature indicates average molecular kinetic energy, whereas heat is total thermal internal energy transferred. Specific heat capacity (c) is heat energy required to raise the temperature of unit mass of a substance by 1 K or 1°C (unit: J kg^-1 K^-1). Heat capacity C'' = m c is the heat needed for the whole body (unit: J/K). The principle of calorimetry states: Heat lost by hot body = Heat gained by cold body in an isolated system. Water possesses an exceptionally high specific heat capacity (4200 J kg^-1 K^-1), making it an ideal coolant and moderator of coastal climate. Latent heat is energy absorbed or released at constant temperature during a phase change; specific latent heat of fusion (L_f) for ice is 336 J/g (3.36 * 10^5 J/kg). During phase transition, temperature remains strictly constant.', '["Principle of calorimetry: Heat lost by hot body = Heat gained by cold body (m1 * c1 * Delta T1 = m2 * c2 * Delta T2) in a thermally isolated system.","Heat capacity is C'' = Q / Delta T = m * c (unit: J/K or J/°C), while specific heat capacity c is the heat required per unit mass per degree rise in temperature (unit: J kg^-1 K^-1 or J g^-1 °C^-1).","Water''s high specific heat capacity (4200 J kg^-1 K^-1) explains coastal moderate climates, its role in automobile cooling, and farmers flooding crops to avert frost damage.","Latent heat of fusion of ice is L_f = 336 J/g (3.36 * 10^5 J/kg); phase changes occur at constant temperature, appearing as flat horizontal plateaus on a heating curve."]', '{"prompt":"A piece of copper of mass 200 g at 100°C is dropped into 150 g of water at 20°C contained in a copper calorimeter of mass 100 g. If the final steady temperature of the mixture is 28°C, calculate the specific heat capacity of copper. [Specific heat capacity of water = 4.2 J g^-1 °C^-1]","steps":["Identify heat lost by copper piece: Q_lost = m_cu * c_cu * (T_initial - T_final) = 200 g * c_cu * (100 - 28)°C = 200 * 72 * c_cu = 14,400 * c_cu.","Identify heat gained by water: Q_water = m_w * c_w * (T_final - T_initial) = 150 g * 4.2 J/(g °C) * (28 - 20)°C = 150 * 4.2 * 8 = 5040 J.","Identify heat gained by copper calorimeter: Q_cal = m_cal * c_cu * (T_final - T_initial) = 100 g * c_cu * (28 - 20)°C = 800 * c_cu.","Apply principle of calorimetry (Heat lost = Total heat gained): 14,400 * c_cu = 5040 + 800 * c_cu => 13,600 * c_cu = 5040 => c_cu = 5040 / 13,600 = 0.37 J g^-1 °C^-1."],"answer":"Specific heat capacity of copper = 0.37 J g^-1 °C^-1 (or 370 J kg^-1 K^-1)"}', 'In calorimetry, separate equations for heat lost and heat gained clearly. Remember that during phase change (melting), Q = mL without any temperature change Delta T.', 'reviewed', 1),
  ('module-x-physics-modern-physics', 'topic-x-physics-modern-physics', 'Radioactivity, Nuclear Radiations, and Nuclear Energy', 'An atomic nucleus comprises positively charged protons and neutral neutrons, collectively called nucleons. An atom is represented as ^A_Z X, where atomic number Z denotes proton count and mass number A denotes total nucleon count. Radioactivity is a spontaneous nuclear phenomenon wherein an unstable nucleus disintegrates without external initiation, emitting ionizing radiation to attain stability. It is completely unaffected by external physical or chemical factors. Disintegration yields three distinct radiations: alpha particles (^4_2 He), beta particles (^0_-1 e), and gamma rays. Alpha emission reduces mass number by 4 and atomic number by 2; beta emission leaves mass number unchanged while increasing atomic number by 1; gamma emission releases excess energy without altering A or Z. Radiation hazards mandate lead shielding and safety measures. Nuclear energy is liberated through fission, such as uranium-235 splitting upon absorbing a neutron (^235_92 U + ^1_0 n -> ^141_56 Ba + ^92_36 Kr + 3 ^1_0 n + energy), and fusion, such as hydrogen isotopes uniting (^2_1 H + ^3_1 H -> ^4_2 He + ^1_0 n + energy), both converting mass defect into energy via E = (Delta m)c^2.', '["Radioactivity is a purely nuclear phenomenon unaffected by physical or chemical changes; unstable nuclei spontaneously emit alpha, beta, or gamma radiation.","Decay transformations: Alpha decay reduces A by 4 and Z by 2 (^A_Z X -> ^(A-4)_(Z-2) Y + ^4_2 He); Beta decay keeps A unchanged and increases Z by 1 (^A_Z X -> ^A_(Z+1) Y + ^0_-1 e); Gamma emission alters neither A nor Z.","Properties: Alpha has maximum ionizing power and least penetration; Beta has intermediate ionization and penetration; Gamma has least ionization and highest penetrating power.","Nuclear fission splits a heavy nucleus with neutrons (^235_92 U + ^1_0 n -> ^141_56 Ba + ^92_36 Kr + 3 ^1_0 n + energy); nuclear fusion combines light nuclei (^2_1 H + ^3_1 H -> ^4_2 He + ^1_0 n + energy); both convert mass defect into energy via E = Delta m * c^2."]', '{"prompt":"A radioactive parent nucleus ^238_92 U undergoes a sequence of radioactive decays by emitting two alpha particles and two beta particles to form a stable daughter nucleus ^A_Z D. Determine the mass number A and atomic number Z of the daughter nucleus.","steps":["Analyze the effect of emitting two alpha particles: each alpha particle (^4_2 He) reduces mass number A by 4 and atomic number Z by 2. For two alpha particles: Delta A = -2 * 4 = -8, and Delta Z = -2 * 2 = -4.","Analyze the effect of emitting two beta particles: each beta particle (^0_-1 e) changes mass number A by 0 and increases atomic number Z by 1. For two beta particles: Delta A = 0, and Delta Z = +2 * 1 = +2.","Calculate final mass number A: A = 238 - 8 + 0 = 230.","Calculate final atomic number Z: Z = 92 - 4 + 2 = 90."],"answer":"Mass number A = 230, Atomic number Z = 90 (Thorium-230)"}', 'When tracking nuclear decay series, calculate the change in mass number A first to find the number of alpha particles, then determine the atomic number Z to deduce the number of beta particles.', 'reviewed', 1),
  ('module-xii-commerce-business-environment', 'topic-xii-commerce-business-environment', 'Business Environment: Scanning, Dimensions, and SWOT Analysis', 'The business environment encompasses the totality of external forces, factors, and institutions that operate beyond the direct control of an individual enterprise but exert a profound influence on its operational continuity, strategic choices, and economic performance. It is characterized by dynamic change, pervasive uncertainty, structural complexity, interrelatedness among diverse components, and geographic relativity. Modern corporate management relies systematically on environmental scanning—the disciplined practice of monitoring, analyzing, and interpreting external signals—to identify emerging market opportunities and detect threatening vulnerabilities before they impair commercial viability. A comprehensive diagnostic analysis requires examining the micro environment (immediate operational actors including customers, competitors, suppliers, marketing intermediaries, and the public) alongside the macro environment (overarching economic, social, technological, political, and legal dimensions). Strategic planners synthesize these external findings with the firm''s internal capabilities through SWOT analysis. By systematically mapping internal Strengths and Weaknesses against external Opportunities and Threats, organizations formulate robust strategic postures that optimize competitive advantage and foster long-term resilience.', '["The business environment is dynamic, uncertain, complex, interrelated, and relative across diverse geographical jurisdictions.","Environmental scanning enables early identification of opportunities for first-mover advantage and provides critical warning signals against external threats.","The micro environment comprises immediate task-related actors (customers, competitors, suppliers), while the macro environment spans broad socio-economic and legal forces.","SWOT analysis aligns internal organizational strengths and weaknesses with external market opportunities and threats to craft viable strategies."]', '{"prompt":"An electric two-wheeler manufacturer in Pune evaluates its business environment. The Union Government announces a 15% production-linked incentive (PLI) subsidy for domestic battery cell assembly. Concurrently, interest rates on consumer retail loans rise by 1.50%, and an unexpected global shortage of lithium carbonate escalates battery pack import costs by 20%. The firm possesses an automated battery-pack assembly unit and holds ₹120 crore in liquid cash reserves, but lacks long-term vendor supply agreements for imported rare-earth components. Classify each of these five environmental factors under the SWOT analysis framework from the manufacturer''s strategic viewpoint.","steps":["Classify the Union Government''s 15% PLI subsidy: This is a favorable external regulatory and economic condition that the firm can exploit to lower unit production costs, representing an Opportunity (O).","Classify the 1.50% hike in retail consumer loan interest rates: This is an adverse external macroeconomic development that increases vehicle financing costs for retail consumers, potentially depressing market demand, representing a Threat (T).","Classify the global lithium carbonate shortage escalating component costs by 20%: This is an adverse external supply-chain disruption arising from the global economic and international environment, representing a Threat (T).","Classify the firm''s proprietary automated battery-pack assembly plant and ₹120 crore liquid cash reserves: These represent proprietary internal tangible assets and financial liquidity that confer competitive efficiency, representing Strengths (S).","Classify the lack of long-term vendor contracts for imported rare-earth components: This is an internal operational vulnerability in procurement strategy that exposes the firm to supply shocks, representing a Weakness (W)."],"answer":"Strengths: automated battery assembly plant and ₹120 crore cash reserves; Weaknesses: lack of long-term vendor contracts for rare-earth components; Opportunities: 15% PLI subsidy scheme; Threats: 1.50% consumer loan interest rate hike and 20% cost escalation from global lithium shortages."}', 'When executing SWOT classification in examination questions, always distinguish the locus of control: Strengths and Weaknesses are strictly internal to the firm, whereas Opportunities and Threats stem entirely from the external micro or macro environment.', 'reviewed', 1),
  ('module-xii-commerce-capital-financial-planning', 'topic-xii-commerce-capital-financial-planning', 'Financial Planning, Capital Structure, and Capital Requirements', 'Capital functions as the lifeblood of every commercial enterprise, financing the acquisition of productive assets and sustaining ongoing operations. The nature and accessibility of financial sources vary markedly across business structures: sole proprietorships and partnerships rely primarily on personal savings, retained operating profits, and trade credit, whereas joint stock companies mobilize extensive long-term resources by issuing shares and debentures to institutional and public investors. Financial planning serves as the operational blueprint for enterprise finance, pursuing two primary objectives: ensuring that adequate funds are available whenever required and preventing the wasteful accumulation of unallocated, idle cash. Capital structure refers to the permanent long-term financing mix of an enterprise, represented by the ratio between owned capital (equity and preference shares, retained earnings) and borrowed capital (debentures, long-term institutional loans). Selecting an optimal capital structure requires balancing financial risk, trading on equity (financial leverage), interest coverage ratios, cost of capital, and regulatory cash-flow restrictions. Concurrently, enterprises must accurately evaluate and finance their twin capital requirements: fixed capital for long-term tangible assets and working capital to maintain continuous liquidity throughout the operating cycle.', '["Sole traders and partnerships face capital limits tied to personal wealth, whereas corporate entities access broad capital markets.","Financial planning ensures funds are available at the right time in the right amounts while avoiding idle surplus capital.","Capital structure is the permanent ratio of owned funds (equity) to borrowed funds (debt) chosen to maximize shareholder return.","Fixed capital funds long-term non-current assets, while working capital funds current assets to support the operating cycle."]', '{"prompt":"Zenith Engineering Ltd. requires total capital of ₹50,00,000 for a manufacturing expansion. The management is evaluating two alternative financing plans to determine which yields a higher Return on Equity (ROE). Plan A: Issue 5,00,000 Equity Shares of ₹10 each at par (100% equity). Plan B: Issue 2,50,000 Equity Shares of ₹10 each (₹25,00,000) and raise ₹25,00,000 through 10% Debentures. The company expects Earnings Before Interest and Taxes (EBIT) of ₹10,00,000 per annum, and the corporate income tax rate is 30%. Calculate Earnings Per Share (EPS) under both plans and explain whether trading on equity is advantageous.","steps":["Compute Plan A (All Equity): Interest = ₹0. Earnings Before Tax (EBT) = EBIT - Interest = ₹10,00,000 - ₹0 = ₹10,00,000. Corporate Tax (30%) = ₹3,00,000. Profit After Tax (PAT) = ₹10,00,000 - ₹3,00,000 = ₹7,00,000. Number of equity shares = 5,00,000. EPS = PAT / Number of Shares = ₹7,00,000 / 5,00,000 = ₹1.40 per share.","Compute Plan B (Debt-Equity Mix): Annual Debenture Interest = 10% of ₹25,00,000 = ₹2,50,000. EBT = EBIT - Interest = ₹10,00,000 - ₹2,50,000 = ₹7,50,000. Corporate Tax (30%) = ₹2,25,000. PAT = ₹7,50,000 - ₹2,25,000 = ₹5,25,000. Number of equity shares = 2,50,000. EPS = PAT / Number of Shares = ₹5,25,000 / 2,50,000 = ₹2.10 per share.","Evaluate Trading on Equity: The overall return on total investment is EBIT / Total Capital = ₹10,00,000 / ₹50,00,000 = 20%. Because the return on capital employed (20%) significantly exceeds the contractual cost of debt (10%), employing borrowed capital elevates the EPS from ₹1.40 to ₹2.10. Hence, trading on equity is favorable."],"answer":"Plan A yields an EPS of ₹1.40; Plan B yields an EPS of ₹2.10. Trading on equity is distinctly advantageous to equity shareholders under Plan B."}', 'Remember that trading on equity only enhances earnings per share when the firm''s Return on Capital Employed (ROCE) is strictly higher than the pre-tax interest rate on debt. If ROCE falls below the interest rate, financial leverage will drastically depress EPS.', 'reviewed', 1),
  ('module-xii-commerce-equity-preference-shares', 'topic-xii-commerce-equity-preference-shares', 'Share Capital: Equity, Preference Shares, and Modern Equity Instruments', 'Share capital constitutes the permanent ownership foundation of a joint stock enterprise. Equity shares, frequently termed ordinary shares, represent the foundational risk-bearing capital. Equity shareholders enjoy comprehensive voting rights and control over corporate governance, participate in unlimited surplus profits via variable dividends, but rank last upon company winding-up. In contrast, preference shares provide hybrid investment characteristics: they carry a preferential entitlement to receive a fixed rate of dividend before any return is paid to equity holders, alongside a prior claim on capital repayment during liquidation. However, preference shares typically do not confer general voting privileges unless dividend arrears accumulate across specified statutory periods. Preference shares encompass cumulative and non-cumulative, participating and non-participating, and redeemable and convertible varieties. Beyond conventional equity issuances, contemporary corporate finance employs dynamic equity mechanisms: Rights issues grant existing shareholders the pre-emptive legal entitlement to purchase newly issued shares pro rata at a concessional price. In contrast, Bonus shares represent the capitalisation of accumulated free reserves distributed pro rata to existing shareholders at zero cash cost. Furthermore, Employee Stock Option Plans (ESOPs) and Sweat Equity incentivize managerial performance, while Qualified Institutional Placements (QIPs) accelerate equity mobilisation from institutional investors.', '["Equity shares provide permanent risk capital with full voting control, variable dividend returns, and residual claim on liquidation.","Preference shares guarantee fixed dividend rates and liquidation priority, but lack voting rights under normal circumstances.","Rights issues provide cash via pre-emptive rights to existing shareholders, whereas bonus shares capitalise free reserves at zero cash cost.","Modern corporate instruments include ESOPs (employee retention), sweat equity (intellectual contribution), and QIPs (institutional issuance)."]', '{"prompt":"Kalyan Textiles Ltd. has an authorized capital of ₹50,00,000 and an issued equity share capital of 2,00,000 equity shares of ₹10 each fully paid. The company resolves to capitalize ₹4,00,000 of its General Reserve by issuing bonus shares in the ratio of 1:5 (one new bonus share for every five existing shares held). An institutional investor owns 15,000 shares. Compute the total bonus shares issued by the company, the number of bonus shares received by this investor, and the total cash received by Kalyan Textiles Ltd. from this bonus issue.","steps":["Compute total bonus shares issued by the company: 2,00,000 existing shares × (1 / 5) = 40,000 equity shares of ₹10 each, absorbing ₹4,00,000 of General Reserve.","Calculate bonus shares received by the institutional investor: 15,000 shares held × (1 / 5) = 3,000 bonus shares.","Determine cash inflow to the company: Bonus shares represent the capitalisation of existing undistributed profits and are distributed free of cost to shareholders; hence cash inflow is ₹0."],"answer":"The company issues 40,000 bonus shares; the investor receives 3,000 bonus shares; and the company receives ₹0 in cash."}', 'Carefully differentiate between bonus shares and rights shares: bonus shares are fully paid free shares funded by capitalizing retained reserves without cash inflow, whereas rights issues require shareholders to subscribe cash for new shares pro rata.', 'reviewed', 1),
  ('module-xii-commerce-debentures-loan-capital', 'topic-xii-commerce-debentures-loan-capital', 'Debentures, Institutional Lending, and Retained Earnings', 'Enterprises mobilize debt capital alongside equity to build balanced capital structures that optimize the overall cost of capital. A debenture is a written instrument issued under the common seal of a company acknowledging debt, containing an express promise to pay a specified principal sum at a stated date and periodic interest at a fixed coupon rate. Debentures may be secured by a fixed or floating charge, or unsecured; redeemable or perpetual; convertible into shares or non-convertible; and registered or bearer. For corporate issuers, debentures provide substantial advantages: interest payments are tax-deductible operational expenses that lower the effective cost of debt, and debenture holders possess no voting rights, protecting equity voting control. However, debentures impose rigid legal obligations to disburse periodic interest regardless of operating earnings, heightening solvency risks during business downturns. Beyond market-traded debentures, enterprises secure long-term capital through term loans from commercial banks and specialised development financial institutions (such as IFCI, IDBI, and State Financial Corporations - SFCs). Complementing external credit, retained earnings (ploughing back of profits) provide an internal, non-dilutive equity source that requires neither legal issue expenditures nor mandatory dividend servicing.', '["Debentures represent borrowed debt capital carrying a contractual obligation of fixed periodic interest and principal repayment.","Debenture interest is tax-deductible, reducing corporate tax liability, but defaults trigger severe legal liquidation risks.","Term loans from commercial banks and financial institutions provide tailored medium-to-long term project finance backed by collateral.","Retained earnings serve as internal self-financing that avoids issue costs, interest burdens, and ownership dilution."]', '{"prompt":"Vanguard Chemicals Ltd. requires ₹20,00,000 of fresh capital to construct a wastewater treatment plant. The company faces a choice between issuing 12% Debentures at par or issuing 10% Preference Shares of ₹100 each. The corporate tax rate is 30%. Compute the annual post-tax cost in rupees to Vanguard Chemicals Ltd. under both financing avenues and explain the tax-shield effect of debentures.","steps":["Compute annual interest on debentures: 12% of ₹20,00,000 = ₹2,40,000 gross annual interest.","Calculate tax shield on debenture interest: Because debenture interest is a tax-deductible business expense, tax savings = Gross Interest × Tax Rate = ₹2,40,000 × 0.30 = ₹72,000. Therefore, net post-tax cash cost of debentures = ₹2,40,000 - ₹72,000 = ₹1,68,000.","Compute dividend on preference shares: 10% of ₹20,00,000 = ₹2,00,000. Because preference dividends are paid out of post-tax profits as an appropriation of profit, they enjoy zero corporate income tax deductibility. Hence, post-tax cash cost of preference shares = ₹2,00,000."],"answer":"The post-tax annual cash outflow for debentures is ₹1,68,000, compared to ₹2,00,000 for preference shares. The debenture interest provides a ₹72,000 annual corporate tax shield."}', 'In competitive calculations, never deduct taxes from preference dividends. Preference dividends are appropriations of profit after tax, whereas debenture interest is an expense charged before tax, yielding a substantial corporate tax shield.', 'reviewed', 1),
  ('module-xii-commerce-short-term-financing-banking', 'topic-xii-commerce-short-term-financing-banking', 'Short-Term Financing and Modern Electronic Banking Services', 'Short-term financing funds current assets and maintains continuous operating liquidity across production cycles spanning up to twelve months. Enterprises utilize diverse trade-based and institutional short-term financing sources. Trade credit allows businesses to defer payment for purchases, while customer advances provide interest-free operating cash against pending deliveries. Companies also mobilize funds through public deposits, which invite short-term unsecured borrowings directly from the public, and instalment credit, which enables immediate acquisition of assets with payment spread over scheduled instalments. Specialised short-term avenues include factoring—where trade debts are assigned to a financial intermediary for immediate liquidity—and Inter-Corporate Deposits (ICDs), consisting of unsecured loans exchanged between creditworthy companies for call, three-month, or six-month tenures. Furthermore, commercial bank assistance facilitates operations through cash credit limits, overdrafts against current accounts, and commercial bill discounting. Concurrently, contemporary financial management relies on digital banking infrastructures to orchestrate rapid cash disbursements: Real Time Gross Settlement (RTGS) settles high-value transactions continuously on an individual gross basis, whereas National Electronic Funds Transfer (NEFT) processes transactions in deferred half-hourly batches. For instantaneous retail payments, the Unified Payments Interface (UPI) and Immediate Payment Service (IMPS) enable 24x7 smartphone-based account transfers, supported by stored-value e-wallets, ATMs, and payment cards.', '["Short-term financing sources include trade credit, customer advances, public deposits, and instalment credit, providing operational liquidity and enabling asset acquisition on deferred payment terms.","Factoring monetizes accounts receivable through financial intermediaries, while Inter-Corporate Deposits (ICDs) enable flexible short-term borrowing and lending between creditworthy corporations.","Commercial bank assistance provides crucial short-term working capital through cash credit facilities, current account overdrafts, and discounting commercial bills of exchange.","Modern digital banking systems distinguish continuous gross clearing (RTGS) from batch settlement (NEFT), instant smartphone payments (UPI, IMPS), and payment card mechanisms."]', '{"prompt":"Sundaram Logistics Ltd. holds trade receivables of ₹10,00,000 due from clients in 90 days. To meet an immediate fuel payroll commitment, the company factors these receivables with Canbank Factors Ltd. under a non-recourse factoring agreement. The factor advances 80% of the invoice value immediately, levies a factoring commission of 2% on total invoice value, and charges an annualized interest rate of 12% on the advance for the 90-day period. Compute the immediate cash proceeds received by Sundaram Logistics Ltd. upon factoring (assume 360 days in a commercial year).","steps":["Compute the initial advance amount: 80% of ₹10,00,000 = ₹8,00,000.","Calculate the factor''s upfront commission: 2% of total invoice value (₹10,00,000) = ₹20,000.","Calculate interest on the advance for 90 days: Advance (₹8,00,000) × 12% per annum × (90 / 360 days) = ₹8,00,000 × 0.12 × 0.25 = ₹24,000.","Determine immediate net cash proceeds released to the firm: Initial Advance (₹8,00,000) - Factoring Commission (₹20,000) - Interest Charge (₹24,00,000) = ₹8,00,000 - ₹44,000 = ₹7,56,000."],"answer":"Sundaram Logistics Ltd. receives net immediate cash proceeds of ₹7,56,000 against its ₹10,00,000 trade receivables."}', 'Clearly differentiate RTGS from NEFT: RTGS processes transactions on an ongoing gross basis with immediate settlement (traditionally designed for high-value transfers), whereas NEFT pools transfers into deferred batches processed at hourly or half-hourly intervals.', 'reviewed', 1),
  ('module-xii-commerce-management-nature-levels', 'topic-xii-commerce-management-nature-levels', 'Concept, Nature, Objectives, and Levels of Management', 'Management is the universal process of planning, organising, staffing, directing, and controlling organizational resources to achieve corporate objectives effectively and efficiently. Efficiency denotes completing activities with minimal resource wastage, while effectiveness signifies attaining targets on schedule. Management can be examined as an operational process, an economic activity, an executive group of decision-makers, and a specialized academic discipline. Hallmarks include being goal-oriented, pervasive, continuous, multidimensional, dynamic, and an intangible force. Crucially, the nature of management integrates aspects of a science, an art, and an emerging profession. Management is an inexact or social science because it features a systematised body of knowledge and testable principles developed through observation and experimentation, though human behaviour precludes universal predictive exactness. Management is an art because it requires personalised skill, creativity, and continuous practice to apply principles to specific situations. Furthermore, management is an emerging profession characterised by specialised knowledge, representative bodies such as the All India Management Association (AIMA), and formal codes of conduct, though it lacks statutory licensing and restricted entry. Management objectives balance enterprise goals (survival, profit, growth) with social and personal goals. Vertically, management functions across three tiers: top management conceives broad policies, middle management coordinates departments, and lower supervisory management oversees operative execution and safety.', '["Management combines effectiveness (achieving goals on schedule) with efficiency (minimising resource costs) across organizational survival, profitability, growth, social responsibilities, and employee development.","Management is viewed through four distinct lenses: as an operational process of interrelated functions, an economic activity, a collective group of managers, and an academic discipline.","The nature of management encompasses a Science (systematised knowledge and testable principles), an Art (personalised skill, creativity, and practice), and an emerging Profession (specialised knowledge, representative bodies such as AIMA, and codes of conduct, but no statutory licensing).","The managerial hierarchy comprises Top management (overarching policies and strategy), Middle management (departmental coordination), and Supervisory management (operative oversight, output quality, and workforce safety)."]', '{"prompt":"Orion Electronics produces commercial air-purifiers. During the festive season, the production manager receives a target order of 5,000 units to be completed in 30 days at a standard cost of ₹4,000 per unit. To ensure delivery on the 30th day, the manager operates double shifts with heavy overtime wage payouts, producing all 5,000 units on schedule but incurring an actual cost of ₹4,800 per unit. Analyze the production manager''s performance in terms of ''effectiveness'' and ''efficiency''.","steps":["Define effectiveness: Effectiveness measures whether the assigned task was completed and target outputs achieved within the stipulated deadline (goal achievement).","Assess manager''s effectiveness: Because the target order of 5,000 units was completed and delivered within the required 30-day window, the manager was effective.","Define efficiency: Efficiency evaluates the relationship between inputs and outputs, focusing on completing tasks at minimum cost and without resource wastage.","Assess manager''s efficiency: Because the actual cost of ₹4,800 per unit exceeded the standard budgeted cost of ₹4,000 per unit due to overtime wages, resources were utilized sub-optimally. The manager was inefficient."],"answer":"The production manager was effective because the production target was achieved on schedule, but was inefficient due to cost overruns exceeding the standard unit cost."}', 'Never treat efficiency and effectiveness as identical: Effectiveness is about ''doing the right things'' to reach target goals on time, whereas Efficiency is about ''doing things right'' by minimizing cost and resource consumption.', 'reviewed', 1),
  ('module-xii-commerce-principles-of-management', 'topic-xii-commerce-principles-of-management', 'Classical Management Principles: Scientific Management and Administrative Theory', 'Management principles are fundamental truths and guidelines that guide managerial decision-making and organizational behavior. These principles are universal yet flexible, formed through systematic empirical observation and experimentation, and contingent upon prevailing situational dynamics. The foundation of classical management thought rests on two seminal contributors: F.W. Taylor and Henri Fayol. Taylor pioneered Scientific Management, focusing on shop-floor shop operations to eliminate industrial waste, establish standard operating procedures, and maximize labor productivity. Taylor''s framework emphasizes four core principles—Science not Rule of Thumb, Harmony not Discord, Cooperation not Individualism, and Development of each person to their greatest efficiency—supported by techniques such as functional foremanship, standardisation, time and motion studies, and differential piece-wage systems. Conversely, Henri Fayol developed Administrative Theory, focusing on top-down enterprise governance. Fayol articulated fourteen administrative principles, including Division of Work, Authority and Responsibility, Discipline, Unity of Command (one subordinate receives orders from only one superior), Unity of Direction, Subordination of Individual Interest, Remuneration, Centralisation, Scalar Chain (with the ''gang plank'' exception for emergency cross-communication), Order, Equity, Stability of Tenure, Initiative, and Esprit de Corps. While Taylor revolutionized shop-floor operational engineering, Fayol provided a universal administrative blueprint for executive leadership.', '["Management principles are flexible, empirically derived, universal guidelines that adapt dynamically to situational contexts.","Taylor''s Scientific Management optimizes shop-floor production via scientific task analysis, time-motion studies, and wage incentives.","Fayol''s 14 principles guide executive administration, emphasizing Unity of Command, Unity of Direction, and the Scalar Chain.","Unity of Command mandates a single boss to prevent confusion, while Unity of Direction requires one unified plan for related activities."]', '{"prompt":"An executive at an industrial logistics hub observes persistent operational conflict: freight handlers frequently receive contradictory dispatch orders from the Warehouse Manager and the Fleet Operations Director simultaneously, leading to delays and missed deliveries. Additionally, when a critical logistical bottleneck occurred, the assistant dispatcher had to send formal memorandums sequentially through five bureaucratic managerial levels before receiving approval to reroute freight trucks. Identify which of Henri Fayol''s administrative principles was violated in the first scenario, and which administrative mechanism Fayol provided to resolve delays in the second scenario.","steps":["Analyze the first scenario: Freight handlers receive conflicting orders from two separate superiors simultaneously. This directly breaches Henri Fayol''s principle of ''Unity of Command'', which asserts that an employee should receive orders from and be accountable to only one direct superior.","Analyze the second scenario: Communication in an emergency is delayed by rigid adherence to the formal hierarchical chain of authority (the Scalar Chain).","Identify Fayol''s solution for the second scenario: Fayol devised the ''Gang Plank''—a direct horizontal communication channel enabling two employees of equal rank across different departments to communicate directly during operational emergencies, bypassing vertical scalar channels while keeping superiors informed."],"answer":"The first scenario violates the principle of Unity of Command; the mechanism to resolve delays in the second scenario is Fayol''s Gang Plank."}', 'Clearly distinguish Unity of Command from Unity of Direction: Unity of Command prevents dual subordination by insisting on ''one employee, one superior'', whereas Unity of Direction ensures unified group efforts through ''one head, one plan'' for a set of activities sharing the same objective.', 'reviewed', 1);
INSERT INTO learning_modules
  (id, topic_id, title, overview, key_points_json, worked_example_json, practice_advice, review_status, version)
VALUES
  ('module-xii-commerce-planning-organising-staffing', 'topic-xii-commerce-planning-organising-staffing', 'Management Processes I: Planning, Organisation Structures, and Staffing', 'Planning, organising, and staffing form the structural triad of administrative management. Planning bridges the divide between current reality and future targets by setting objectives, developing premises, identifying and evaluating alternatives, selecting a course of action, and establishing reviews. Plans range from strategies and policies to procedures, rules, programmes, and budgets. Organising establishes structural harmony by identifying activities, departmentalising tasks, allocating resources, and defining authority lines. Enterprises adopt functional structures based on occupational specialisation or divisional structures based on product lines or territories. Crucially, organising distinguishes formal organisation from informal organisation: a formal organisation is a deliberately designed structure with defined authority and official communication channels created by management to achieve enterprise objectives, whereas an informal organisation consists of spontaneous social relationships and informal communication networks that arise alongside the formal structure. Within these frameworks, delegation entrusts authority, responsibility, and accountability to immediate subordinates, while decentralisation systematically disperses decision-making power across all organizational echelons. Staffing ensures the enterprise is manned by competent human capital through human resource planning, recruitment from internal or external sources, candidate selection, job-specific training, and executive development.', '["Planning establishes objectives, premises, and courses of action, structured through varied plan types ranging from enterprise policies to quantitative budgets.","Organising designs functional or divisional structures, distinguishing formal organisation (deliberately designed structure with defined authority and official communication channels) from informal organisation (spontaneous social relationships and informal communication that arise alongside the formal structure).","Delegation is the downward transfer of authority from a superior to an immediate subordinate, whereas decentralisation is the systematic, enterprise-wide dispersal of decision-making authority.","Staffing ensures competent human capital through human resource planning, recruitment from internal/external pools, multi-stage selection, job-specific training, and executive career development."]', '{"prompt":"Apex Consumer Goods manufactures three distinct product lines: cosmetics, footwear, and packaged snacks. The Managing Director delegates authority for new supplier approvals to the General Manager of Purchasing, who in turn delegates purchase contract signing authority up to ₹5,00,000 to the Senior Purchase Officer. During an audit, an unapproved purchase order of ₹4,50,000 was signed that resulted in severe financial loss. The General Manager argues that because authority was delegated to the Senior Purchase Officer, the General Manager bears zero accountability to the Managing Director. Evaluate this administrative argument using principles of delegation.","steps":["Define delegation elements: Delegation comprises three elements: Authority (right to decide), Responsibility (obligation to perform), and Accountability (answerability for final outcomes).","Analyze the principle of delegation: While a superior can delegate authority and entrust responsibility to a subordinate, accountability is absolute and cannot be delegated (the Principle of Absoluteness of Accountability).","Evaluate the General Manager''s stance: The General Manager remains answerable and accountable to the Managing Director for the performance of the purchasing function and any losses resulting from tasks delegated to subordinates."],"answer":"The General Manager''s argument is invalid. Under the principle of absoluteness of accountability, a superior remains fully answerable to higher management for all duties delegated to subordinates."}', 'Always remember the cardinal rule of delegation: Authority can be delegated, Responsibility can be shared, but Accountability can NEVER be delegated or shifted. A superior remains fully answerable to their own superior for the performance of subordinates.', 'reviewed', 1),
  ('module-xii-commerce-directing-controlling-coordination', 'topic-xii-commerce-directing-controlling-coordination', 'Management Processes II: Directing, Controlling Systems, and Coordination', 'Directing, controlling, and coordination bring organizational blueprints to life. Directing initiates human action through four core elements: supervision, motivation, leadership, and communication. Supervision oversees operative work, guided by span of control (the number of subordinates a manager can effectively direct). Motivation unleashes human potential, conceptualized by A.H. Maslow''s Hierarchy of Needs, which advances sequentially from physiological and safety needs to social affiliation, self-esteem, and self-actualisation. Effective leadership mobilizes collective effort through autocratic (authoritarian), democratic (participative), or laissez-faire (free-rein) styles. Directing requires overcoming semantic, psychological, organizational, and personal communication barriers. Controlling completes the managerial loop by measuring actual performance against predetermined standards, computing deviations, and implementing corrective action. Advanced controlling applies Management by Exception (MBE)—concentrating managerial scrutiny strictly on significant negative deviations that exceed established tolerance limits. Permeating every function, coordination harmonizes individual and departmental activities, justly recognized not as a discrete managerial function, but as the enduring essence of management that prevents interdepartmental friction and unifies enterprise efforts.', '["Directing drives operational execution through supervision, motivational systems, leadership styles, and open communication channels.","Maslow''s hierarchy states human needs progress sequentially from basic physiological and safety requirements to self-actualisation.","The controlling sequence measures actuals against standards, applying Management by Exception (MBE) to significant deviations.","Coordination is the overarching essence of management that binds planning, organising, staffing, directing, and controlling into unified action."]', '{"prompt":"Sigma Precision Ball-Bearings Ltd. produces automotive ball bearings with an engineered diameter tolerance of 25.00 mm ± 0.05 mm (acceptable range: 24.95 mm to 25.05 mm). The company employs the principle of Management by Exception (MBE) in its quality control system. During a shift inspection, three batches record the following average bearing diameters: Batch X = 25.02 mm; Batch Y = 25.04 mm; Batch Z = 25.12 mm. Explain which batch should be brought to the immediate attention of the Plant General Manager under Management by Exception, and justify why Batches X and Y should not be escalated.","steps":["Define Management by Exception (MBE): MBE is a management control principle stating that managers should focus their attention on significant deviations from established standards, while minor deviations within acceptable tolerance ranges should be handled by operating supervisors.","Evaluate Batch X (25.02 mm) and Batch Y (25.04 mm): Both batches fall within the acceptable tolerance range of 24.95 mm to 25.05 mm (deviations of +0.02 mm and +0.04 mm are within the ±0.05 mm tolerance limit). These minor operational variations should be handled locally by shop-floor technicians.","Evaluate Batch Z (25.12 mm): The diameter deviation is +0.12 mm, which significantly exceeds the permissible tolerance limit of ±0.05 mm. This critical quality breach indicates potential machinery malfunction or tool wear that risks defective deliveries.","Apply MBE: Only Batch Z represents an exceptional deviation requiring immediate escalation to the Plant General Manager."],"answer":"Only Batch Z (25.12 mm) should be reported to the Plant General Manager because its deviation (+0.12 mm) breaches the permissible tolerance band (±0.05 mm); Batches X and Y fall safely within standard tolerance limits."}', 'When answering questions on Management by Exception (MBE), emphasize that an attempt to control everything results in controlling nothing. Management must establish clear tolerance limits and investigate only significant variances.', 'reviewed', 1),
  ('module-xii-commerce-marketing-concept-functions', 'topic-xii-commerce-marketing-concept-functions', 'Foundations of Marketing: Philosophies, Market Classification, and Core Functions', 'Marketing is the dynamic socio-economic process by which individuals and organizations satisfy customer needs and wants through creating, offering, and exchanging products and services of value. Markets can be classified based on geographic scope (local, regional, national, international), types of buyers (consumer goods markets versus industrial goods markets), goods traded (commodity versus capital goods), and delivery terms (spot versus future contracts). Over the past century, commercial philosophies have evolved through distinct orientations: the Production Concept (emphasizing cheap, abundant factory output); the Product Concept (focusing on engineering quality and continuous performance enhancements); the Selling Concept (relying on aggressive promotional salesmanship to push pre-manufactured inventories); the Marketing Concept (customer-centric orientation identifying target market needs and delivering superior customer satisfaction); and the Societal Marketing Concept (harmonizing customer satisfaction, corporate profits, and long-term societal well-being). A fundamental conceptual distinction separates marketing from selling: selling focuses on seller requirements and converting pre-manufactured goods into cash, whereas marketing focuses on customer desires and creating goods that satisfy those needs. The execution of marketing encompasses twelve core functions, including marketing research, product development, standardisation and grading, packaging, branding, customer support, pricing, promotion, storage, and transportation.', '["Markets are classified by geographical scope, customer type (consumer vs industrial), commodities traded, and contract timing.","Management philosophies evolved from production and selling orientations to the customer-centric marketing and societal concepts.","Selling focuses on pushing manufactured inventory for immediate sales volume, while marketing builds long-term customer satisfaction.","Core marketing functions include market research, standardisation, grading, packaging, branding, pricing, physical distribution, and promotion."]', '{"prompt":"An electric home-appliance manufacturer discovers through consumer research that urban households desire a dishwasher designed for traditional Indian cookware with heavy oil stains. Company A builds a standard European dishwasher in high volume and uses hard-sell telemarketing tactics to sell down its factory inventory. Company B designs an appliance with specialized high-temperature pressure jets specifically for traditional Indian cookware and guarantees five years of on-site service support. Classify the business philosophies of Company A and Company B.","steps":["Analyze Company A''s approach: Company A manufactures a standardized product without researching target market needs and relies on aggressive sales promotion and hard-sell tactics to buy a company''s pre-manufactured goods. This reflects the ''Selling Concept''.","Analyze Company B''s approach: Company B identifies customer requirements through market research, designs a customized product to satisfy those specific needs, and provides ongoing customer service support. This reflects the ''Marketing Concept''.","Compare both concepts: Company A''s focus is on the product and seller''s need to generate cash through volume, whereas Company B''s focus is on customer satisfaction as the path to sustainable enterprise profitability."],"answer":"Company A illustrates the Selling Concept (product-centric with aggressive promotion); Company B exemplifies the Marketing Concept (customer-centric with value creation)."}', 'In comparative exam questions, remember that Selling begins AFTER goods are produced and focuses on sales volume, whereas Marketing begins long BEFORE production starts (with market research) and continues well after the sale (with customer support).', 'reviewed', 1),
  ('module-xii-commerce-marketing-mix', 'topic-xii-commerce-marketing-mix', 'Marketing Mix Strategies: Product, Price, Place, and Promotion', 'The marketing mix represents the tactical toolkit—traditionally formulated as the Four Ps (Product, Price, Place, Promotion)—that an enterprise coordinates to elicit desired responses from its target market. Product decisions encompass tangible goods and intangible services, managed through three interrelated elements: Branding creates distinctive brand identity, trade names, and trademarks; Packaging provides physical containment and protection across primary, secondary, and transport tiers while acting as a silent salesman; and Labelling delivers statutory information, directions, and batch identification. Price is the sole marketing mix element that generates revenue, calibrated through methods including cost-plus pricing, penetration pricing (low initial entry pricing to capture share), price skimming (high introductory prices for innovative products), going-rate pricing, and psychological pricing. Place (Distribution) manages channels (zero-level direct marketing versus one, two, or three-tier intermediary networks) and logistics including warehousing, inventory control, and transport. Finally, Promotion communicates value and drives purchases through four integrated components: Advertising (non-personal paid communication), Personal Selling (interpersonal oral presentations), Sales Promotion (short-term incentives like rebates and coupons), and Publicity/Public Relations.', '["The marketing mix combines Product, Price, Place, and Promotion strategies to generate target customer responses.","Product elements integrate distinctive branding, multi-tiered functional packaging, and informative statutory labelling.","Pricing strategies range from cost-plus and going-rate methods to market skimming and market penetration.","Physical distribution manages intermediary channels and logistics, supported by advertising, personal selling, and sales promotions."]', '{"prompt":"An innovative consumer electronics startup launches an advanced noise-cancelling smart headphone featuring proprietary biometric sensors. The direct manufacturing and component cost is ₹4,000 per unit, while fixed research and development overheads total ₹50,00,000. In Year 1, the company targets premium early-adopters with minimal initial competition, pricing the device at ₹16,000 per unit. In Year 3, as competitors enter the market with comparable features, the company drops the retail price to ₹7,500 to expand into mass college-student markets. Identify the pricing strategy applied in Year 1 versus Year 3, and explain the marketing logic.","steps":["Analyze Year 1 pricing: The firm launches a pioneering innovative product at an elevated initial price (₹16,00,000) targeting affluent early adopters who value premium features and are less price-sensitive. This is ''Price Skimming''.","Analyze Year 3 pricing: As competitive entry intensifies and the market matures, the firm cuts its price substantially to ₹7,500 to capture price-sensitive mass-market share. This transition adopts a competitive mass-market pricing posture.","Identify the economic rationale: Price skimming in Year 1 allows the innovator to recover high R&D expenditures rapidly before rival substitutes appear; subsequent price reductions defend market share against new entrants."],"answer":"Year 1 reflects a Price Skimming strategy to maximize early margins and recover R&D costs; Year 3 reflects a Penetration/Competitive Pricing strategy to secure mass-market volume."}', 'Clearly distinguish Price Skimming from Penetration Pricing: Skimming sets high initial prices to skim premium margins from early adopters before competition arrives; Penetration sets low initial prices to capture large market share rapidly.', 'reviewed', 1),
  ('module-xii-commerce-consumer-protection', 'topic-xii-commerce-consumer-protection', 'Consumer Protection: Rights, Responsibilities, CPA 2019, and Adjudication', 'Consumer protection safeguards buyers against unfair trade practices, adulteration, and misleading advertisements through self-help, legislative measures, and consumer organisations. The Consumer Protection Act 2019 modernised consumer jurisprudence, covering offline and e-commerce purchases while excluding commercial resale. The Act establishes six rights: Safety, Information, Choice, Heard, Redressal, and Consumer Education, balanced by responsibilities such as obtaining cash memos and checking quality marks. The Central Consumer Protection Authority (CCPA) regulates consumer rights violations and false advertisements, imposing fines up to ₹10 lakh for a first offence and ₹50 lakh for subsequent contraventions. For dispute adjudication, the Act provides a three-tier quasi-judicial Consumer Disputes Redressal machinery: the District Commission, State Commission, and National Commission. Under the Consumer Protection (Consumer Disputes Redressal Commissions) Rules 2021, the revised pecuniary jurisdiction is: District Commission up to ₹50 lakh; State Commission above ₹50 lakh up to ₹2 crore; and National Commission above ₹2 crore. Appeals progress sequentially up through this machinery to the Supreme Court.', '["Consumers are protected through self-help vigilance, statutory enactments, and active consumer associations or NGOs, covering both offline retail and online e-commerce transactions.","The Consumer Protection Act 2019 guarantees six basic rights (Safety, Information, Choice, Heard, Redressal, Consumer Education) alongside key responsibilities such as obtaining cash memos and inspecting standard certification marks.","The Central Consumer Protection Authority (CCPA) regulates unfair practices and misleading advertisements, penalizing violations up to ₹10 lakh for a first offence and ₹50 lakh for subsequent offences.","Adjudication operates through a three-tier machinery with revised pecuniary jurisdiction under the 2021 Rules: District Commission (claims up to ₹50 lakh), State Commission (above ₹50 lakh up to ₹2 crore), and National Commission (above ₹2 crore)."]', '{"prompt":"Sunita purchases a branded electric geyser for ₹18,000 from an online e-commerce marketplace. The vendor supplies a defective unit with substandard electrical insulation that causes an electric shock. The manufacturer refuses to refund the purchase price or repair the geyser. Furthermore, the celebrity endorser on national television claimed the appliance had ''100% shockproof aerospace insulation''. Identify the statutory consumer rights infringed, explain whether Sunita can maintain an action against the e-commerce platform under the Consumer Protection Act 2019, and outline the statutory liability of the celebrity endorser.","steps":["Identify infringed rights: The supply of an electrically hazardous appliance violates the Right to Safety (protection against goods hazardous to life and health) and the Right to Redressal (entitlement to seek fair compensation or replacement for defective goods).","Analyze e-commerce standing under CPA 2019: Unlike the 1986 Act, the Consumer Protection Act 2019 explicitly brings digital e-commerce transactions and online platforms under its regulatory ambit. Sunita can file an electronic complaint (e-daakhil) against both the vendor and the marketplace.","Determine endorser liability: Under the 2019 Act, the Central Consumer Protection Authority (CCPA) can investigate misleading advertisements. The celebrity endorser can be penalized up to ₹10 lakh for a first offence (and up to ₹50 lakh for subsequent offences) and prohibited from endorsing any product for up to one year, unless they can prove due diligence was conducted."],"answer":"The Right to Safety and Right to Redressal were breached. The CPA 2019 covers e-commerce platforms directly, and the CCPA can fine the celebrity endorser up to ₹10 lakh and impose a promotional ban for misleading claims."}', 'When answering consumer protection questions, highlight the institutional role of the Central Consumer Protection Authority (CCPA), the inclusion of e-commerce within the 2019 Act, and the consumer''s essential legal responsibility to insist on a cash memo.', 'reviewed', 1);
INSERT INTO questions
  (id, topic_id, question_type, prompt, options_json, answer_json, rationale, difficulty, requires_rough_work, review_status, version)
VALUES
  ('viii-physics-matter-q1', 'topic-viii-physics-kinetic-molecular-theory', 'single_choice', 'Which of the following correctly describes the particles in a liquid state according to kinetic molecular theory?', '[{"id":"a","label":"Particles are separated by enormous distances and exert completely negligible intermolecular attractions on each other."},{"id":"b","label":"Particles possess zero kinetic energy and are held entirely stationary by electrostatic forces."},{"id":"c","label":"Particles remain in close contact but have enough kinetic energy to slide past one another, giving liquids a definite volume but no fixed shape."},{"id":"d","label":"Particles are fixed in a rigid crystal lattice and can only vibrate about fixed equilibrium points."}]', '{"choice":"c"}', 'In liquids, intermolecular forces are strong enough to keep particles close together (yielding a definite volume), yet weak enough to allow particles to slide past one another and assume the shape of the container.', 1, 0, 'reviewed', 1),
  ('viii-physics-matter-q2', 'topic-viii-physics-kinetic-molecular-theory', 'single_choice', 'When solid camphor or dry ice is heated at normal atmospheric pressure, it transitions directly to the vapor state without forming a liquid. What is this phase change called, and what is its reverse process?', '[{"id":"a","label":"Sublimation, and its reverse is deposition."},{"id":"b","label":"Vaporization, and its reverse is condensation."},{"id":"c","label":"Liquefaction, and its reverse is solidification."},{"id":"d","label":"Fusion, and its reverse is freezing."}]', '{"choice":"a"}', 'The direct phase change from solid to gas upon heating is sublimation. The reverse transition from vapor directly to solid upon cooling is known as deposition (or desublimation).', 2, 0, 'reviewed', 1),
  ('viii-physics-matter-q3', 'topic-viii-physics-kinetic-molecular-theory', 'single_choice', 'Why does a person feel an intense cooling sensation when rubbing surgical spirit or perfume onto their forearm skin?', '[{"id":"a","label":"Volatile spirit molecules absorb latent heat of vaporization directly from the skin to evaporate, lowering skin temperature."},{"id":"b","label":"Liquid spirit blocks infrared radiation emitted by the skin, trapping coolness."},{"id":"c","label":"Chemical components of the spirit chemically freeze the epidermal skin cells."},{"id":"d","label":"The spirit reacts exothermically with atmospheric nitrogen, chilling the air above the skin."}]', '{"choice":"a"}', 'Spirit is highly volatile. To evaporate, its high-energy molecules absorb the necessary latent heat of vaporization from the skin surface, thereby extracting heat energy and creating a pronounced cooling sensation.', 2, 0, 'reviewed', 1),
  ('viii-physics-matter-q4', 'topic-viii-physics-kinetic-molecular-theory', 'numeric', 'A sample of pure solid naphthalene at 20 °C is continuously heated until it melts completely into liquid naphthalene at its normal melting point of 80 °C. What is the temperature change (in kelvin) undergone by the sample?', NULL, '{"value":60,"tolerance":0.1}', 'Temperature change on the Celsius scale equals ΔT = 80 °C - 20 °C = 60 °C. Because a temperature interval of 1 °C is identical to an interval of 1 K, the temperature change in kelvin is also 60 K.', 2, 1, 'reviewed', 1),
  ('viii-physics-matter-q5', 'topic-viii-physics-kinetic-molecular-theory', 'numeric', 'During an experiment, water is heated until it boils steadily at 100 °C. The heating source supplies thermal energy at a steady rate of 450 W for exactly 120 seconds while water vaporizes at 100 °C. How much thermal energy (in kilojoules) was supplied during this boiling period?', NULL, '{"value":54,"tolerance":0.5}', 'Energy supplied Q = Power × time = 450 W × 120 s = 54,000 J. In kilojoules, Q = 54,000 / 1000 = 54 kJ.', 2, 1, 'reviewed', 1),
  ('viii-physics-measurement-q1', 'topic-viii-physics-physical-quantities-density', 'numeric', 'An empty relative density bottle has a mass of 24.5 g. When filled completely with water, its mass is 49.5 g. When filled with an unknown oil, its mass is 44.5 g. Calculate the density of the oil in g/cm³.', NULL, '{"value":0.8,"tolerance":0.02}', 'Mass of water = 49.5 g - 24.5 g = 25.0 g. Since water density is 1.0 g/cm³, bottle volume = 25.0 cm³. Mass of oil = 44.5 g - 24.5 g = 20.0 g. Density of oil = 20.0 g / 25.0 cm³ = 0.80 g/cm³.', 2, 1, 'reviewed', 1),
  ('viii-physics-measurement-q2', 'topic-viii-physics-physical-quantities-density', 'numeric', 'A solid rectangular block of wood measures 10 cm × 6 cm × 4 cm. Its mass is measured on a beam balance to be 168 g. What is the density of the wood in g/cm³?', NULL, '{"value":0.7,"tolerance":0.02}', 'Volume = 10 cm × 6 cm × 4 cm = 240 cm³. Density = Mass / Volume = 168 g / 240 cm³ = 0.70 g/cm³.', 1, 1, 'reviewed', 1),
  ('viii-physics-measurement-q3', 'topic-viii-physics-physical-quantities-density', 'numeric', 'A block of metal has a density of 7500 kg/m³ and a volume of 0.004 m³. Calculate the mass of the metal block in kilograms.', NULL, '{"value":30,"tolerance":0.1}', 'Mass = Density × Volume = 7500 kg/m³ × 0.004 m³ = 30 kg.', 1, 1, 'reviewed', 1),
  ('viii-physics-measurement-q4', 'topic-viii-physics-physical-quantities-density', 'single_choice', 'A solid block has a relative density of 0.75. When placed into a container of pure water (density = 1.0 g/cm³), what fraction of the block''s total volume remains submerged beneath the water surface?', '[{"id":"a","label":"It floats with zero volume submerged."},{"id":"b","label":"Three-fourths (75%) of its total volume."},{"id":"c","label":"One-fourth (25%) of its total volume."},{"id":"d","label":"The block sinks entirely to the bottom."}]', '{"choice":"b"}', 'By the principle of floatation, the fraction of volume submerged of a floating body in water equals (Density of body / Density of water) = Relative Density. Thus, 0.75 or 75% of its volume is submerged.', 1, 0, 'reviewed', 1),
  ('viii-physics-measurement-q5', 'topic-viii-physics-physical-quantities-density', 'single_choice', 'Why does a large ocean-going steel ship float safely on water, even though solid steel has a density nearly eight times greater than water?', '[{"id":"a","label":"Surface tension forces on the immense surface area of the hull support the ship completely."},{"id":"b","label":"The hollow shape of the ship traps a large volume of air, making the average density of the entire ship less than the density of seawater."},{"id":"c","label":"High ocean waves apply continuous upward dynamic thrust against the ship''s keel."},{"id":"d","label":"Seawater contains dissolved salt that dissolves the bottom weight of the ship."}]', '{"choice":"b"}', 'Because the ship is hollowed out, its total volume includes huge air spaces. Average density = Total Mass / Total Volume. This average density is significantly lower than water density, allowing it to float.', 2, 0, 'reviewed', 1),
  ('viii-physics-force-q1', 'topic-viii-physics-moment-and-pressure', 'numeric', 'A mechanic applies a perpendicular force of 45 N at the far end of a wrench of length 0.35 m to tighten an engine bolt. Calculate the moment of force exerted on the bolt in N m.', NULL, '{"value":15.75,"tolerance":0.1}', 'Moment of force = Force × Perpendicular distance from pivot = 45 N × 0.35 m = 15.75 N m.', 2, 1, 'reviewed', 1),
  ('viii-physics-force-q2', 'topic-viii-physics-moment-and-pressure', 'numeric', 'A uniform half-meter ruler is pivoted at its 25 cm midpoint mark. A weight of 0.8 N is hung from the 5 cm mark on the left side. What magnitude of force (in newtons) must be hung from the 45 cm mark on the right side to keep the ruler horizontally balanced?', NULL, '{"value":0.8,"tolerance":0.05}', 'Distance of left weight from pivot = 25 cm - 5 cm = 20 cm. Left anticlockwise moment = 0.8 N × 20 cm = 16 N cm. Distance of right weight from pivot = 45 cm - 25 cm = 20 cm. By principle of moments: F_right × 20 cm = 16 N cm, so F_right = 16 / 20 = 0.8 N.', 2, 1, 'reviewed', 1),
  ('viii-physics-force-q3', 'topic-viii-physics-moment-and-pressure', 'numeric', 'A heavy stone monument weighs 5400 N and rests on a flat rectangular concrete pedestal measuring 1.5 m by 0.6 m. Calculate the pressure exerted by the monument on the pedestal in pascals (N/m²).', NULL, '{"value":6000,"tolerance":10}', 'Contact Area = 1.5 m × 0.6 m = 0.9 m². Pressure = Thrust / Area = 5400 N / 0.9 m² = 6000 Pa.', 2, 1, 'reviewed', 1),
  ('viii-physics-force-q4', 'topic-viii-physics-moment-and-pressure', 'single_choice', 'In a classic physics demonstration, a small amount of water is boiled inside a tin can until steam expels the air. The can is then tightly sealed and cold water is poured over it, causing the can to suddenly crush inward. Why does the can collapse?', '[{"id":"a","label":"Air molecules inside heat up and pull the metal walls inward by suction."},{"id":"b","label":"Cold water causes the metal of the can to contract violently and collapse inward."},{"id":"c","label":"Steam inside condenses into liquid water, creating a partial vacuum so the much greater outside atmospheric pressure crushes the can."},{"id":"d","label":"The weight of the cold water poured on top pushes down with a force exceeding the strength of the tin."}]', '{"choice":"c"}', 'When cold water is poured over the sealed can, the steam inside condenses rapidly into liquid water, leaving behind a partial vacuum (greatly reduced internal pressure). Because the external atmospheric pressure acting on the outside of the can is now vastly greater than the internal pressure, the unbalanced atmospheric force crushes the can inward.', 2, 0, 'reviewed', 1),
  ('viii-physics-force-q5', 'topic-viii-physics-moment-and-pressure', 'single_choice', 'Which statement accurately describes hydrostatic pressure in an open container of liquid at rest?', '[{"id":"a","label":"Liquid pressure increases linearly with depth and acts equally in all directions at any given horizontal level."},{"id":"b","label":"Liquid pressure depends entirely on the lateral surface area and diameter of the container walls."},{"id":"c","label":"Liquid pressure acts only vertically downward and exerts no sideways thrust on container walls."},{"id":"d","label":"Liquid pressure decreases as depth increases because upper layers compress lower layers."}]', '{"choice":"a"}', 'Hydrostatic pressure is given by P = h × rho × g. It increases with depth h, depends on the liquid''s density rho, and acts equally in all directions at a given depth.', 1, 0, 'reviewed', 1),
  ('viii-physics-force-q6', 'topic-viii-physics-moment-and-pressure', 'single_choice', 'A rubber suction cup is pressed firmly against a smooth, clean glass surface so that it sticks tightly and can support a hanging load. Why does the suction cup adhere so strongly to the glass?', '[{"id":"a","label":"Frictional contact between the rubber and glass generates an attractive electrostatic charge."},{"id":"b","label":"Pressing the cup expels air from underneath, creating a partial vacuum so that the greater outside atmospheric pressure presses it firmly against the glass."},{"id":"c","label":"Gravitational attraction between the rubber molecules and the glass molecules increases dramatically upon close contact."},{"id":"d","label":"Moisture between the cup and glass forms an unbreakable chemical adhesive bond."}]', '{"choice":"b"}', 'When the suction cup is pressed against the smooth glass surface, most of the air trapped inside is pushed out, creating a partial vacuum with greatly reduced internal pressure. Because the external atmospheric pressure acting on the outside of the suction cup is much higher than the pressure underneath, the unbalanced inward force exerted by the atmosphere presses the cup firmly against the glass.', 2, 0, 'reviewed', 1),
  ('viii-physics-energy-q1', 'topic-viii-physics-work-kinetic-potential-energy', 'numeric', 'A porter pushes a luggage trolley across a flat railway platform with a horizontal force of 85 N through a distance of 14 m in the direction of the force. Calculate the work done in joules.', NULL, '{"value":1190,"tolerance":5}', 'Work done = Force × displacement = 85 N × 14 m = 1190 J.', 1, 1, 'reviewed', 1),
  ('viii-physics-energy-q2', 'topic-viii-physics-work-kinetic-potential-energy', 'numeric', 'A water tank of mass 250 kg is positioned on a roof 8 m above the ground. Taking acceleration due to gravity g = 10 m/s², calculate the gravitational potential energy of the water tank relative to the ground in joules.', NULL, '{"value":20000,"tolerance":50}', 'Gravitational Potential Energy = m × g × h = 250 kg × 10 m/s² × 8 m = 20000 J.', 2, 1, 'reviewed', 1),
  ('viii-physics-energy-q3', 'topic-viii-physics-work-kinetic-potential-energy', 'numeric', 'An electric crane lifts a steel girder doing 36000 J of work in a duration of 45 seconds. Calculate the power delivered by the crane in watts.', NULL, '{"value":800,"tolerance":5}', 'Power = Work done / Time taken = 36000 J / 45 s = 800 W.', 2, 1, 'reviewed', 1),
  ('viii-physics-energy-q4', 'topic-viii-physics-work-kinetic-potential-energy', 'single_choice', 'A delivery van traveling at 15 m/s increases its speed to 30 m/s. How does its kinetic energy change?', '[{"id":"a","label":"It increases by a factor of 8."},{"id":"b","label":"It remains the same because the mass did not change."},{"id":"c","label":"It doubles."},{"id":"d","label":"It quadruples (increases by a factor of 4)."}]', '{"choice":"d"}', 'Kinetic energy is proportional to the square of velocity (KE = 0.5 × m × v²). Doubling the speed from 15 m/s to 30 m/s increases KE by a factor of 2² = 4.', 2, 0, 'reviewed', 1),
  ('viii-physics-energy-q5', 'topic-viii-physics-work-kinetic-potential-energy', 'single_choice', 'In a hydroelectric power station, water stored in a high dam reservoir is released to turn turbines connected to electric generators. What sequence of energy transformations takes place?', '[{"id":"a","label":"Electrical energy → Mechanical energy → Kinetic energy → Gravitational potential energy"},{"id":"b","label":"Chemical energy → Heat energy → Kinetic energy → Electrical energy"},{"id":"c","label":"Gravitational potential energy → Sound energy → Light energy → Electrical energy"},{"id":"d","label":"Gravitational potential energy → Kinetic energy → Mechanical energy → Electrical energy"}]', '{"choice":"d"}', 'Water stored high up in the reservoir possesses gravitational potential energy. When released, this converts into kinetic energy of flowing water, which rotates the turbines (mechanical energy). Finally, the generators transform this mechanical energy into electrical energy.', 2, 0, 'reviewed', 1),
  ('viii-physics-energy-q6', 'topic-viii-physics-work-kinetic-potential-energy', 'single_choice', 'When a battery-operated electric torch is switched on, which sequence correctly describes the transformation of energy that takes place to illuminate a room?', '[{"id":"a","label":"Electrical energy in the wires → Chemical energy in the battery → Heat and light energy"},{"id":"b","label":"Mechanical energy from the switch → Electrical energy → Chemical energy → Light energy"},{"id":"c","label":"Thermal energy stored in the bulb → Chemical energy → Electrical energy → Light energy"},{"id":"d","label":"Chemical energy stored in the dry cells → Electrical energy in the circuit → Light energy (and heat energy) from the bulb"}]', '{"choice":"d"}', 'In a battery-operated torch, chemical reactions inside the dry cells convert stored chemical energy into electrical energy when the circuit is completed. As electric current flows through the bulb filament (or LED), this electrical energy is converted primarily into light energy along with some heat energy. Thus, the transformation sequence is Chemical energy → Electrical energy → Light energy (and heat energy).', 2, 0, 'reviewed', 1),
  ('viii-physics-light-q1', 'topic-viii-physics-refraction-and-curved-mirrors', 'numeric', 'A dental concave mirror used by a dentist to inspect teeth has a radius of curvature of 4.8 cm. Calculate its focal length in centimeters.', NULL, '{"value":2.4,"tolerance":0.05}', 'Focal length f of a spherical mirror equals half its radius of curvature: f = R / 2 = 4.8 cm / 2 = 2.4 cm.', 1, 1, 'reviewed', 1),
  ('viii-physics-light-q2', 'topic-viii-physics-refraction-and-curved-mirrors', 'single_choice', 'What happens to a ray of light when it passes obliquely from water into air?', '[{"id":"a","label":"It reflects completely without entering the air."},{"id":"b","label":"It speeds up and bends away from the normal."},{"id":"c","label":"It slows down and bends toward the normal."},{"id":"d","label":"It continues in the exact same direction without any deviation."}]', '{"choice":"b"}', 'Water is optically denser than air. When light travels from an optically denser medium into a rarer medium, its speed increases, causing the ray to bend away from the normal line.', 2, 0, 'reviewed', 1),
  ('viii-physics-light-q3', 'topic-viii-physics-refraction-and-curved-mirrors', 'single_choice', 'Why are convex mirrors universally installed as rear-view side mirrors in automobiles?', '[{"id":"a","label":"They always produce erect, diminished virtual images and offer a much wider field of view."},{"id":"b","label":"They focus parallel headlight beams into an intense bright spot."},{"id":"c","label":"They eliminate all blind spots by absorbing stray reflection rays."},{"id":"d","label":"They produce inverted, magnified real images of distant vehicles."}]', '{"choice":"a"}', 'Convex mirrors diverge reflected rays, forming always-erect, virtual, and diminished images regardless of object position, providing drivers with a substantially broader field of view.', 1, 0, 'reviewed', 1),
  ('viii-physics-light-q4', 'topic-viii-physics-refraction-and-curved-mirrors', 'single_choice', 'When narrow white sunlight passes through a triangular glass prism, it disperses into a multi-colored band. Which color bends (deviates) the most from its original path?', '[{"id":"a","label":"Red light"},{"id":"b","label":"Yellow light"},{"id":"c","label":"Violet light"},{"id":"d","label":"Green light"}]', '{"choice":"c"}', 'In glass, violet light has the shortest wavelength and travels slowest among visible colors, giving it the highest refractive index and causing it to suffer the maximum angle of deviation.', 2, 0, 'reviewed', 1),
  ('viii-physics-light-q5', 'topic-viii-physics-refraction-and-curved-mirrors', 'single_choice', 'An object is placed at the centre of curvature (C) in front of a concave mirror. Where is the image formed, and what are its size and nature?', '[{"id":"a","label":"Between F and C, enlarged and real."},{"id":"b","label":"Behind the mirror, magnified and erect."},{"id":"c","label":"At the focus (F), diminished and virtual."},{"id":"d","label":"At the centre of curvature (C), real, inverted, and exactly the same size as the object."}]', '{"choice":"d"}', 'When an object is placed precisely at the centre of curvature C of a concave mirror, rays reflect to form an image at C itself that is real, inverted, and of the exact same size as the object.', 2, 0, 'reviewed', 1),
  ('viii-physics-light-q6', 'topic-viii-physics-refraction-and-curved-mirrors', 'numeric', 'A security mirror fitted in a shop is a convex mirror whose reflecting surface has a radius of curvature of 30 cm. Calculate the focal length of this convex mirror in cm.', NULL, '{"value":15,"tolerance":0.1}', 'For a spherical mirror the focal length is half the radius of curvature, so f = R / 2 = 30 / 2 = 15 cm. For a convex mirror the focus lies behind the reflecting surface, but the magnitude of the focal length is still 15 cm.', 2, 1, 'reviewed', 1),
  ('viii-physics-heat-q1', 'topic-viii-physics-thermal-expansion-and-heat', 'single_choice', 'A bimetallic strip consists of a brass strip firmly riveted along its length to an iron strip. When heated uniformly with a flame, the composite strip bends into a curve with the brass on the outer convex side. Why does it bend in this direction?', '[{"id":"a","label":"Iron expands faster than brass, contracting the inner surface."},{"id":"b","label":"Thermal expansion occurs only in brass while iron stays completely unchanged."},{"id":"c","label":"Brass has a higher coefficient of thermal expansion than iron, expanding more and forcing the strip to curve outward on the brass side."},{"id":"d","label":"Iron softens and melts at a lower temperature than brass, losing its structural rigidity."}]', '{"choice":"c"}', 'Brass expands significantly more than iron for the same temperature rise. Because the two metals are firmly riveted together, the faster-expanding brass must form the longer outer curve (convex side), causing the bimetallic strip to bend toward the iron side.', 2, 0, 'reviewed', 1),
  ('viii-physics-heat-q2', 'topic-viii-physics-thermal-expansion-and-heat', 'single_choice', 'Equal initial volumes (100 cm³) of copper, water, and air are heated from 25 °C to 75 °C under constant pressure. How do their increases in volume compare?', '[{"id":"a","label":"Air expands vastly more than water, which expands more than copper."},{"id":"b","label":"Water expands most because liquids have the highest cubical expansivity."},{"id":"c","label":"Copper expands most, followed by water, and air expands least."},{"id":"d","label":"All three expand by exactly identical amounts because temperature increase is identical."}]', '{"choice":"a"}', 'Thermal expansivity follows the general order: gases >> liquids > solids. Air (gas) expands substantially more than water (liquid), and water expands much more than copper (solid).', 1, 0, 'reviewed', 1),
  ('viii-physics-heat-q3', 'topic-viii-physics-thermal-expansion-and-heat', 'single_choice', 'Which of the following is a primary distinction between evaporation and boiling of a liquid?', '[{"id":"a","label":"Evaporation requires external heat sources, while boiling is purely self-sustaining without heat input."},{"id":"b","label":"Evaporation forms vigorous vapor bubbles within the liquid, whereas boiling produces no bubbles."},{"id":"c","label":"Evaporation produces a heating effect, while boiling always causes cooling."},{"id":"d","label":"Evaporation occurs only from the exposed liquid surface at any temperature, whereas boiling occurs throughout the entire bulk liquid at a fixed temperature."}]', '{"choice":"d"}', 'Evaporation is a slow surface phenomenon occurring at all temperatures below boiling point without bubbling, causing cooling. Boiling is a rapid bulk phenomenon occurring throughout the liquid with bubble formation at a definite boiling point.', 1, 0, 'reviewed', 1),
  ('viii-physics-heat-q4', 'topic-viii-physics-thermal-expansion-and-heat', 'numeric', 'A solid metal rod has a length of 1.200 m at 20 °C. When heated uniformly to 120 °C, its length increases by 0.0024 m (2.4 mm). Calculate the percentage increase in length of the rod.', NULL, '{"value":0.2,"tolerance":0.01}', 'Percentage increase in length = (Increase in length / Original length) × 100 = (0.0024 m / 1.200 m) × 100 = 0.2%.', 2, 1, 'reviewed', 1),
  ('viii-physics-heat-q5', 'topic-viii-physics-thermal-expansion-and-heat', 'numeric', 'An empty volumetric glass flask has an internal volume of 500 cm³ at 0 °C. Upon heating to 100 °C, the flask expands cubically so its internal volume increases by 1.35 cm³. What is the expanded internal volume of the flask at 100 °C in cm³?', NULL, '{"value":501.35,"tolerance":0.05}', 'Expanded volume = Initial volume + Volume increase = 500 cm³ + 1.35 cm³ = 501.35 cm³.', 1, 1, 'reviewed', 1),
  ('viii-physics-sound-q1', 'topic-viii-physics-pitch-frequency-loudness', 'numeric', 'A standard acoustic tuning fork completes 1280 vibrations in 2.5 seconds. What is the frequency of the sound wave produced in hertz (Hz)?', NULL, '{"value":512,"tolerance":1}', 'Frequency = Number of complete vibrations / Time taken = 1280 / 2.5 s = 512 Hz.', 2, 1, 'reviewed', 1),
  ('viii-physics-sound-q2', 'topic-viii-physics-pitch-frequency-loudness', 'numeric', 'A musical audio synthesizer generates a pure tone whose single vibration has a time period of 0.002 seconds. Calculate the frequency of this tone in hertz (Hz).', NULL, '{"value":500,"tolerance":1}', 'Frequency f is the reciprocal of the time period T: f = 1 / T = 1 / 0.002 s = 500 Hz.', 2, 1, 'reviewed', 1),
  ('viii-physics-sound-q3', 'topic-viii-physics-pitch-frequency-loudness', 'single_choice', 'How can a violinist raise the pitch of a note produced by a vibrating violin string without switching to another string?', '[{"id":"a","label":"By loosening the tuning peg so the tension in the string decreases."},{"id":"b","label":"By bowing the string with much greater force to increase amplitude."},{"id":"c","label":"By pressing a finger down on the string to shorten its vibrating length or by tightening the tuning peg to increase tension."},{"id":"d","label":"By using a thicker, heavier replacement string made of wound metal."}]', '{"choice":"c"}', 'The natural frequency of a vibrating string increases with higher tension and decreases with longer length or higher mass per unit length. Pressing down on the fingerboard shortens the active length, raising the vibration frequency and pitch.', 2, 0, 'reviewed', 1),
  ('viii-physics-sound-q4', 'topic-viii-physics-pitch-frequency-loudness', 'single_choice', 'How can musicians produce a note of higher pitch (higher frequency) on a wind instrument (such as a flute) and on a membrane instrument (such as a tabla)?', '[{"id":"a","label":"By using a wider pipe in the wind instrument, and by using a thicker, heavier skin on the drum."},{"id":"b","label":"By shortening the vibrating air column in the wind instrument, and by increasing the tension of the membrane on the drum."},{"id":"c","label":"By lengthening the vibrating air column in the wind instrument, and by loosening the tension of the membrane on the drum."},{"id":"d","label":"By blowing harder into the wind instrument, and by striking the drum membrane with greater force."}]', '{"choice":"b"}', 'Pitch is directly proportional to frequency. In wind instruments, a shorter vibrating air column vibrates faster, producing a higher frequency (higher pitch). In membrane instruments, increasing the tension of the stretched membrane causes it to vibrate faster, also producing a higher frequency and higher pitch. (Blowing or striking harder only increases amplitude and loudness, not pitch.)', 2, 0, 'reviewed', 1),
  ('viii-physics-sound-q5', 'topic-viii-physics-pitch-frequency-loudness', 'single_choice', 'Which physical wave attribute determines the loudness of a sound, and what standard unit is used to express sound loudness levels?', '[{"id":"a","label":"Amplitude determines loudness, measured in decibels (dB)."},{"id":"b","label":"Wave speed determines loudness, measured in meters per second (m/s)."},{"id":"c","label":"Frequency determines loudness, measured in hertz (Hz)."},{"id":"d","label":"Wavelength determines loudness, measured in meters (m)."}]', '{"choice":"a"}', 'Loudness depends on the square of the vibration amplitude. Large amplitudes displace air molecules with greater kinetic energy, producing louder sensations quantified on the decibel (dB) scale.', 1, 0, 'reviewed', 1),
  ('viii-physics-sound-q6', 'topic-viii-physics-pitch-frequency-loudness', 'single_choice', 'In a percussion instrument such as a drum or tabla, how do the surface area and the tension of the vibrating membrane determine the frequency and pitch of the note produced when struck?', '[{"id":"a","label":"A membrane with a smaller surface area and higher tension vibrates faster, producing a higher frequency and higher pitch."},{"id":"b","label":"A membrane with a larger surface area and higher tension vibrates faster, producing a higher frequency and higher pitch."},{"id":"c","label":"A membrane with a larger surface area and lower tension vibrates faster, producing a higher frequency and higher pitch."},{"id":"d","label":"A membrane with a smaller surface area and lower tension vibrates faster, producing a higher frequency and higher pitch."}]', '{"choice":"a"}', 'The vibration frequency of a stretched membrane is directly proportional to the square root of its tension and inversely proportional to its surface area (or diameter). Increasing membrane tension causes it to vibrate faster, while decreasing surface area reduces the vibrating mass so the membrane oscillates at a higher rate. Because pitch depends directly on frequency, a membrane with a smaller surface area and higher tension produces a higher frequency and higher pitch.', 2, 0, 'reviewed', 1),
  ('viii-physics-electricity-q1', 'topic-viii-physics-electrostatics-household-circuits', 'numeric', 'An electric iron rated at 1200 W is operated daily for 2 hours. How many units (kilowatt-hours) of electrical energy does the iron consume in a month of 30 days?', NULL, '{"value":72,"tolerance":0.5}', 'Power in kW = 1200 W / 1000 = 1.2 kW. Daily energy = 1.2 kW × 2 h = 2.4 kWh. Total monthly energy = 2.4 kWh/day × 30 days = 72 kWh (72 units).', 2, 1, 'reviewed', 1),
  ('viii-physics-electricity-q2', 'topic-viii-physics-electrostatics-household-circuits', 'numeric', 'How much energy in megajoules (MJ) is equivalent to 25 commercial units (25 kWh) of electricity?', NULL, '{"value":90,"tolerance":0.5}', '1 kWh = 3.6 × 10⁶ J = 3.6 MJ. Therefore, 25 kWh = 25 × 3.6 MJ = 90 MJ.', 2, 1, 'reviewed', 1),
  ('viii-physics-electricity-q3', 'topic-viii-physics-electrostatics-household-circuits', 'single_choice', 'When a positively charged glass rod is brought near (without touching) the metal brass cap of an uncharged gold-leaf electroscope, what happens to the gold leaves and why?', '[{"id":"a","label":"Protons jump from the glass rod onto the cap and travel down to the leaves, attracting them together."},{"id":"b","label":"The leaves melt instantly due to electric current."},{"id":"c","label":"The leaves remain completely collapsed because no physical contact occurred."},{"id":"d","label":"Free electrons are drawn up to the cap by induction, leaving the leaves positively charged so they diverge due to mutual electrostatic repulsion."}]', '{"choice":"d"}', 'By electrostatic induction, the positive glass rod attracts free conduction electrons upward toward the cap, leaving an excess positive deficiency on the bottom gold leaves. Since both leaves acquire like positive charges, they repel each other and diverge.', 3, 0, 'reviewed', 1),
  ('viii-physics-electricity-q4', 'topic-viii-physics-electrostatics-household-circuits', 'single_choice', 'Why is an electrical safety fuse or Miniature Circuit Breaker (MCB) strictly connected into the live wire rather than the neutral wire of a domestic circuit?', '[{"id":"a","label":"To double the voltage supplied to heavy appliances like air conditioners."},{"id":"b","label":"Because electric current flows only through the live wire and never passes through the neutral wire."},{"id":"c","label":"If placed in the neutral wire, blowing the fuse would break the circuit return but leave the appliance at dangerous high live potential (220 V), causing severe shock hazards."},{"id":"d","label":"Because the live wire has zero electrical resistance while the neutral wire has infinite resistance."}]', '{"choice":"c"}', 'Connecting the fuse in the live wire ensures that whenever excessive current melts the fuse, the appliance is completely isolated from the high-voltage live supply, eliminating shock risk.', 2, 0, 'reviewed', 1),
  ('viii-physics-electricity-q5', 'topic-viii-physics-electrostatics-household-circuits', 'single_choice', 'What is the primary function of the green/yellow insulated earth wire connected to the metallic casing of electrical appliances like refrigerators and washing machines?', '[{"id":"a","label":"It cools the internal electric motor to prevent overheating."},{"id":"b","label":"It supplies supplementary electric power when the line voltage fluctuates."},{"id":"c","label":"In case of insulation breakdown, it channels leaking current directly to ground, blowing the live fuse and protecting users from fatal electric shocks."},{"id":"d","label":"It reduces household power bills by recycling excess electrical energy back into the power grid."}]', '{"choice":"c"}', 'The earth wire provides an extremely low-resistance path from the appliance''s metal outer casing to deep ground. If the live wire accidentally touches the metal body, current surges through the earth wire to ground, quickly blowing the fuse and saving the user from shock.', 2, 0, 'reviewed', 1),
  ('viii-physics-electricity-q6', 'topic-viii-physics-electrostatics-household-circuits', 'numeric', 'A classroom ceiling fan of power 75 W is kept running continuously for 8 hours every school day. Calculate the electrical energy consumed by the fan in 20 school days in kilowatt-hours (kWh).', NULL, '{"value":12,"tolerance":0.1}', 'Power = 75 W = 0.075 kW. Daily energy = 0.075 kW × 8 h = 0.6 kWh. Total energy consumed in 20 days = 0.6 kWh/day × 20 days = 12 kWh.', 1, 1, 'reviewed', 1),
  ('x-physics-tf-q1', 'topic-x-physics-turning-forces', 'single_choice', 'Which of the following statements correctly distinguishes between centripetal force and centrifugal force for an object moving in a circle?', '[{"id":"a","label":"Centrifugal force acts towards the center in an inertial frame, while centripetal force acts outward."},{"id":"b","label":"Centrifugal force is a real gravitational force, while centripetal force is an electrostatic force."},{"id":"c","label":"Centripetal force is a real inward force in an inertial frame, whereas centrifugal force is a fictitious outward force perceived in a rotating frame."},{"id":"d","label":"Centripetal force and centrifugal force form an action-reaction pair according to Newton''s third law."}]', '{"choice":"c"}', 'Centripetal force is a real force directed towards the centre of circular curvature in an inertial frame of reference. Centrifugal force is an apparent, fictitious force of equal magnitude directed radially outward that arises only when describing motion from the rotating (non-inertial) frame of reference. They do not act on the same body as an action-reaction pair.', 2, 0, 'reviewed', 1),
  ('x-physics-tf-q2', 'topic-x-physics-turning-forces', 'numeric', 'A uniform metre rule of mass 60 g is balanced horizontally on a knife-edge at the 35 cm mark when an unknown mass m is suspended at the 10 cm mark. Determine the value of mass m in grams.', NULL, '{"value":36.0,"tolerance":0.5}', 'The centre of gravity of a uniform metre rule is at the 50 cm mark. The rule''s mass of 60 g acts downwards at 50 cm. Distance from pivot (at 35 cm) to rule''s centre = 50 cm - 35 cm = 15 cm. Clockwise moment = 60 gf * 15 cm = 900 gf cm. The unknown mass m is at 10 cm, so its distance to pivot = 35 cm - 10 cm = 25 cm. By the principle of moments, Anticlockwise moment = Clockwise moment => m * 25 cm = 900 gf cm => m = 900 / 25 = 36 g.', 2, 1, 'reviewed', 1),
  ('x-physics-tf-q3', 'topic-x-physics-turning-forces', 'numeric', 'Two parallel forces of magnitude 25 N each act in opposite directions along lines separated by a perpendicular distance of 0.8 m, forming a couple. Calculate the moment of the couple in newton metres (N m).', NULL, '{"value":20.0,"tolerance":0.1}', 'The moment of a couple is given by the product of the magnitude of either force and the perpendicular distance between the two lines of action (arm of the couple). Moment of couple = Force * arm = 25 N * 0.8 m = 20 N m.', 3, 1, 'reviewed', 1),
  ('x-physics-tf-q4', 'topic-x-physics-turning-forces', 'single_choice', 'Where is the centre of gravity located for a uniform hollow sphere of radius R?', '[{"id":"a","label":"At the geometric centre of the sphere, where no material is present."},{"id":"b","label":"On the innermost physical surface of the shell."},{"id":"c","label":"At the lowest point on the bottom of the hollow sphere."},{"id":"d","label":"At the top pole of the outer surface."}]', '{"choice":"a"}', 'The centre of gravity of a symmetrical body like a uniform hollow sphere lies at its geometric centre. Because the sphere is hollow, this balance point is located in the empty space inside the sphere where no physical material exists.', 2, 0, 'reviewed', 1),
  ('x-physics-tf-q5', 'topic-x-physics-turning-forces', 'numeric', 'A mechanic uses a spanner of length 30 cm to loosen a tight nut. If a minimum torque of 45 N m is required to turn the nut, calculate the minimum perpendicular force in newtons (N) that must be applied at the free end of the spanner.', NULL, '{"value":150.0,"tolerance":1.0}', 'Torque tau = Force * perpendicular distance. Given tau = 45 N m and distance d = 30 cm = 0.30 m. Minimum force F = tau / d = 45 / 0.30 = 150 N.', 3, 1, 'reviewed', 1),
  ('x-physics-wep-q1', 'topic-x-physics-work-energy-power', 'single_choice', 'In which of the following situations is the work done by the specified force strictly zero?', '[{"id":"a","label":"A compressed spring expanding and pushing a wooden block across a floor."},{"id":"b","label":"A porter carrying a heavy suitcase on his head while walking horizontally across a platform at constant speed."},{"id":"c","label":"A crane lifting a heavy concrete beam vertically upwards."},{"id":"d","label":"A locomotive pulling a freight train forward along a level track."}]', '{"choice":"b"}', 'The vertical upward force exerted by the porter''s head balances the weight of the suitcase, while the displacement is purely horizontal. The angle theta between the upward supporting force and horizontal displacement is 90°. Since cos 90° = 0, work done by the porter''s upward force is W = F * S * cos 90° = 0.', 1, 0, 'reviewed', 1),
  ('x-physics-wep-q2', 'topic-x-physics-work-energy-power', 'numeric', 'A worker pulls a trolley along a horizontal floor by exerting a force of 160 N at an angle of 60° to the horizontal. If the trolley moves a distance of 25 m, calculate the work done by the worker in joules (J). [Given: cos 60° = 0.5]', NULL, '{"value":2000.0,"tolerance":10.0}', 'Work done W = F * S * cos theta = 160 N * 25 m * cos 60° = 160 * 25 * 0.5 = 2000 J.', 2, 1, 'reviewed', 1),
  ('x-physics-wep-q3', 'topic-x-physics-work-energy-power', 'numeric', 'An engine rated at 4 hp operates continuously for 2 hours. Calculate the total energy consumed in joules, given that 1 hp = 746 W.', NULL, '{"value":21484800.0,"tolerance":20000.0}', 'Power P = 4 hp = 4 * 746 W = 2984 W. Time t = 2 hours = 2 * 3600 s = 7200 s. Total energy E = P * t = 2984 W * 7200 s = 21,484,800 J.', 3, 1, 'reviewed', 1),
  ('x-physics-wep-q4', 'topic-x-physics-work-energy-power', 'single_choice', 'If the linear momentum of a moving body of fixed mass is doubled, what happens to its kinetic energy?', '[{"id":"a","label":"It remains unchanged."},{"id":"b","label":"It is halved."},{"id":"c","label":"It becomes four times its initial value."},{"id":"d","label":"It is doubled."}]', '{"choice":"c"}', 'Kinetic energy is related to linear momentum p by K = p^2 / (2m). Since mass m is constant, kinetic energy is directly proportional to the square of momentum (K proportional to p^2). When p is doubled to 2p, K becomes (2p)^2 / (2m) = 4 * (p^2 / 2m) = 4K.', 2, 0, 'reviewed', 1),
  ('x-physics-wep-q5', 'topic-x-physics-work-energy-power', 'numeric', 'A body of mass 4 kg is moving with a constant velocity of 15 m/s. Calculate its kinetic energy in joules (J).', NULL, '{"value":450.0,"tolerance":2.0}', 'Kinetic energy K = 1/2 * m * v^2 = 0.5 * 4 kg * (15 m/s)^2 = 2 * 225 = 450 J.', 2, 1, 'reviewed', 1);
INSERT INTO questions
  (id, topic_id, question_type, prompt, options_json, answer_json, rationale, difficulty, requires_rough_work, review_status, version)
VALUES
  ('x-physics-mach-q1', 'topic-x-physics-machines-conservation-energy', 'single_choice', 'Which of the following machines operates as a Class II lever?', '[{"id":"a","label":"A pair of sugar tongs"},{"id":"b","label":"A human forearm lifting a weight held in the palm"},{"id":"c","label":"A nutcracker"},{"id":"d","label":"A pair of scissors"}]', '{"choice":"c"}', 'In a nutcracker, the fulcrum is at the hinged end, the load (the nut to be cracked) is located in the middle, and the effort is applied at the free handles. This arrangement (Fulcrum - Load - Effort) defines a Class II lever, which always has MA > 1.', 2, 0, 'reviewed', 1),
  ('x-physics-mach-q2', 'topic-x-physics-machines-conservation-energy', 'numeric', 'A block and tackle system contains 4 pulleys and is 75% efficient. Calculate the effort in newtons (N) required to lift a load of 900 N.', NULL, '{"value":300.0,"tolerance":2.0}', 'For a block and tackle with 4 pulleys, VR = 4. Efficiency eta = 75% = 0.75. Mechanical Advantage MA = eta * VR = 0.75 * 4 = 3. Since MA = Load / Effort, Effort = Load / MA = 900 N / 3 = 300 N.', 2, 1, 'reviewed', 1),
  ('x-physics-mach-q3', 'topic-x-physics-machines-conservation-energy', 'numeric', 'A metal ball of mass 0.5 kg is dropped from a height of 20 m above the ground. Neglecting air resistance and taking g = 10 m/s^2, calculate the kinetic energy of the ball in joules (J) when it is at a height of 8 m above the ground.', NULL, '{"value":60.0,"tolerance":0.5}', 'By conservation of mechanical energy: Total initial energy E = m * g * h_initial = 0.5 kg * 10 m/s^2 * 20 m = 100 J. At height h = 8 m, Potential Energy U = m * g * h = 0.5 * 10 * 8 = 40 J. Kinetic Energy K = Total Energy - U = 100 J - 40 J = 60 J.', 3, 1, 'reviewed', 1),
  ('x-physics-mach-q4', 'topic-x-physics-machines-conservation-energy', 'single_choice', 'Why is the mechanical advantage of a practical block and tackle pulley system always strictly less than its velocity ratio?', '[{"id":"a","label":"Because the velocity ratio decreases as the load rises."},{"id":"b","label":"Because useful work is lost overcoming friction in bearings and lifting the weight of the movable lower block and string."},{"id":"c","label":"Because the total number of pulleys increases during operation."},{"id":"d","label":"Because the acceleration due to gravity decreases with height."}]', '{"choice":"b"}', 'In any real machine, some input work is spent overcoming frictional resistance at the axles and lifting the mass of the movable pulley block and ropes. Consequently, work output is less than work input (efficiency eta < 1), which means MA = eta * VR < VR.', 2, 0, 'reviewed', 1),
  ('x-physics-mach-q5', 'topic-x-physics-machines-conservation-energy', 'single_choice', 'In an ideal simple pendulum oscillating without friction, at which point in its swing is the tension in the suspending string maximum?', '[{"id":"a","label":"The tension is identical at all points along the oscillatory arc."},{"id":"b","label":"At the lowest (mean) position, where kinetic energy and speed are maximum."},{"id":"c","label":"At the extreme left position, where potential energy is maximum."},{"id":"d","label":"At the extreme right position, where speed is momentarily zero."}]', '{"choice":"b"}', 'At the lowest (mean) position, all potential energy has converted into kinetic energy, so speed v is at its peak. The string must support both the bob''s weight and provide the required centripetal acceleration: Tension T = mg + (m v^2 / L). Since v is maximum and weight acts collinear with tension, T reaches its absolute maximum at the mean position.', 3, 0, 'reviewed', 1),
  ('x-physics-refr-q1', 'topic-x-physics-refraction-tir', 'single_choice', 'When a monochromatic ray of light travels from air into a dense glass block, which of its wave characteristics remains completely unchanged?', '[{"id":"a","label":"Wavelength"},{"id":"b","label":"Amplitude"},{"id":"c","label":"Frequency"},{"id":"d","label":"Speed"}]', '{"choice":"c"}', 'The frequency of a light wave is determined entirely by the oscillating source that created it. When passing into another medium, the speed and wavelength decrease in proportion (v = f * lambda), but the frequency remains strictly constant.', 1, 0, 'reviewed', 1),
  ('x-physics-refr-q2', 'topic-x-physics-refraction-tir', 'numeric', 'A glass beaker contains water to a depth of 16 cm. If the refractive index of water is 1.333 (equal to 4/3), calculate the apparent depth of the bottom of the beaker in centimetres (cm).', NULL, '{"value":12.0,"tolerance":0.1}', 'Refractive index mu = Real Depth / Apparent Depth. Apparent Depth = Real Depth / mu = 16 cm / (4/3) = 16 * (3/4) = 12 cm.', 2, 1, 'reviewed', 1),
  ('x-physics-refr-q3', 'topic-x-physics-refraction-tir', 'numeric', 'The speed of light in vacuum is 3.0 * 10^8 m/s. If the refractive index of a specific glass block is 1.50, calculate the speed of light inside the glass block in units of 10^8 m/s (enter just the numerical coefficient).', NULL, '{"value":2.0,"tolerance":0.05}', 'Refractive index mu = c / v, where c is speed in vacuum and v is speed in glass. v = c / mu = (3.0 * 10^8 m/s) / 1.50 = 2.0 * 10^8 m/s. The coefficient is 2.0.', 2, 1, 'reviewed', 1),
  ('x-physics-refr-q4', 'topic-x-physics-refraction-tir', 'single_choice', 'A ray of light enters normally through one perpendicular face of an isosceles right-angled glass prism (angles 45°-90°-45°). If the critical angle for the glass-air boundary is 42°, what happens to the ray when it strikes the hypotenuse face?', '[{"id":"a","label":"It is absorbed completely inside the prism."},{"id":"b","label":"It strikes the hypotenuse at an angle of incidence of 45° and undergoes total internal reflection, turning through 90°."},{"id":"c","label":"It refracts out into the air with an angle of refraction of 45°."},{"id":"d","label":"It emerges straight through the hypotenuse without any deviation."}]', '{"choice":"b"}', 'Because the ray enters normally on one shorter face, it proceeds undeviated to the hypotenuse face. Geometry shows that its angle of incidence on the hypotenuse inside the glass is 45°. Since this angle of incidence (45°) exceeds the critical angle of 42°, total internal reflection occurs, deviating the ray by 90° towards the other shorter face.', 3, 0, 'reviewed', 1),
  ('x-physics-refr-q5', 'topic-x-physics-refraction-tir', 'single_choice', 'Which of the following conditions is mandatory for total internal reflection to occur at an interface?', '[{"id":"a","label":"Light must travel from an optically rarer medium towards an optically denser medium at any non-zero angle."},{"id":"b","label":"The angle of refraction in the second medium must be less than the angle of incidence."},{"id":"c","label":"The refractive index of the second medium must be greater than that of the first medium."},{"id":"d","label":"Light must travel from an optically denser medium towards an optically rarer medium, and the angle of incidence must exceed the critical angle."}]', '{"choice":"d"}', 'Total internal reflection can only happen when light travels from a medium of higher refractive index (denser) towards one of lower refractive index (rarer) and the angle of incidence in the denser medium exceeds the critical angle (i > C).', 2, 0, 'reviewed', 1),
  ('x-physics-lens-q1', 'topic-x-physics-lenses-spectrum-scattering', 'numeric', 'A convex lens has a focal length of 25 cm. Calculate its optical power in dioptres (D).', NULL, '{"value":4.0,"tolerance":0.1}', 'Focal length f = +25 cm = +0.25 m. Optical power P = 1 / f(m) = 1 / 0.25 = +4.0 D.', 2, 1, 'reviewed', 1),
  ('x-physics-lens-q2', 'topic-x-physics-lenses-spectrum-scattering', 'numeric', 'A concave lens has a focal length of 15 cm. If an object is placed 30 cm in front of the lens, calculate the image distance v in centimetres (enter as a negative number following standard sign convention).', NULL, '{"value":-10.0,"tolerance":0.2}', 'For a concave lens, f = -15 cm, and object distance u = -30 cm. Lens formula: 1/f = 1/v - 1/u => -1/15 = 1/v - 1/(-30) => -1/15 = 1/v + 1/30 => 1/v = -1/15 - 1/30 = (-2 - 1)/30 = -3/30 = -1/10 => v = -10 cm.', 3, 1, 'reviewed', 1),
  ('x-physics-lens-q3', 'topic-x-physics-lenses-spectrum-scattering', 'single_choice', 'Which region of the electromagnetic spectrum is characterized by wavelengths just longer than the visible red boundary and produces strong thermal heating effects?', '[{"id":"a","label":"Infrared radiation"},{"id":"b","label":"Ultraviolet radiation"},{"id":"c","label":"X-rays"},{"id":"d","label":"Gamma rays"}]', '{"choice":"a"}', 'Infrared radiation lies immediately beyond the red end of the visible spectrum (approx. 700 nm to 1 mm). It is strongly absorbed by water and common matter, generating molecular vibrations perceived as heat, and is widely utilized in thermal imaging and heat lamps.', 1, 0, 'reviewed', 1),
  ('x-physics-lens-q4', 'topic-x-physics-lenses-spectrum-scattering', 'single_choice', 'Why does the clear daytime sky appear predominantly blue to an observer on Earth?', '[{"id":"a","label":"Dust particles in space reflect sunlight as blue before it reaches Earth''s atmosphere."},{"id":"b","label":"Atmospheric gas molecules scatter shorter blue wavelengths far more effectively than longer red wavelengths according to Rayleigh''s law."},{"id":"c","label":"Ozone gas in the stratosphere absorbs all red and yellow sunlight, reflecting only blue."},{"id":"d","label":"Blue light travels at a noticeably higher speed through the atmosphere than other visible colours."}]', '{"choice":"b"}', 'Rayleigh scattering occurs when scattering particle sizes are much smaller than light wavelength. The scattered intensity is proportional to 1 / lambda^4. Because blue light has a much shorter wavelength (~450 nm) than red light (~700 nm), it is scattered roughly ten times more strongly into the observer''s line of sight across the entire sky.', 2, 0, 'reviewed', 1),
  ('x-physics-lens-q5', 'topic-x-physics-lenses-spectrum-scattering', 'single_choice', 'To use a convex lens of focal length f as a simple magnifying glass, where must the object be positioned along the principal axis?', '[{"id":"a","label":"Between F and 2F"},{"id":"b","label":"At infinity"},{"id":"c","label":"Between the optical centre and the principal focus (u < f)"},{"id":"d","label":"Exactly at 2F"}]', '{"choice":"c"}', 'When an object is placed between the optical centre and the focus (distance u < f) of a convex lens, the refracted rays diverge on the opposite side. Producing them backwards forms an erect, magnified, virtual image on the same side as the object, functioning as a magnifying glass.', 2, 0, 'reviewed', 1),
  ('x-physics-snd-q1', 'topic-x-physics-sound', 'numeric', 'A boy stands at a distance of 85 m from a high vertical wall and claps his hands. If the speed of sound in air is 340 m/s, calculate the time in seconds (s) after which he hears the echo.', NULL, '{"value":0.5,"tolerance":0.02}', 'Total distance traveled by the sound wave to the wall and back is 2 * d = 2 * 85 m = 170 m. Time taken t = (2 * d) / v = 170 m / (340 m/s) = 0.50 s.', 2, 1, 'reviewed', 1),
  ('x-physics-snd-q2', 'topic-x-physics-sound', 'numeric', 'A person standing between two tall parallel vertical cliffs fires a starting pistol. He hears the first echo after 1.5 s and the second echo after 2.5 s. If the speed of sound in air is 330 m/s, calculate the total distance between the two cliffs in metres (m).', NULL, '{"value":660.0,"tolerance":2.0}', 'Let the person be at distance d1 from the first cliff and d2 from the second cliff. The first echo returns in t1 = 1.5 s, so 2 * d1 = v * t1 => d1 = (330 * 1.5) / 2 = 247.5 m. The second echo returns in t2 = 2.5 s, so 2 * d2 = v * t2 => d2 = (330 * 2.5) / 2 = 412.5 m. The total distance between the cliffs is d = d1 + d2 = 247.5 + 412.5 = 660 m.', 3, 1, 'reviewed', 1),
  ('x-physics-snd-q3', 'topic-x-physics-sound', 'single_choice', 'Under what condition does the physical phenomenon of resonance take place?', '[{"id":"a","label":"When the speed of sound exceeds the speed of light in that medium."},{"id":"b","label":"When the frequency of an applied periodic force exactly matches the natural frequency of the vibrating system."},{"id":"c","label":"When sound waves encounter a boundary between two media with identical acoustic impedances."},{"id":"d","label":"When the amplitude of an oscillating system is damped to zero by air resistance."}]', '{"choice":"b"}', 'Resonance is a specific instance of forced vibrations occurring when the frequency of an external driving force coincides with the natural frequency of the system. In this condition, energy transfer is maximized, resulting in large amplitude oscillations.', 1, 0, 'reviewed', 1),
  ('x-physics-snd-q4', 'topic-x-physics-sound', 'single_choice', 'Which acoustic property allows a listener to distinguish between notes of the exact same pitch and loudness played on a violin versus a flute?', '[{"id":"a","label":"Pitch"},{"id":"b","label":"Loudness"},{"id":"c","label":"Velocity"},{"id":"d","label":"Quality (timbre)"}]', '{"choice":"d"}', 'Even when musical instruments play notes of identical fundamental frequency (same pitch) and identical amplitude (same loudness), they sound distinct because of quality or timbre. Timbre is determined by the number, relative frequencies, and amplitudes of the subsidiary harmonics (overtones) accompanying the fundamental note.', 2, 0, 'reviewed', 1),
  ('x-physics-snd-q5', 'topic-x-physics-sound', 'single_choice', 'Why is ultrasound preferentially used over audible sound in medical imaging and underwater SONAR depth sounding?', '[{"id":"a","label":"Ultrasound waves are transverse electromagnetic waves that penetrate dense tissue effortlessly."},{"id":"b","label":"Ultrasound is completely immune to reflection and absorption in matter."},{"id":"c","label":"Ultrasound has a high frequency and short wavelength, enabling high resolution and directional propagation with minimal diffraction spreading."},{"id":"d","label":"Ultrasound travels at twice the speed of audible sound in any medium."}]', '{"choice":"c"}', 'Due to their exceptionally high frequency (above 20 kHz), ultrasound waves possess very short wavelengths. Short wavelengths experience negligible diffraction bending around obstacles, allowing the beam to remain highly directional, focused, and capable of resolving fine anatomical or underwater structures.', 2, 0, 'reviewed', 1),
  ('x-physics-elec-q1', 'topic-x-physics-electricity', 'numeric', 'Two resistors of 6 ohms and 12 ohms are connected in parallel. This parallel combination is then connected in series with a 4-ohm resistor. Calculate the total equivalent resistance of the complete circuit in ohms.', NULL, '{"value":8.0,"tolerance":0.1}', 'For the parallel combination: 1/R_p = 1/6 + 1/12 = (2 + 1)/12 = 3/12 = 1/4 => R_p = 4 ohms. The total equivalent resistance in series is R_eq = R_p + 4 = 4 + 4 = 8 ohms.', 2, 1, 'reviewed', 1),
  ('x-physics-elec-q2', 'topic-x-physics-electricity', 'numeric', 'A 2000 W electric room heater is operated for 5 hours daily over a 30-day month. If electrical energy costs Rs 6.0 per kWh, calculate the total electricity bill for operating this heater for the month in rupees (Rs).', NULL, '{"value":1800.0,"tolerance":5.0}', 'Power P = 2000 W = 2 kW. Operating time per day = 5 hours. Total time in 30 days = 30 * 5 = 150 hours. Total energy consumed = P * t = 2 kW * 150 h = 300 kWh (units). Cost = Total units * rate = 300 units * Rs 6.0/unit = Rs 1800.', 3, 1, 'reviewed', 1),
  ('x-physics-elec-q3', 'topic-x-physics-electricity', 'numeric', 'A battery of emf 12 V and internal resistance 2 ohms is connected to an external load resistor of 10 ohms. Calculate the lost volts (the internal potential drop Ir) in volts (V).', NULL, '{"value":2.0,"tolerance":0.1}', 'Total circuit resistance R_total = R + r = 10 + 2 = 12 ohms. Circuit current I = E / R_total = 12 V / 12 ohms = 1.0 A. Lost volts = I * r = 1.0 A * 2 ohms = 2.0 V.', 2, 1, 'reviewed', 1),
  ('x-physics-elec-q4', 'topic-x-physics-electricity', 'single_choice', 'Why is a switch or fuse always connected in the live wire rather than the neutral wire in domestic electrical installations?', '[{"id":"a","label":"To ensure that when the switch is open or the fuse blows, the appliance is completely isolated from high potential, preventing electric shock."},{"id":"b","label":"Because current flows strictly through the live wire and never passes through the neutral wire."},{"id":"c","label":"To decrease the overall electrical resistance of the appliance during regular operation."},{"id":"d","label":"Because the neutral wire operates at a higher voltage than the live wire."}]', '{"choice":"a"}', 'The live wire is maintained at high electric potential (220-240 V), while the neutral wire is at zero potential (earthed at the substation). Placing the switch or fuse in the live wire ensures that opening the circuit disconnects the appliance from high voltage. If placed in neutral, the appliance remains energized at 220 V even when turned off, posing a severe shock hazard.', 2, 0, 'reviewed', 1),
  ('x-physics-elec-q5', 'topic-x-physics-electricity', 'single_choice', 'What is the primary physical reason that the earth pin on a standard three-pin electrical plug is designed to be noticeably longer and thicker than the live and neutral pins?', '[{"id":"a","label":"To reduce electrical resistance along the live and neutral connections."},{"id":"b","label":"To increase the friction holding the plug tightly inside the wall socket."},{"id":"c","label":"To ensure the earth connection is established first upon insertion and disconnected last upon removal, and to prevent it from entering live sockets."},{"id":"d","label":"To allow higher current to flow continuously into the earth wire during normal appliance operation."}]', '{"choice":"c"}', 'The longer pin ensures that earth connection is established before the live and neutral pins enter the socket, and remains connected until after they are removed. The thicker diameter prevents the earth pin from being mistakenly inserted into live or neutral socket openings.', 1, 0, 'reviewed', 1),
  ('x-physics-elec-q6', 'topic-x-physics-electricity', 'single_choice', 'According to the modern international convention for household electrical wiring, what are the standard insulation colours for the live, neutral, and earth wires, respectively?', '[{"id":"a","label":"Live: brown, Neutral: light blue, Earth: green/yellow"},{"id":"b","label":"Live: red, Neutral: black, Earth: green"},{"id":"c","label":"Live: light blue, Neutral: brown, Earth: green/yellow"},{"id":"d","label":"Live: brown, Neutral: green, Earth: light blue"}]', '{"choice":"a"}', 'Under the modern international convention for three-core household cable, the live wire is brown, the neutral wire is light blue, and the earth wire is green/yellow. In the old convention, live was red, neutral was black, and earth was green.', 1, 0, 'reviewed', 1),
  ('x-physics-mag-q1', 'topic-x-physics-magnetism-induction', 'single_choice', 'What is the primary function of the split-ring commutator in a direct current (DC) electric motor?', '[{"id":"a","label":"To decrease the resistance of the armature coil as it accelerates."},{"id":"b","label":"To prevent the magnetic field of the permanent magnets from collapsing."},{"id":"c","label":"To reverse the direction of current in the armature coil every half-turn, ensuring unidirectional rotation."},{"id":"d","label":"To convert alternating current into three-phase direct current."}]', '{"choice":"c"}', 'As the armature coil passes through the vertical neutral plane, each half of the split-ring commutator switches contact to the opposite brush. This reverses the current direction through the coil sides every half-rotation, ensuring the turning couple continues acting in the same rotational sense.', 2, 0, 'reviewed', 1),
  ('x-physics-mag-q2', 'topic-x-physics-magnetism-induction', 'numeric', 'An ideal step-up transformer has 150 turns on its primary coil and 3000 turns on its secondary coil. If an alternating voltage of 110 V is applied across the primary, calculate the output voltage across the secondary in volts (V).', NULL, '{"value":2200.0,"tolerance":10.0}', 'Transformer equation: V_s / V_p = N_s / N_p. Given N_p = 150, N_s = 3000, V_p = 110 V. V_s = V_p * (N_s / N_p) = 110 * (3000 / 150) = 110 * 20 = 2200 V.', 2, 1, 'reviewed', 1),
  ('x-physics-mag-q3', 'topic-x-physics-magnetism-induction', 'numeric', 'A 100% efficient step-down transformer receives 2200 V on its primary coil and steps it down to 220 V. If the secondary coil delivers a power output of 4400 W, calculate the primary current I_p in amperes (A).', NULL, '{"value":2.0,"tolerance":0.05}', 'For an ideal transformer, Input Power = Output Power. P_in = V_p * I_p. Given P_out = 4400 W and V_p = 2200 V, we have V_p * I_p = 4400 W => 2200 * I_p = 4400 => I_p = 4400 / 2200 = 2.0 A.', 3, 1, 'reviewed', 1),
  ('x-physics-mag-q4', 'topic-x-physics-magnetism-induction', 'single_choice', 'Why is the core of a commercial transformer made of thin, laminated sheets of soft iron insulated from one another rather than a solid iron block?', '[{"id":"a","label":"To eliminate the magnetic field outside the transformer casing."},{"id":"b","label":"To convert alternating current into smooth direct current."},{"id":"c","label":"To minimize energy losses caused by induced circulating eddy currents."},{"id":"d","label":"To prevent the primary coil from overheating due to high supply voltage."}]', '{"choice":"c"}', 'Alternating magnetic flux induces circulating currents (eddy currents) in a solid conducting core, generating significant heat and power loss. Laminating the core into thin varnished or insulated sheets breaks the continuous conductive loops, vastly increasing resistance to eddy currents and reducing energy dissipation.', 2, 0, 'reviewed', 1),
  ('x-physics-mag-q5', 'topic-x-physics-magnetism-induction', 'single_choice', 'According to Fleming''s Left-Hand Rule, when the thumb, forefinger, and central finger of the left hand are held mutually perpendicular, what does the forefinger represent?', '[{"id":"a","label":"The direction of the magnetic field"},{"id":"b","label":"The direction of the mechanical force on the conductor"},{"id":"c","label":"The direction of conventional electric current"},{"id":"d","label":"The direction of induced electromotive force"}]', '{"choice":"a"}', 'In Fleming''s Left-Hand Rule (mnemonic FBI): Thumb indicates Force (motion), Forefinger indicates magnetic Field, and Middle (central) finger indicates Current.', 1, 0, 'reviewed', 1),
  ('x-physics-heat-q1', 'topic-x-physics-heat-calorimetry', 'numeric', 'Calculate the total quantity of heat energy in joules (J) required to completely melt 50 g of ice at 0°C into water at 0°C. [Specific latent heat of fusion of ice = 336 J/g]', NULL, '{"value":16800.0,"tolerance":50.0}', 'Heat required for phase change Q = m * L. Given m = 50 g and L = 336 J/g. Q = 50 * 336 = 16,800 J.', 2, 1, 'reviewed', 1),
  ('x-physics-heat-q2', 'topic-x-physics-heat-calorimetry', 'numeric', 'A mass of 40 g of water at 60°C is added to 60 g of water at 20°C in an insulated container. Assuming no heat is lost to the container or surroundings, calculate the final equilibrium temperature in degrees Celsius (°C). [Specific heat capacity of water = 4.2 J g^-1 °C^-1]', NULL, '{"value":36.0,"tolerance":0.2}', 'Heat lost by hot water = Heat gained by cold water. Let final temperature be T. m1 * c * (60 - T) = m2 * c * (T - 20). Since c cancels out: 40 * (60 - T) = 60 * (T - 20) => 2400 - 40T = 60T - 1200 => 100T = 3600 => T = 36°C.', 3, 1, 'reviewed', 1),
  ('x-physics-heat-q3', 'topic-x-physics-heat-calorimetry', 'single_choice', 'Why do farmers in cold climates flood their fruit orchards and fields with water when a sub-zero freeze is anticipated?', '[{"id":"a","label":"Water evaporates instantly into warm steam that creates a greenhouse canopy over the trees."},{"id":"b","label":"Flooding elevates the ambient atmospheric pressure, significantly increasing the freezing point of sap."},{"id":"c","label":"Water has an exceptionally high specific heat capacity and high latent heat of fusion, releasing large amounts of heat before freezing and insulating vegetation."},{"id":"d","label":"Ice is a superconductor of thermal energy that warms the plants by conduction."}]', '{"choice":"c"}', 'Water has a very high specific heat capacity (4200 J kg^-1 K^-1) and a massive latent heat of fusion (3.36 * 10^5 J/kg). As water cools and begins to freeze on the surface, it liberates enormous quantities of latent heat into the surrounding air and soil, preventing the temperature of delicate plant capillaries from plummeting below 0°C.', 2, 0, 'reviewed', 1),
  ('x-physics-heat-q4', 'topic-x-physics-heat-calorimetry', 'single_choice', 'On a temperature versus time heating curve for a block of pure ice initially at -10°C heated at a steady rate until converted to water at 20°C, what does a flat horizontal plateau represent?', '[{"id":"a","label":"The instant where water boils and converts into steam."},{"id":"b","label":"A malfunction where the calorimeter ceases absorbing heat from the burner."},{"id":"c","label":"The melting phase change where latent heat is absorbed at a constant temperature of 0°C without a temperature increase."},{"id":"d","label":"The region where thermal energy is reflected completely away from the ice."}]', '{"choice":"c"}', 'A horizontal plateau on a heating curve indicates that heat supplied is being absorbed entirely as latent heat of fusion to break intermolecular crystalline bonds (increasing potential energy), while molecular kinetic energy and temperature remain strictly invariant.', 2, 0, 'reviewed', 1),
  ('x-physics-heat-q5', 'topic-x-physics-heat-calorimetry', 'single_choice', 'What is the SI unit of specific heat capacity?', '[{"id":"a","label":"J kg^-1 K^-1"},{"id":"b","label":"J K^-1"},{"id":"c","label":"cal g^-1 °C^-1"},{"id":"d","label":"W m^-1 K^-1"}]', '{"choice":"a"}', 'Specific heat capacity is defined as c = Q / (m * Delta T). The SI unit of heat Q is joule (J), mass m is kilogram (kg), and temperature Delta T is kelvin (K). Hence the SI unit is J kg^-1 K^-1 (joules per kilogram per kelvin).', 1, 0, 'reviewed', 1),
  ('x-physics-nuc-q1', 'topic-x-physics-modern-physics', 'numeric', 'A radioactive nucleus of Uranium-238 (^238_92 U) decays into a daughter nucleus of Thorium-234 (^234_90 Th) by emitting alpha radiation. Calculate the number of neutrons contained in the daughter Thorium nucleus.', NULL, '{"value":144.0,"tolerance":0.1}', 'For the daughter nucleus Thorium-234 (^234_90 Th), mass number A = 234 and atomic number Z = 90. The number of neutrons N is given by N = A - Z = 234 - 90 = 144.', 2, 1, 'reviewed', 1),
  ('x-physics-nuc-q2', 'topic-x-physics-modern-physics', 'numeric', 'A radioactive nucleus of Polonium-218 (^218_84 Po) undergoes successive decays to become a stable Lead nucleus (^206_82 Pb) by emitting a certain number of alpha particles and beta particles. Calculate the total number of alpha particles emitted in this decay series.', NULL, '{"value":3.0,"tolerance":0.1}', 'Beta particles have zero mass number, so only alpha particles reduce mass number. Initial mass number A_initial = 218, final mass number A_final = 206. Total decrease in mass number = 218 - 206 = 12. Since each alpha particle carries 4 units of mass number: Number of alpha particles = 12 / 4 = 3.', 3, 1, 'reviewed', 1),
  ('x-physics-nuc-q3', 'topic-x-physics-modern-physics', 'single_choice', 'Which of the following correctly compares the ionizing power and penetrating power of alpha, beta, and gamma radiations?', '[{"id":"a","label":"Alpha has both the least ionizing power and the least penetrating power."},{"id":"b","label":"Alpha has the highest ionizing power but least penetrating power; Gamma has the least ionizing power but highest penetrating power."},{"id":"c","label":"Gamma has both the highest ionizing power and the highest penetrating power."},{"id":"d","label":"Beta has the highest ionizing power and Gamma has the least penetrating power."}]', '{"choice":"b"}', 'Due to their large mass and +2e charge, alpha particles strongly interact with matter and have the highest ionizing power, but are stopped by a sheet of paper. Gamma rays have no charge or rest mass, resulting in the weakest ionizing ability but immense penetrating power, requiring thick lead or concrete to attenuate.', 2, 0, 'reviewed', 1),
  ('x-physics-nuc-q4', 'topic-x-physics-modern-physics', 'single_choice', 'What happens to the atomic number (Z) and mass number (A) of a radioactive nucleus when it undergoes beta-minus (beta) decay?', '[{"id":"a","label":"Atomic number Z decreases by 1, and mass number A remains unchanged."},{"id":"b","label":"Both atomic number Z and mass number A increase by 1."},{"id":"c","label":"Atomic number Z increases by 1, while mass number A remains unchanged."},{"id":"d","label":"Atomic number Z decreases by 2, and mass number A decreases by 4."}]', '{"choice":"c"}', 'In beta-minus decay, a neutron inside the nucleus transforms into a proton and an electron (^1_0 n -> ^1_1 p + ^0_-1 e). The emitted electron is the beta particle. Since proton count increases by 1, atomic number Z increases by 1, but the total nucleon count A remains identical.', 2, 0, 'reviewed', 1),
  ('x-physics-nuc-q5', 'topic-x-physics-modern-physics', 'single_choice', 'Which of the following conditions is required to initiate and sustain a nuclear fusion reaction?', '[{"id":"a","label":"Complete evacuation of all matter in a cryogenic magnetic trap."},{"id":"b","label":"High electric voltage in an alkaline electrolyte solution."},{"id":"c","label":"Extremely high temperature (approx. 10^7 K) and high pressure to overcome strong electrostatic repulsion between positively charged nuclei."},{"id":"d","label":"Bombardment of stable heavy nuclei with slow thermal neutrons at room temperature."}]', '{"choice":"c"}', 'Positively charged light nuclei strongly repel each other due to Coulomb electrostatic forces. Extreme temperatures (tens of millions of kelvins) impart sufficient kinetic energy to overcome this electrostatic repulsion barrier, allowing short-range nuclear attractive forces to bind them together.', 2, 0, 'reviewed', 1),
  ('xii-commerce-mod1-q1', 'topic-xii-commerce-business-environment', 'single_choice', 'When a sharp rise in consumer health awareness simultaneously stimulates demand for organic foods and depresses sales of carbonated soft drinks, which distinctive feature of the business environment is directly demonstrated?', '[{"id":"a","label":"Static equilibrium of market forces"},{"id":"b","label":"Total predictability of consumer behaviour"},{"id":"c","label":"Relativity across geographic territories"},{"id":"d","label":"Interrelatedness of environmental forces"}]', '{"choice":"d"}', 'Interrelatedness refers to the way different elements or factors of the business environment are closely linked; a shift in social values regarding health directly induces simultaneous shifts in commercial demand patterns across disparate product markets.', 2, 0, 'reviewed', 1),
  ('xii-commerce-mod1-q2', 'topic-xii-commerce-business-environment', 'single_choice', 'An industrial machinery producer monitors central bank monetary policy updates regarding repo rate revisions, statutory reserve ratios, and commercial credit flow. Which macro-environmental dimension is the firm examining?', '[{"id":"a","label":"Economic environment"},{"id":"b","label":"Legal environment"},{"id":"c","label":"Technological environment"},{"id":"d","label":"Social environment"}]', '{"choice":"a"}', 'The economic environment consists of factors such as interest rates, inflation rates, monetary policies, and credit availability that determine the cost of capital and purchasing power across the economy.', 1, 0, 'reviewed', 1),
  ('xii-commerce-mod1-q3', 'topic-xii-commerce-business-environment', 'single_choice', 'Which of the following elements constitutes a constituent of an enterprise''s micro (operating task) environment rather than its macro (general) environment?', '[{"id":"a","label":"Demographic trends reflecting an ageing regional workforce"},{"id":"b","label":"Widespread commercial adoption of artificial intelligence algorithms"},{"id":"c","label":"Authorized wholesale distributors and commercial intermediaries"},{"id":"d","label":"National statutes governing industrial pollution control"}]', '{"choice":"c"}', 'Marketing intermediaries (such as wholesale distributors and agents) are direct operating actors within the micro environment that immediately assist the enterprise in promoting, selling, and distributing goods to final buyers.', 2, 0, 'reviewed', 1),
  ('xii-commerce-mod1-q4', 'topic-xii-commerce-business-environment', 'single_choice', 'A solar panel manufacturer conducts systematic environmental scanning and recognizes that upcoming municipal green-building mandates will require rooftop solar arrays on all new commercial complexes. By expanding production capacity two years ahead of competitors, the firm secures:', '[{"id":"a","label":"First-mover advantage"},{"id":"b","label":"Complete insulation from legal compliance"},{"id":"c","label":"Elimination of production overheads"},{"id":"d","label":"Conversion of fixed assets into current assets"}]', '{"choice":"a"}', 'First-mover advantage is the competitive edge gained by an initial occupant of a market segment who proactively detects external opportunities via early environmental scanning and capitalizes on them before rivals enter.', 2, 0, 'reviewed', 1),
  ('xii-commerce-mod1-q5', 'topic-xii-commerce-business-environment', 'single_choice', 'During a corporate strategic retreat, executives at a textile manufacturing enterprise note that the company suffers from outdated pneumatic looms, high employee attrition, and an overburdened middle management team. In a SWOT matrix, these factors are classified as:', '[{"id":"a","label":"External Threats"},{"id":"b","label":"Internal Weaknesses"},{"id":"c","label":"Strategic Strengths"},{"id":"d","label":"Macro Opportunities"}]', '{"choice":"b"}', 'Weaknesses are inherent internal limitations, resource deficits, or operational inefficiencies (such as obsolete plant machinery and high staff turnover) that place the enterprise at a competitive disadvantage.', 1, 0, 'reviewed', 1),
  ('xii-commerce-mod2-q1', 'topic-xii-commerce-capital-financial-planning', 'single_choice', 'What are the twin core objectives of sound financial planning in a commercial enterprise?', '[{"id":"a","label":"To ensure timely availability of necessary funds and prevent the accumulation of idle financial resources"},{"id":"b","label":"To replace all equity capital with debt and minimise inventory holding levels"},{"id":"c","label":"To guarantee speculative dividend payouts and finance customer credit without limits"},{"id":"d","label":"To maximise short-term sales turnover and eliminate corporate tax liabilities entirely"}]', '{"choice":"a"}', 'Financial planning focuses on two essential goals: ensuring sufficient funds are on hand when needed to meet operational commitments, and ensuring the enterprise does not raise surplus funds that remain unproductively idle.', 1, 0, 'reviewed', 1),
  ('xii-commerce-mod2-q2', 'topic-xii-commerce-capital-financial-planning', 'single_choice', 'A manufacturing firm with highly volatile operating cash flows and an unstable operating margin decides against issuing debentures to fund its capital expenditure. What primary financial risk is the board seeking to avoid?', '[{"id":"a","label":"Debentures impose mandatory fixed interest charges that heighten default and bankruptcy risk during cash flow contractions"},{"id":"b","label":"Debentures cannot be secured against tangible factory machinery"},{"id":"c","label":"Debentures convert current liabilities directly into fixed capital reserves"},{"id":"d","label":"Debentures carry variable dividend rights that dilute existing shareholder control"}]', '{"choice":"a"}', 'Debt instruments impose an unconditional legal obligation to pay interest and repay principal regardless of profitability. An enterprise with erratic cash flows faces severe solvency risk if burdened with high fixed financial commitments.', 2, 0, 'reviewed', 1),
  ('xii-commerce-mod2-q3', 'topic-xii-commerce-capital-financial-planning', 'single_choice', 'Which of the following business operations inherently requires a comparatively smaller proportion of fixed capital relative to its working capital?', '[{"id":"a","label":"A deep-sea offshore petroleum extraction rig"},{"id":"b","label":"A capital-intensive integrated iron and steel blast furnace"},{"id":"c","label":"A wholesale FMCG trading enterprise operating from leased transit godowns"},{"id":"d","label":"A hydroelectric power generation and transmission facility"}]', '{"choice":"c"}', 'A trading concern buys and sells finished goods with minimal processing, using leased premises instead of purchasing heavy plant and machinery. Consequently, its capital is tied up predominantly in inventory and receivables (working capital) rather than fixed assets.', 2, 0, 'reviewed', 1),
  ('xii-commerce-mod2-q4', 'topic-xii-commerce-capital-financial-planning', 'single_choice', 'Which capital source is legally and operationally accessible exclusively to a public joint stock company, and unavailable to sole proprietorships and partnership firms?', '[{"id":"a","label":"Unsecured credit advances extended by raw material suppliers"},{"id":"b","label":"Public issue of transferable equity shares and debentures through a prospectus"},{"id":"c","label":"Reinvestment of accumulated personal operational savings"},{"id":"d","label":"Secured working capital term loans from commercial banks"}]', '{"choice":"b"}', 'Only public limited joint stock companies possess the statutory authority to issue a prospectus and invite the general public to subscribe to freely transferable equity shares and debentures.', 2, 0, 'reviewed', 1),
  ('xii-commerce-mod2-q5', 'topic-xii-commerce-capital-financial-planning', 'numeric', 'Apex Precision Tools Ltd. presents the following balances at the close of the financial year: Finished Goods Inventory = ₹18,00,000; Trade Receivables (Debtors) = ₹14,00,000; Cash and Bank Balances = ₹6,00,000; Trade Payables (Creditors) = ₹11,00,000; Outstanding Factory Expenses = ₹3,00,000. Calculate the Net Working Capital of the company in rupees.', NULL, '{"value":2400000,"tolerance":0}', 'Net Working Capital = Current Assets - Current Liabilities. Current Assets = Inventory (₹18,00,000) + Trade Receivables (₹14,00,000) + Cash & Bank (₹6,00,000) = ₹38,00,000. Current Liabilities = Trade Payables (₹11,00,000) + Outstanding Expenses (₹3,00,000) = ₹14,00,000. Net Working Capital = ₹38,00,000 - ₹14,00,000 = ₹24,00,000.', 2, 1, 'reviewed', 1);
INSERT INTO questions
  (id, topic_id, question_type, prompt, options_json, answer_json, rationale, difficulty, requires_rough_work, review_status, version)
VALUES
  ('xii-commerce-mod3-q1', 'topic-xii-commerce-equity-preference-shares', 'single_choice', 'If a company fails to declare a dividend in an unprofitable year, but the unpaid dividend accrues as an arrear that must be cleared in future profitable years before any equity dividend is distributed, which type of preference share is held?', '[{"id":"a","label":"Non-cumulative preference shares"},{"id":"b","label":"Cumulative preference shares"},{"id":"c","label":"Participating preference shares"},{"id":"d","label":"Redeemable preference shares"}]', '{"choice":"b"}', 'Cumulative preference shares carry the right to accumulate unpaid dividends during loss-making periods; all accumulated arrears must be completely paid off before equity shareholders receive any dividend distribution.', 1, 0, 'reviewed', 1),
  ('xii-commerce-mod3-q2', 'topic-xii-commerce-equity-preference-shares', 'single_choice', 'Which of the following statements accurately highlights a core distinction between equity shares and preference shares?', '[{"id":"a","label":"Equity shares carry a legally fixed rate of dividend, whereas preference dividends fluctuate with annual net profit"},{"id":"b","label":"Equity shareholders possess normal voting rights in general meetings, whereas preference shareholders enjoy voting rights only on resolutions directly affecting their rights"},{"id":"c","label":"Preference share capital is never refunded during company liquidation, whereas equity capital is refunded first"},{"id":"d","label":"Preference dividends are tax-deductible interest expenses, whereas equity dividends are appropriations of profit"}]', '{"choice":"b"}', 'Equity shareholders exercise overall control through voting rights on all resolutions, whereas preference shareholders possess restricted voting rights limited strictly to matters that directly affect their class rights or when dividends remain unpaid for statutory periods.', 2, 0, 'reviewed', 1),
  ('xii-commerce-mod3-q3', 'topic-xii-commerce-equity-preference-shares', 'single_choice', 'What is the primary operational distinction between an issue of Bonus Shares and an issue of Rights Shares?', '[{"id":"a","label":"Bonus shares are offered only to institutional debenture holders, whereas rights shares are offered to the public"},{"id":"b","label":"Bonus shares convert short-term debt into equity, whereas rights issues increase long-term secured liabilities"},{"id":"c","label":"Bonus shares require subscription payments from shareholders, whereas rights shares are allotted free of cost"},{"id":"d","label":"Bonus shares capitalise undistributed reserves without any cash inflow, whereas rights issues require cash payment by existing shareholders"}]', '{"choice":"d"}', 'Bonus shares represent capitalization of existing free reserves and are distributed to existing shareholders free of charge with zero cash inflow, whereas rights shares are offered for cash subscription to existing shareholders pro rata.', 2, 0, 'reviewed', 1),
  ('xii-commerce-mod3-q4', 'topic-xii-commerce-equity-preference-shares', 'single_choice', 'Under company law, shares issued by an enterprise to its directors or employees at a discount or for consideration other than cash, in exchange for providing know-how or making available intellectual property rights, are formally termed:', '[{"id":"a","label":"Sweat Equity Shares"},{"id":"b","label":"Cumulative Convertible Preference Shares"},{"id":"c","label":"Qualified Institutional Placements"},{"id":"d","label":"Participating Preference Shares"}]', '{"choice":"a"}', 'Sweat equity shares are specifically issued to employees or directors at a discount or for non-cash consideration in recognition of their intellectual contributions, patents, or specialized technical value additions to the company.', 2, 0, 'reviewed', 1),
  ('xii-commerce-mod3-q5', 'topic-xii-commerce-equity-preference-shares', 'numeric', 'AeroTech Components Ltd. announces a rights issue in the ratio of 2:5 (2 new shares for every 5 existing shares held) at an issue price of ₹45 per share (face value ₹10). An investor currently holds 1,500 shares. If this investor exercises their rights entitlement in full, what total cash amount in rupees must they remit to the company?', NULL, '{"value":27000,"tolerance":0}', 'Rights shares entitled = 1,500 × (2 / 5) = 600 shares. Total cash remittance required = Number of rights shares × Issue price per share = 600 × ₹45 = ₹27,000.', 2, 1, 'reviewed', 1),
  ('xii-commerce-mod4-q1', 'topic-xii-commerce-debentures-loan-capital', 'single_choice', 'Which of the following legal and operational characteristics differentiates a Debenture Holder from an Equity Shareholder in a joint stock enterprise?', '[{"id":"a","label":"A debenture holder participates actively in voting at annual general meetings"},{"id":"b","label":"A debenture holder''s claims are settled only after complete equity share capital is refunded"},{"id":"c","label":"A debenture holder is an owner of the company, whereas a shareholder is an external creditor"},{"id":"d","label":"A debenture holder receives a contractual fixed rate of interest charged against profit, whereas a shareholder receives variable dividends appropriated from profits"}]', '{"choice":"d"}', 'A debenture holder is a creditor of the company entitled to fixed contractual interest that must be paid regardless of profit, whereas a shareholder is a fractional owner entitled to residual dividends declared out of post-tax profits.', 1, 0, 'reviewed', 1),
  ('xii-commerce-mod4-q2', 'topic-xii-commerce-debentures-loan-capital', 'single_choice', 'A debenture that is secured not against an identifiable piece of land or building, but against the shifting circulating assets (such as inventory and book debts) of the company in the ordinary course of business, is secured by a:', '[{"id":"a","label":"Fixed charge"},{"id":"b","label":"Floating charge"},{"id":"c","label":"Pari passu equity covenant"},{"id":"d","label":"Pre-emptive pledge"}]', '{"choice":"b"}', 'A floating charge secures debt against dynamic, changing classes of assets (like inventory and debtors) that the company is free to deal with in the normal course of business until default crystallises the charge into a fixed encumbrance.', 2, 0, 'reviewed', 1),
  ('xii-commerce-mod4-q3', 'topic-xii-commerce-debentures-loan-capital', 'single_choice', 'What primary operational advantage makes Retained Earnings an especially attractive source of long-term financing for corporate modernization?', '[{"id":"a","label":"It creates a statutory fixed charge over all commercial factory properties"},{"id":"b","label":"It does not incur underwriting commissions, legal prospectus expenses, or dilute existing equity ownership"},{"id":"c","label":"It forces immediate cash dividend repayments to preference shareholders"},{"id":"d","label":"It permanently eliminates all future corporate income tax obligations"}]', '{"choice":"b"}', 'Retained earnings represent internal financing through reinvested profits, avoiding flotation costs, prospectus printing, underwriting commissions, interest commitments, and dilution of voting control.', 2, 0, 'reviewed', 1),
  ('xii-commerce-mod4-q4', 'topic-xii-commerce-debentures-loan-capital', 'single_choice', 'Specialized public institutions such as the Industrial Finance Corporation of India (IFCI) and State Financial Corporations (SFCs) were established primarily to:', '[{"id":"a","label":"Fix foreign currency exchange rates for export-import trading"},{"id":"b","label":"Act as exclusive depositories for unlisted municipal corporate bonds"},{"id":"c","label":"Handle retail day-to-day cheque clearing and consumer credit card issuances"},{"id":"d","label":"Provide medium- and long-term project loans and underwrite securities for industrial enterprises"}]', '{"choice":"d"}', 'Development Financial Institutions (DFIs) like IFCI, IDBI, and SFCs were established to provide medium- and long-term financial assistance, promote balanced industrial development, and underwrite capital issues for new and expanding enterprises.', 2, 0, 'reviewed', 1),
  ('xii-commerce-mod4-q5', 'topic-xii-commerce-debentures-loan-capital', 'numeric', 'A corporation with a 30% corporate income tax rate issues 14% debentures worth ₹50,00,000 at par. What is the effective annual post-tax cost of this debenture debt to the corporation in rupees?', NULL, '{"value":490000,"tolerance":0}', 'Gross annual interest = 14% of ₹50,00,000 = ₹7,00,000. Because interest is tax-deductible, the effective post-tax cost is: Gross Interest × (1 - Tax Rate) = ₹7,00,000 × (1 - 0.30) = ₹7,00,000 × 0.70 = ₹4,90,000.', 2, 1, 'reviewed', 1),
  ('xii-commerce-mod5-q1', 'topic-xii-commerce-short-term-financing-banking', 'single_choice', 'An industrial supplier delivers ₹5,00,000 of raw cotton to a textile spinning mill with terms allowing payment within 60 days without interest. This spontaneous operational financing arrangement is known as:', '[{"id":"a","label":"Trade credit"},{"id":"b","label":"Inter-corporate deposit"},{"id":"c","label":"Cash credit loan"},{"id":"d","label":"Public deposit"}]', '{"choice":"a"}', 'Trade credit is credit extended by one trader to another for the purchase of goods and services, enabling the buyer to generate cash from sales before payment falls due.', 1, 0, 'reviewed', 1),
  ('xii-commerce-mod5-q2', 'topic-xii-commerce-short-term-financing-banking', 'single_choice', 'How does a commercial bank ''Cash Credit'' facility operate for a corporate borrower?', '[{"id":"a","label":"The bank waives all interest if funds are utilized for export promotion"},{"id":"b","label":"The bank credits the entire sanctioned loan amount into a fixed deposit that cannot be withdrawn for three years"},{"id":"c","label":"The borrower is sanctioned a drawing limit against hypothecated current assets and pays interest strictly on the amount actually utilized"},{"id":"d","label":"The bank purchases equity shares in the client company up to the credit limit"}]', '{"choice":"c"}', 'Under a Cash Credit arrangement, the bank establishes a borrowing limit secured against current assets (stocks, debtors), and interest is levied solely on the funds actually drawn and utilized day-to-day, not on the total limit sanctioned.', 2, 0, 'reviewed', 1),
  ('xii-commerce-mod5-q3', 'topic-xii-commerce-short-term-financing-banking', 'single_choice', 'A company with temporary surplus cash reserves of ₹10 crore lends funds to another established corporation for a fixed tenure of three months at a negotiated rate of interest. This transaction constitutes:', '[{"id":"a","label":"A commercial bill discounting facility"},{"id":"b","label":"A customer operating advance"},{"id":"c","label":"A factoring assignment"},{"id":"d","label":"An Inter-Corporate Deposit (ICD)"}]', '{"choice":"d"}', 'Inter-Corporate Deposits (ICDs) are unsecured borrowings and lendings arranged directly between corporate bodies, providing flexible liquidity for call, three-month, or six-month durations.', 2, 0, 'reviewed', 1),
  ('xii-commerce-mod5-q4', 'topic-xii-commerce-short-term-financing-banking', 'single_choice', 'Which of the following statements correctly distinguishes Real Time Gross Settlement (RTGS) from National Electronic Funds Transfer (NEFT)?', '[{"id":"a","label":"NEFT provides irreversible real-time settlement, while RTGS transactions can be reversed within 24 hours"},{"id":"b","label":"RTGS processes transactions continuously on an individual transaction basis, whereas NEFT settles transactions in deferred batches"},{"id":"c","label":"RTGS operates only for sums below ₹50,000, while NEFT handles transactions exceeding ₹1 crore"},{"id":"d","label":"RTGS requires physical cheque clearance at the clearing house, whereas NEFT is fully automated"}]', '{"choice":"b"}', 'In RTGS, transactions are settled continuously on a gross (individual) basis as they occur in real time, whereas NEFT processes interbank fund transfers in deferred net settlement batches throughout the day.', 2, 0, 'reviewed', 1),
  ('xii-commerce-mod5-q5', 'topic-xii-commerce-short-term-financing-banking', 'single_choice', 'What is the primary operational distinction between a Debit Card and a Credit Card during an electronic retail transaction?', '[{"id":"a","label":"A debit card carries a 45-day interest-free repayment credit period, whereas a credit card charges interest daily from purchase date"},{"id":"b","label":"A debit card can only be used at ATMs, while a credit card is restricted exclusively to online transactions"},{"id":"c","label":"A debit card requires merchant signature verification, whereas a credit card cannot be used at point-of-sale terminals"},{"id":"d","label":"A debit card instantly withdraws funds directly from the cardholder''s existing bank balance, while a credit card draws against a pre-approved revolving credit limit extended by the issuing bank"}]', '{"choice":"d"}', 'Debit cards are linked directly to deposit accounts, debiting money immediately upon purchase (''pay now''), whereas credit cards create short-term debt up to a pre-set ceiling, allowing cardholders to repay at a later date (''pay later'').', 1, 0, 'reviewed', 1),
  ('xii-commerce-mod6-q1', 'topic-xii-commerce-management-nature-levels', 'single_choice', 'A project team delivers a software development contract exactly on the agreed client delivery date, but expends 40% more funds than the budgeted financial allocation. In management terminology, this team was:', '[{"id":"a","label":"Neither effective nor efficient"},{"id":"b","label":"Effective but inefficient"},{"id":"c","label":"Efficient but ineffective"},{"id":"d","label":"Both effective and efficient"}]', '{"choice":"b"}', 'Effectiveness relates to achieving end results within time constraints; efficiency relates to cost and resource minimization. Hitting the deadline means the team was effective, but overspending the budget proves they were inefficient.', 1, 0, 'reviewed', 1),
  ('xii-commerce-mod6-q2', 'topic-xii-commerce-management-nature-levels', 'single_choice', 'When management is described as having to continuously adapt enterprise strategies to changing consumer tastes, evolving legal regulations, and emerging technologies, which characteristic is highlighted?', '[{"id":"a","label":"Management is an individualistic discipline"},{"id":"b","label":"Management is a tangible concrete object"},{"id":"c","label":"Management is a static activity"},{"id":"d","label":"Management is a dynamic function"}]', '{"choice":"d"}', 'Management is a dynamic function that must continuously adapt, alter, and modify its plans and operations to respond effectively to an ever-changing business environment.', 1, 0, 'reviewed', 1),
  ('xii-commerce-mod6-q3', 'topic-xii-commerce-management-nature-levels', 'single_choice', 'An automobile company establishes eco-friendly manufacturing plants, provides competitive employment opportunities to local communities, and installs advanced effluent filtration systems. Which category of management objectives is being fulfilled?', '[{"id":"a","label":"Personal objectives"},{"id":"b","label":"Social objectives"},{"id":"c","label":"Functional objectives"},{"id":"d","label":"Organizational objectives"}]', '{"choice":"b"}', 'Social objectives involve creating economic value and welfare for society, including environmental preservation, community development, and fair business conduct.', 2, 0, 'reviewed', 1),
  ('xii-commerce-mod6-q4', 'topic-xii-commerce-management-nature-levels', 'single_choice', 'Which of the following executive functions is a primary responsibility of Top-Level Management rather than Supervisory-Level Management?', '[{"id":"a","label":"Assigning day-to-day machine operating schedules to factory floor workers"},{"id":"b","label":"Enforcing immediate workshop physical safety and maintenance protocols"},{"id":"c","label":"Resolving interpersonal operational disputes among line laborers"},{"id":"d","label":"Formulating long-range enterprise policies, corporate vision, and resource allocation strategies"}]', '{"choice":"d"}', 'Top management (Board of Directors, Chief Executive Officer, Managing Director) is responsible for the overall strategic direction, corporate goal setting, and formulating overarching enterprise policies.', 1, 0, 'reviewed', 1),
  ('xii-commerce-mod6-q5', 'topic-xii-commerce-management-nature-levels', 'single_choice', 'Why is management considered an ''inexact science'' or a ''social science''?', '[{"id":"a","label":"Its principles deal with complex, unpredictable human behavior and cannot be tested under rigid laboratory conditions like physics or chemistry"},{"id":"b","label":"It has no recognized academic textbooks, professional literature, or research journals"},{"id":"c","label":"Managers are legally prohibited from measuring financial outcomes"},{"id":"d","label":"It lacks any systematic body of theoretical knowledge or verifiable principles"}]', '{"choice":"a"}', 'Management has a systematized body of knowledge, but because its principles deal with human beings whose reactions cannot be predicted with mathematical certainty, its outcomes lack the universal exactness of physical sciences.', 2, 0, 'reviewed', 1),
  ('xii-commerce-mod7-q1', 'topic-xii-commerce-principles-of-management', 'single_choice', 'A software engineer receives conflicting project deadlines and contradictory feature requirements from the Marketing Director and the Technical Product Manager at the same time. Which administrative principle of Henri Fayol is being violated?', '[{"id":"a","label":"Unity of Command"},{"id":"b","label":"Subordination of individual interest"},{"id":"c","label":"Esprit de corps"},{"id":"d","label":"Unity of Direction"}]', '{"choice":"a"}', 'Unity of Command dictates that an individual employee must receive instructions from and report to strictly one superior; dual reporting causes confusion, undermines discipline, and divides loyalty.', 1, 0, 'reviewed', 1),
  ('xii-commerce-mod7-q2', 'topic-xii-commerce-principles-of-management', 'single_choice', 'Which of F.W. Taylor''s scientific techniques divides operational workshop supervision among eight specialized foremen—four in planning and four in execution—to direct each operative worker?', '[{"id":"a","label":"Functional foremanship"},{"id":"b","label":"Differential piece-rate system"},{"id":"c","label":"Standardisation of tools"},{"id":"d","label":"Motion study"}]', '{"choice":"a"}', 'Functional foremanship is Taylor''s technique that extends division of labor by deploying eight specialized supervisors (four in the planning room and four in the workshop) to oversee each workman.', 2, 0, 'reviewed', 1),
  ('xii-commerce-mod7-q3', 'topic-xii-commerce-principles-of-management', 'single_choice', 'How does F.W. Taylor''s ''Differential Piece Wage System'' incentivize superior industrial worker productivity?', '[{"id":"a","label":"It pays a higher piece rate per unit to workers who achieve or exceed the standard quota, and a lower rate to those who underperform"},{"id":"b","label":"It distributes company equity shares in lieu of monetary wages"},{"id":"c","label":"It penalizes workers by deducting daily allowances for machinery breakdowns"},{"id":"d","label":"It guarantees identical fixed monthly salaries to all workers regardless of output"}]', '{"choice":"a"}', 'Taylor''s differential piece-rate system establishes two distinct wage rates: an elevated rate per unit for workers meeting or beating standard performance targets, and a lower rate for workers falling short, powerfully motivating workers to attain peak efficiency.', 2, 0, 'reviewed', 1),
  ('xii-commerce-mod7-q4', 'topic-xii-commerce-principles-of-management', 'single_choice', 'Under Henri Fayol''s Scalar Chain concept, what administrative mechanism permits direct horizontal communication between two managers of identical rank during an operational emergency without ascending the formal hierarchy?', '[{"id":"a","label":"Gang plank"},{"id":"b","label":"Management by exception"},{"id":"c","label":"Esprit de corps"},{"id":"d","label":"Functional foremanship"}]', '{"choice":"a"}', 'A ''gang plank'' is an exception to the formal scalar chain that enables two officials of equal status in different lines of authority to communicate directly with each other in an emergency to avoid delays.', 2, 0, 'reviewed', 1),
  ('xii-commerce-mod7-q5', 'topic-xii-commerce-principles-of-management', 'numeric', 'Under Taylor''s differential piece-wage system, standard daily output is fixed at 40 units. The piece rate is ₹15 per unit for output at or above standard, and ₹12 per unit for output below standard. Worker Mohan produces 44 units, while Worker Sohan produces 36 units. What is the difference in daily earnings between Mohan and Sohan in rupees?', NULL, '{"value":228,"tolerance":0}', 'Mohan produces 44 units (above standard), so his wage rate is ₹15 per unit: 44 × ₹15 = ₹660. Sohan produces 36 units (below standard), so his wage rate is ₹12 per unit: 36 × ₹12 = ₹432. Difference in daily earnings = ₹660 - ₹432 = ₹228.', 2, 1, 'reviewed', 1),
  ('xii-commerce-mod8-q1', 'topic-xii-commerce-planning-organising-staffing', 'single_choice', 'In an organization manufacturing pharmaceuticals, cosmetics, and electronics, operations are structured into autonomous multi-product units, each possessing its own dedicated research, manufacturing, and marketing departments. Which structure is adopted?', '[{"id":"a","label":"Informal matrix network"},{"id":"b","label":"Sole proprietorship hierarchy"},{"id":"c","label":"Functional structure"},{"id":"d","label":"Divisional structure"}]', '{"choice":"d"}', 'A divisional structure groups activities around separate product lines, business units, or geographical territories, with each division functioning as an autonomous profit center with its own specialized functional departments.', 2, 0, 'reviewed', 1),
  ('xii-commerce-mod8-q2', 'topic-xii-commerce-planning-organising-staffing', 'single_choice', 'Which of the following specific plan types provides an exact, rigid guide to action that admits no managerial discretion or flexibility, prescribing what must or must not be done in a given situation?', '[{"id":"a","label":"Strategy"},{"id":"b","label":"Objective"},{"id":"c","label":"Policy"},{"id":"d","label":"Rule"}]', '{"choice":"d"}', 'A rule is a specific statement that clearly dictates what must or must not be done in a particular situation, leaving no room for individual interpretation or discretion.', 1, 0, 'reviewed', 1),
  ('xii-commerce-mod8-q3', 'topic-xii-commerce-planning-organising-staffing', 'single_choice', 'What is the crucial structural distinction between Delegation and Decentralisation in management?', '[{"id":"a","label":"Delegation is prohibited by commercial company law, whereas decentralisation is legally mandatory"},{"id":"b","label":"Delegation is a downward transfer of authority between two individuals, whereas decentralisation is a systematic enterprise-wide dispersal of decision-making authority across all levels"},{"id":"c","label":"Delegation applies only to top management, whereas decentralisation applies only to factory floor supervisors"},{"id":"d","label":"Delegation is a broad philosophy of governance, while decentralisation is an optional one-to-one managerial technique"}]', '{"choice":"b"}', 'Delegation is an interpersonal process of sharing authority between a superior and subordinate to get work done, whereas decentralization is a systemic corporate policy dispersing decision-making power across all levels of the enterprise.', 2, 0, 'reviewed', 1),
  ('xii-commerce-mod8-q4', 'topic-xii-commerce-planning-organising-staffing', 'single_choice', 'In the systematic Staffing sequence, why is candidate Selection described as a ''negative'' process while Recruitment is described as a ''positive'' process?', '[{"id":"a","label":"Recruitment seeks to attract a large pool of applicants, whereas selection screens and eliminates candidates to hire the most qualified"},{"id":"b","label":"Recruitment requires police verification, whereas selection involves informal campus interviews"},{"id":"c","label":"Recruitment leads to immediate wage deductions, whereas selection provides pension benefits"},{"id":"d","label":"Recruitment focuses on rejecting unqualified candidates, while selection invites all applicants indiscriminately"}]', '{"choice":"a"}', 'Recruitment is considered positive because it encourages and attracts prospective job seekers to apply; selection is considered negative because it screens, eliminates, and rejects less suitable applicants.', 2, 0, 'reviewed', 1),
  ('xii-commerce-mod8-q5', 'topic-xii-commerce-planning-organising-staffing', 'single_choice', 'An industrial manufacturing enterprise establishes a vestibule school equipped with exact replicas of expensive factory machines to train newly recruited operators away from the actual assembly line. This method represents:', '[{"id":"a","label":"Internship coaching"},{"id":"b","label":"Off-the-job training"},{"id":"c","label":"On-the-job apprenticeship training"},{"id":"d","label":"Job rotation"}]', '{"choice":"b"}', 'Vestibule training is an off-the-job training technique where workers learn their jobs on specialized equipment in a classroom or workshop setting away from the actual factory floor to avoid damaging expensive production machinery.', 2, 0, 'reviewed', 1),
  ('xii-commerce-mod9-q1', 'topic-xii-commerce-directing-controlling-coordination', 'single_choice', 'According to Abraham Maslow''s Hierarchy of Needs theory, which need level must be reasonably satisfied before an employee is motivated by esteem needs (such as job titles, prestige, and professional recognition)?', '[{"id":"a","label":"Self-actualisation needs"},{"id":"b","label":"Social (belongingness and love) needs"},{"id":"c","label":"Differential piece-wage needs"},{"id":"d","label":"Scalar chain needs"}]', '{"choice":"b"}', 'In Maslow''s hierarchy, needs are arranged progressively: Physiological -> Safety -> Social/Belongingness -> Esteem -> Self-Actualisation. Social needs must be satisfied before higher-order esteem needs become active motivators.', 1, 0, 'reviewed', 1),
  ('xii-commerce-mod9-q2', 'topic-xii-commerce-directing-controlling-coordination', 'single_choice', 'A Chief Executive Officer adopts a leadership style where project decisions are made through group consultation, subordinates are actively invited to offer feedback on proposed policies, and authority is shared. This leadership style is:', '[{"id":"a","label":"Laissez-faire (Free-rein) leadership"},{"id":"b","label":"Paternalistic bureaucratic leadership"},{"id":"c","label":"Autocratic (Authoritarian) leadership"},{"id":"d","label":"Democratic (Participative) leadership"}]', '{"choice":"d"}', 'Democratic or participative leadership involves consulting with subordinates, encouraging team participation in decision-making, and respecting employee opinions before finalizing actions.', 1, 0, 'reviewed', 1),
  ('xii-commerce-mod9-q3', 'topic-xii-commerce-directing-controlling-coordination', 'single_choice', 'In the managerial controlling sequence, what is the core operational rationale behind the principle of ''Management by Exception'' (MBE)?', '[{"id":"a","label":"To focus senior managerial attention on significant, abnormal deviations while leaving normal, minor variances to routine supervisory staff"},{"id":"b","label":"To discharge every worker who fails to achieve standard hourly output"},{"id":"c","label":"To replace internal quality control with mandatory judicial arbitration"},{"id":"d","label":"To inspect 100% of manufactured goods and eliminate all supervisory personnel"}]', '{"choice":"a"}', 'Management by Exception rests on the principle that attempting to control everything results in controlling nothing. Senior executives should concentrate their attention on substantial variations that exceed established tolerance limits.', 2, 0, 'reviewed', 1),
  ('xii-commerce-mod9-q4', 'topic-xii-commerce-directing-controlling-coordination', 'single_choice', 'A factory memo drafted in dense engineering jargon is misunderstood by shop-floor assembly workers, leading to improper machine calibration. Which type of communication barrier occurred?', '[{"id":"a","label":"Personal physical barrier"},{"id":"b","label":"Semantic barrier"},{"id":"c","label":"Organizational barrier"},{"id":"d","label":"Psychological status barrier"}]', '{"choice":"b"}', 'Semantic barriers arise from problems in the language, symbols, vocabulary, or technical jargon used to encode messages, causing faulty translation or misinterpretation by the receiver.', 2, 0, 'reviewed', 1),
  ('xii-commerce-mod9-q5', 'topic-xii-commerce-directing-controlling-coordination', 'single_choice', 'Why do modern management theorists define Coordination as the ''essence of management'' rather than treating it merely as a separate functional step?', '[{"id":"a","label":"Because coordination replaces the need for financial budgeting and market research"},{"id":"b","label":"Because coordination is legally required under the Indian Companies Act"},{"id":"c","label":"Because coordination is the unifying force that binds and harmonizes all five managerial functions (planning, organising, staffing, directing, and controlling)"},{"id":"d","label":"Because coordination is performed exclusively by lower-level factory supervisors"}]', '{"choice":"c"}', 'Coordination is not an isolated managerial function; it is the fundamental essence of management that harmonizes and integrates all individual efforts across planning, organising, staffing, directing, and controlling to achieve enterprise goals.', 2, 0, 'reviewed', 1),
  ('xii-commerce-mod10-q1', 'topic-xii-commerce-marketing-concept-functions', 'single_choice', 'How is a market primarily categorized when buyers purchase specialized goods such as high-tensile sheet metal, hydraulic stamping presses, and industrial lubricants to manufacture motor vehicles?', '[{"id":"a","label":"Industrial goods market"},{"id":"b","label":"Retail grocery market"},{"id":"c","label":"Speculative currency market"},{"id":"d","label":"Consumer goods market"}]', '{"choice":"a"}', 'An industrial goods market consists of individuals and organizations that purchase goods and services for use in producing other products or operating an industrial business.', 1, 0, 'reviewed', 1),
  ('xii-commerce-mod10-q2', 'topic-xii-commerce-marketing-concept-functions', 'single_choice', 'Which commercial philosophy operates on the premise that consumers will favor products that offer superior quality, performance, and innovative features, leading management to concentrate on continuous product improvements without consulting customer preferences?', '[{"id":"a","label":"The Production Concept"},{"id":"b","label":"The Selling Concept"},{"id":"c","label":"The Marketing Concept"},{"id":"d","label":"The Societal Marketing Concept"}]', '{"choice":"a"}', 'The Product Concept focuses on manufacturing superior goods and refining them over time, assuming customers will automatically buy high-quality products without extensive marketing research.', 2, 0, 'reviewed', 1),
  ('xii-commerce-mod10-q3', 'topic-xii-commerce-marketing-concept-functions', 'single_choice', 'Which of the following points highlights an essential distinction between Selling and Marketing?', '[{"id":"a","label":"Selling emphasizes integrated marketing research, whereas marketing relies purely on price discounting"},{"id":"b","label":"Selling begins long before production starts, whereas marketing begins only after goods are stored in warehouses"},{"id":"c","label":"Selling focuses on the buyer''s needs, whereas marketing focuses solely on the seller''s factory needs"},{"id":"d","label":"Selling aims at profit through sales volume, whereas marketing aims at profit through customer satisfaction"}]', '{"choice":"d"}', 'Selling focuses on the seller''s need to convert goods into cash to maximize sales volume, whereas marketing focuses on satisfying the needs of the consumer to earn profits through customer loyalty.', 2, 0, 'reviewed', 1),
  ('xii-commerce-mod10-q4', 'topic-xii-commerce-marketing-concept-functions', 'single_choice', 'When an agricultural cooperative classifies harvested apples into Grade A, Grade B, and Grade C based on fruit diameter, uniform colour, and weight, it is performing the marketing function of:', '[{"id":"a","label":"Branding"},{"id":"b","label":"Customer support services"},{"id":"c","label":"Grading"},{"id":"d","label":"Standardisation"}]', '{"choice":"c"}', 'Grading is the process of sorting products into different classes or categories based on established criteria such as size, weight, quality, and condition, especially important for agricultural commodities.', 1, 0, 'reviewed', 1),
  ('xii-commerce-mod10-q5', 'topic-xii-commerce-marketing-concept-functions', 'single_choice', 'How does marketing create economic ''time utility'' and ''place utility'' for consumers?', '[{"id":"a","label":"Through industrial manufacturing patents and equity share issues"},{"id":"b","label":"Through warehousing (storage until demand arises) and transportation (moving goods to accessible consumption points)"},{"id":"c","label":"Through high-frequency speculative stock exchange trading"},{"id":"d","label":"Through statutory legal drafting of company articles"}]', '{"choice":"b"}', 'Transportation moves goods from production centers to consumption points, creating place utility; warehousing stores goods from harvest or production until demanded, creating time utility.', 2, 0, 'reviewed', 1),
  ('xii-commerce-mod11-q1', 'topic-xii-commerce-marketing-mix', 'single_choice', 'An oral care enterprise packages toothpaste inside a collapsible plastic tube, places that tube inside a printed cardboard carton, and packs 72 cartons into a corrugated fibreboard box for highway freight transit. The printed cardboard carton represents the:', '[{"id":"a","label":"Transportation package"},{"id":"b","label":"Disposable courier wrapper"},{"id":"c","label":"Primary package"},{"id":"d","label":"Secondary package"}]', '{"choice":"d"}', 'The collapsible tube is the primary package (immediate container); the printed cardboard box is the secondary package (additional layer of protection discarded when put to use); and the corrugated carton is the transportation package.', 2, 0, 'reviewed', 1),
  ('xii-commerce-mod11-q2', 'topic-xii-commerce-marketing-mix', 'single_choice', 'A digital telecommunications network enters an intensely competitive broadband market by offering free high-speed fiber-optic data for the first six months, deliberately targeting widespread consumer adoption and rapid market share acquisition. Which pricing strategy is being deployed?', '[{"id":"a","label":"Prestige luxury pricing strategy"},{"id":"b","label":"Price skimming strategy"},{"id":"c","label":"Penetration pricing strategy"},{"id":"d","label":"Cost-plus markup strategy"}]', '{"choice":"c"}', 'Penetration pricing charges an exceptionally low initial price (or offers free trial periods) to penetrate the market deeply and quickly, attracting a large base of customers and driving out rivals.', 1, 0, 'reviewed', 1),
  ('xii-commerce-mod11-q3', 'topic-xii-commerce-marketing-mix', 'single_choice', 'A heavy engineering plant designs customized multi-crore industrial steam turbines for hydroelectric dams. Which distribution channel structure is most appropriate for selling these specialized engineering installations?', '[{"id":"a","label":"Door-to-door retail peddlers"},{"id":"b","label":"Direct zero-level channel (Manufacturer directly to User)"},{"id":"c","label":"Two-level channel (Manufacturer to Wholesaler to Retailer to Consumer)"},{"id":"d","label":"Three-level channel involving carrying and forwarding agents"}]', '{"choice":"b"}', 'Complex, expensive, custom-built industrial goods require direct technical consultation, negotiations, and post-installation service, making a direct zero-level channel (manufacturer to industrial user) necessary.', 2, 0, 'reviewed', 1),
  ('xii-commerce-mod11-q4', 'topic-xii-commerce-marketing-mix', 'single_choice', 'Which promotion mix component is characterized by non-personal, unpaid commercial presentation and dissemination of significant business news in published mass media without direct sponsor funding?', '[{"id":"a","label":"Television commercial advertising"},{"id":"b","label":"Direct personal selling"},{"id":"c","label":"Publicity"},{"id":"d","label":"Sales discount promotion"}]', '{"choice":"c"}', 'Publicity is non-personal stimulation of demand for a product or business by securing news coverage in mass media without direct payment by an identified commercial sponsor.', 2, 0, 'reviewed', 1),
  ('xii-commerce-mod11-q5', 'topic-xii-commerce-marketing-mix', 'numeric', 'An artisan leather goods enterprise incurs a direct material cost of ₹1,200, direct labor cost of ₹600, and variable factory overheads of ₹200 per designer travel bag. Fixed corporate overheads allocated to each bag are ₹400. If the enterprise determines its selling price using a cost-plus pricing formula with a 25% profit margin markup on total cost, what is the selling price per bag in rupees?', NULL, '{"value":3000,"tolerance":0}', 'Total Cost per bag = Direct Material (₹1,200) + Direct Labor (₹600) + Variable Overheads (₹200) + Fixed Overheads (₹400) = ₹2,400. Profit markup (25% on total cost) = 25% of ₹2,400 = ₹600. Selling Price = Total Cost + Profit Markup = ₹2,400 + ₹600 = ₹3,000.', 2, 1, 'reviewed', 1),
  ('xii-commerce-mod12-q1', 'topic-xii-commerce-consumer-protection', 'single_choice', 'A packaged food brand fails to disclose the list of artificial preservatives, nutritional composition, manufacturing date, and best-before expiry date on its cereal boxes. Which statutory consumer right is directly infringed?', '[{"id":"a","label":"Right to be Informed"},{"id":"b","label":"Right to Choose"},{"id":"c","label":"Right to Consumer Education"},{"id":"d","label":"Right to Safety"}]', '{"choice":"a"}', 'The Right to be Informed guarantees that consumers have the right to know the quality, quantity, potency, purity, standard, and price of goods or services, including expiry dates and ingredients, so as to protect against unfair trade practices.', 1, 0, 'reviewed', 1),
  ('xii-commerce-mod12-q2', 'topic-xii-commerce-consumer-protection', 'single_choice', 'Under the Consumer Protection Act, 2019, which of the following individuals qualifies legally as a ''consumer'' entitled to file a complaint before a Consumer Disputes Redressal Commission?', '[{"id":"a","label":"A person who receives an electronic gadget as an unsolicited free commercial sample without any consideration"},{"id":"b","label":"A dealer who purchases 50 air conditioners directly from a factory to resell them to retail buyers at a profit"},{"id":"c","label":"An individual who purchases a single commercial printing machine exclusively for the purpose of earning a personal livelihood through self-employment"},{"id":"d","label":"A corporate entity that procures 500 laptops for distribution to its nationwide executive sales force"}]', '{"choice":"c"}', 'Under the Act, a person who buys goods exclusively for the purpose of earning their livelihood by means of self-employment is legally recognized as a consumer, whereas commercial purchases for resale are excluded.', 2, 0, 'reviewed', 1);
INSERT INTO questions
  (id, topic_id, question_type, prompt, options_json, answer_json, rationale, difficulty, requires_rough_work, review_status, version)
VALUES
  ('xii-commerce-mod12-q3', 'topic-xii-commerce-consumer-protection', 'single_choice', 'Why is insisting on a formal cash memo or tax invoice at the time of purchase considered an indispensable consumer responsibility?', '[{"id":"a","label":"It permits the consumer to resell the product without an enterprise licence"},{"id":"b","label":"It serves as the definitive legal proof of purchase required to establish locus standi and claim redressal in consumer commissions"},{"id":"c","label":"It permanently exempts the consumer from paying municipal taxes"},{"id":"d","label":"It guarantees that the manufacturer will double the product warranty automatically"}]', '{"choice":"b"}', 'A cash memo or tax invoice constitutes definitive documentary evidence of purchase and consideration paid, without which a consumer cannot substantiate a legal claim in consumer dispute forums.', 1, 0, 'reviewed', 1),
  ('xii-commerce-mod12-q4', 'topic-xii-commerce-consumer-protection', 'single_choice', 'Which major regulatory enhancement represents a key structural difference between the Consumer Protection Act, 2019 and the erstwhile 1986 Act?', '[{"id":"a","label":"The 2019 Act established the Central Consumer Protection Authority (CCPA) as an executive regulator and explicitly included e-commerce transactions and mediation"},{"id":"b","label":"The 2019 Act eliminated all civil compensation for defective industrial goods"},{"id":"c","label":"The 2019 Act prohibited consumers from hiring advocates or filing written representations"},{"id":"d","label":"The 2019 Act abolished the District and State consumer forums completely"}]', '{"choice":"a"}', 'The 2019 Act introduced the Central Consumer Protection Authority (CCPA) with powers to initiate class actions, issue recall orders, penalize false endorsements, and specifically incorporated e-commerce transactions and mediation into consumer jurisprudence.', 2, 0, 'reviewed', 1),
  ('xii-commerce-mod12-q5', 'topic-xii-commerce-consumer-protection', 'single_choice', 'Under the Consumer Protection Act, 2019, what maximum financial penalty can the Central Consumer Protection Authority (CCPA) impose on a manufacturer or endorser for publishing a false or misleading advertisement for the first offence?', '[{"id":"a","label":"Up to ₹1,00,00,000"},{"id":"b","label":"Up to ₹1,00,000"},{"id":"c","label":"Up to ₹5,00,000"},{"id":"d","label":"Up to ₹10,00,000"}]', '{"choice":"d"}', 'The CCPA is empowered under the Consumer Protection Act, 2019 to impose a penalty of up to ₹10 lakh on a manufacturer or endorser for a first misleading advertisement violation, and up to ₹50 lakh for subsequent contraventions.', 2, 0, 'reviewed', 1),
  ('xii-commerce-mod12-q6', 'topic-xii-commerce-consumer-protection', 'single_choice', 'Under the Consumer Protection (Consumer Disputes Redressal Commissions) Rules 2021, which consumer dispute redressal forum has pecuniary jurisdiction to entertain an original complaint where the value of goods or services paid as consideration is ₹75 lakh?', '[{"id":"a","label":"State Consumer Disputes Redressal Commission (State Commission)"},{"id":"b","label":"National Consumer Disputes Redressal Commission (National Commission)"},{"id":"c","label":"Supreme Court of India"},{"id":"d","label":"District Consumer Disputes Redressal Commission (District Commission)"}]', '{"choice":"a"}', 'Under the revised pecuniary jurisdiction notified in the Consumer Protection (Consumer Disputes Redressal Commissions) Rules 2021, the District Commission hears complaints where consideration does not exceed ₹50 lakh; the State Commission hears complaints where consideration exceeds ₹50 lakh up to ₹2 crore; and the National Commission hears complaints exceeding ₹2 crore. A complaint of ₹75 lakh exceeds ₹50 lakh but is within ₹2 crore, placing it under the original jurisdiction of the State Commission.', 2, 0, 'reviewed', 1);
